window.PM_DATA={"secciones":[{"nombre":"Temeller","grupos":[{"nombre":"Hareket bilimi temelleri","icono":"🧭","temas":[1,2,3,4]},{"nombre":"Değerlendirme","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"Bölgelere göre özel testler","grupos":[{"nombre":"Omuz","icono":"💪","temas":[10,11,12]},{"nombre":"Dirsek, el bileği ve el","icono":"✋","temas":[13,14]},{"nombre":"Omurga ve pelvis","icono":"🦴","temas":[15,16,17]},{"nombre":"Kalça ve diz","icono":"🦵","temas":[18,19,20]},{"nombre":"Ayak bileği ve ayak","icono":"🦶","temas":[21]},{"nombre":"Nörolojik testler","icono":"🧠","temas":[22]}]},{"nombre":"Yaralanmalar ve rehabilitasyon","grupos":[{"nombre":"Omuz","icono":"💪","temas":[23,24,25]},{"nombre":"Spor, tendonlar ve kaslar","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"Ortopedi ve travmatoloji","icono":"🦴","temas":[31,32,33]},{"nombre":"Omurga","icono":"🧍","temas":[34,35,36]},{"nombre":"Nöroloji","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"Tedaviler ve uygulamalar","grupos":[{"nombre":"Teknikler ve fizik tedavi ajanları","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"Klinik vakalar","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"Düzlemler ve Eksenler","lead":"Vücut hareketleri üç temel düzlem ve bunlara dik hareket eksenleriyle tanımlanır. Düzlem–eksen eşleştirmesi her muayenenin, kaydın ve hareket analizinin temelidir.","sheet":{"kind":"basics","items":[{"h":"Başlangıç pozisyonu","t":"Düzlemler ve eksenler anatomik pozisyona göre tanımlanır. EHA ölçümünde 0° nötral sıfır pozisyonudur (önkol orta konumda); ikisi arasındaki farka dikkat edin."},{"h":"Sagittal düzlem","t":"Vücudu sağ ve sol yarıya ayırır. Fleksiyon–ekstansiyon ile ayak bileği dorsifleksiyonu ve plantar fleksiyonu burada olur; hareket ekseni frontal eksendir."},{"h":"Frontal düzlem","t":"Vücudu ön ve arka bölüme ayırır. Abdüksiyon–addüksiyon ve gövdenin yana eğilmesi burada olur; hareket ekseni sagittal eksendir."},{"h":"Transvers düzlem","t":"Vücudu üst ve alt bölüme ayırır. İç ve dış rotasyon, gövde rotasyonu, omzun horizontal fleksiyonu ve ekstansiyonu burada olur; eksen longitudinal eksendir."},{"h":"Düzlem–eksen ilişkisi","t":"Hareket ekseni daima hareket düzlemini dik olarak keser. Düzlem ve ekseni çift olarak öğrenirseniz bilmediğiniz bir hareketi de kolayca sınıflarsınız."},{"h":"Bileşik hareketler","t":"Gerçek hareketler birden fazla düzlemde gerçekleşir. Yürüme veya fırlatma önce düzlem düzlem ayrı gözlenir, sonra birlikte analiz edilir."}]},"keypoints":["Sagittal düzlem = fleksiyon–ekstansiyon, eksen: frontal eksen","Frontal düzlem = abdüksiyon–addüksiyon, eksen: sagittal eksen","Transvers düzlem = rotasyon, eksen: longitudinal eksen","Hareket ekseni daima hareket düzlemine diktir","Hareket analizinde her düzlemi ayrı gözleyin"],"case":{"text":"20 yaşında atlet. Sırtüstü yatarken düz alt ekstremitesini öne kaldırıyor (kalça eklemi). Bu hareketi kaydetmek istiyorsunuz. Hangi düzlemde ve hangi eksen etrafında tanımlarsınız?","answer":"Kalçanın öne kaldırılması fleksiyondur: sagittal düzlemde bir harekettir, eksen frontal eksendir. Frontal düzlemdeki abdüksiyonla karıştırmamak için hareketin vücudu sağ ve sol yarıya ayıran düzlemde olup olmadığına bakın."},"questions":[{"level":"Temel","q":"Abdüksiyon ve addüksiyon hangi düzlemde gerçekleşir?","options":["Sagittal düzlem","Frontal düzlem","Transvers düzlem","Oblik düzlem"],"answer":1,"exp":"Frontal düzlem vücudu ön ve arka bölüme ayırır; abdüksiyon–addüksiyon bu düzlemde olur. Hareket ekseni sagittal eksendir."},{"level":"Temel","q":"Transvers düzlemdeki rotasyonun hareket ekseni hangisidir?","options":["Frontal eksen","Sagittal eksen","Oblik eksen","Longitudinal eksen"],"answer":3,"exp":"Transvers düzlemdeki hareket (rotasyon), bu düzleme dik olan longitudinal eksen etrafında gerçekleşir."},{"level":"Orta","q":"Aşağıdaki hareketlerden hangisi sagittal düzlemde gerçekleşir?","options":["Gövdenin yana eğilmesi","Ayak bileği dorsifleksiyonu","Kalça dış rotasyonu","Omuz abdüksiyonu"],"answer":1,"exp":"Dorsifleksiyon ve plantar fleksiyon, fleksiyon–ekstansiyon gibi sagittal düzlemdedir. Yana eğilme ve abdüksiyon frontal, dış rotasyon transvers düzlemdedir."},{"level":"Orta","q":"Omzun horizontal fleksiyonu hangi düzlemde gerçekleşir?","options":["Sagittal düzlem","Frontal düzlem","Transvers düzlem","Hiçbir düzleme ait değil"],"answer":2,"exp":"Horizontal fleksiyon–ekstansiyonda 90° abdüksiyondaki üst ekstremite transvers düzlemde hareket eder; eksen longitudinal eksendir."},{"level":"Klinik","q":"Omuz dış rotasyonunu kol yanda sarkık, dirsek 90° fleksiyonda ölçüyorsunuz. Hangi düzlem–eksen eşleşmesi doğrudur?","options":["Sagittal düzlem – frontal eksen","Frontal düzlem – sagittal eksen","Transvers düzlem – longitudinal eksen","Transvers düzlem – frontal eksen"],"answer":2,"exp":"Kol yanda sarkıkken omzun iç ve dış rotasyonu transvers düzlemde, humerusun uzun ekseni (longitudinal eksen) etrafında olur."},{"level":"Klinik","q":"Yürüme gözleminde basma fazında pelvis salınım tarafına doğru düşüyor. Esas olarak hangi düzlemi gözlersiniz?","options":["Frontal düzlem","Sagittal düzlem","Transvers düzlem","Düzlem belirlenemez"],"answer":0,"exp":"Pelvisin yana eğilmesi frontal düzlemde bir harekettir, önden veya arkadan gözlenir. M. gluteus medius zayıflığına işaret eder."}],"seccion":"Temeller","grupo":"Hareket bilimi temelleri","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"Biyomekanik","lead":"Biyomekanik, vücut hareketini kuvvet ile hareket arasındaki ilişki üzerinden açıklar. Kaldıraçları, torku ve kütle merkezini bilmek terapötik egzersizlerin yükünü daha doğru ayarlamayı sağlar.","sheet":{"kind":"basics","items":[{"h":"Tork","t":"Eklemi döndüren etki torktur. Kuvvetin büyüklüğü ile kuvvet kolunun (dönme ekseni ile kuvvetin etki çizgisi arasındaki dik uzaklık) çarpımıdır."},{"h":"Üç tip kaldıraç","t":"Birinci sınıfta dayanak, ikinci sınıfta yük, üçüncü sınıfta kuvvet ortadadır. Çoğu kas üçüncü sınıf kaldıraç olarak çalışır: hıza ve hareket açıklığına elverişlidir."},{"h":"Kütle merkezi","t":"Ayakta vücudun kütle merkezi pelviste, S2 vertebranın biraz önündedir. Ağırlık hattı destek yüzeyinin ne kadar içine düşerse postür o kadar stabildir."},{"h":"Kinetik zincir","t":"Açık kinetik zincirde (AKZ) distal segment serbestçe hareket eder, kapalı zincirde (KKZ) zemine veya başka bir yüzeye sabittir. Amaca göre seçilir."},{"h":"Kas kasılma tipleri","t":"Konsantrik kasılmada kas kısalarak, eksantrik kasılmada uzayarak kuvvet üretir. İzometrik kasılma eklem hareketi olmadan gerçekleşir."},{"h":"Klinik uygulama","t":"Ağırlık ne kadar distalde ise kuvvet kolu o kadar uzun, yük o kadar büyüktür. Egzersiz yükü yalnızca ağırlıkla değil, ağırlığın yeriyle de ayarlanabilir."}]},"keypoints":["Tork = kuvvet × kuvvet kolu","Çoğu kas üçüncü sınıf kaldıraçtır (hıza elverişli)","Ağırlık hattı destek yüzeyi içindeyse postür stabildir","İndirme hareketlerinin çoğunu eksantrik kasılma kontrol eder","Yük, ağırlığın yeriyle de ayarlanabilir"],"case":{"text":"65 yaşında kadın, diz osteoartriti. Sırtüstü yatarken ayak bileğine bağlanmış kum torbasıyla SLR egzersizi yapıyor; ancak çabuk yoruluyor ve kompansatuvar hareketler ortaya çıkıyor.","answer":"Ağırlığı bacağın proksimal kısmına koyarsanız kuvvet kolu kısalır; aynı ağırlıkla kalça fleksiyon torku azalır. Ağrıyı ve kompansasyonu izleyerek yükü kademeli artırın; yalnızca tekrar sayısını artırmayın."},"questions":[{"level":"Temel","q":"Hangi kaldıraçta dayanak noktası kuvvet ile yük arasındadır?","options":["Birinci sınıf kaldıraç","İkinci sınıf kaldıraç","Üçüncü sınıf kaldıraç","Tekerlek ve aks"],"answer":0,"exp":"Birinci sınıf kaldıraçta dayanak ortadadır; tipik örnek başın öne-arkaya dengesidir."},{"level":"Temel","q":"Dirseğin m. biceps brachii ile fleksiyonu hangi kaldıraç tipinin tipik örneğidir?","options":["Birinci sınıf kaldıraç","İkinci sınıf kaldıraç","Üçüncü sınıf kaldıraç","Makara"],"answer":2,"exp":"Kasın yapışma yeri (kuvvet), dirsek eklemi (dayanak) ile eldeki ağırlık (yük) arasındadır; bu nedenle üçüncü sınıf kaldıraçtır."},{"level":"Orta","q":"Eklem torkunun büyüklüğünü hangi ikili belirler?","options":["Kuvvetin büyüklüğü ve hız","Kas uzunluğu ve kesit alanı","Kuvvetin büyüklüğü ve kuvvet kolu","Kütle ve sıcaklık"],"answer":2,"exp":"Tork, kuvvetin büyüklüğü ile dönme ekseni–etki çizgisi arasındaki dik uzaklığın (kuvvet kolu) çarpımıdır."},{"level":"Orta","q":"Squat’ın iniş fazında m. quadriceps femoris esas olarak hangi kasılmayı yapar?","options":["Konsantrik kasılma","İzometrik kasılma","İzokinetik kasılma","Eksantrik kasılma"],"answer":3,"exp":"İnişte diz fleksiyona gider; m. quadriceps uzayarak vücut ağırlığını taşır, bu eksantrik kasılmadır."},{"level":"Klinik","q":"Yaşlı bir hasta önündeki bir nesneye uzanırken dengesini kaybediyor. Kütle merkezi açısından en iyi açıklama hangisidir?","options":["Ağırlık hattı destek yüzeyinin kenarına yaklaştı","Destek yüzeyi fazla genişledi","Kütle merkezi fazla alçaldı","Konsantrik kasılma arttı"],"answer":0,"exp":"Öne uzanırken ağırlık hattı destek yüzeyinin ön kenarına yaklaşır ve stabilite azalır."},{"level":"Klinik","q":"Oturur pozisyonda kum torbasıyla diz ekstansiyonu yaptırıyorsunuz. Ağırlığı değiştirmeden yükü nasıl azaltırsınız?","options":["Ağırlığı ayak bileğine koyarım","Ağırlığı bacağın proksimal kısmına koyarım","Hareketi hızlandırırım","Son pozisyonda daha uzun tuttururum"],"answer":1,"exp":"Ağırlığı dize yaklaştırırsanız kuvvet kolu kısalır; aynı ağırlıkla tork azalır."}],"seccion":"Temeller","grupo":"Hareket bilimi temelleri","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"Eklem Hareket Açıklığı (Gonyometri)","lead":"Eklem hareket açıklığı (EHA) ölçümünde eklemin hareket genişliği gonyometreyle derece olarak kaydedilir. Bozukluğun değerlendirilmesinin, hedef belirlemenin ve etkinlik değerlendirmesinin temelidir.","sheet":{"kind":"basics","items":[{"h":"Temel kurallar","t":"Nötral sıfır pozisyonu 0°’dir ve 5°’lik adımlarla kaydedilir. Öncelikle pasif hareketle ölçülür; aktif ölçtüyseniz bunu ayrıca belirtin."},{"h":"Sabit ve hareketli kol","t":"Gonyometrenin iki kolunu ilgili eklem için tanımlanmış sabit ve hareketli segmente, merkezini ise eklemin hareket eksenine hizalayın."},{"h":"Referans değerler","t":"Genel referans değerler (nötral sıfır yöntemi): omuz fleksiyon ve abdüksiyon 180°, dirsek fleksiyon 150°, kalça fleksiyon 120°, abdüksiyon 45°, diz fleksiyon 135°. Daima karşı tarafla karşılaştırın."},{"h":"Kompansatuvar hareketler","t":"Gövdenin geriye eğilmesi veya pelvisin tiltı olduğundan büyük değer verir. Proksimal segmenti sabit tutun ve kompansasyonu dışlayarak ölçün."},{"h":"Son his (end feel)","t":"Hareket sonundaki direncin niteliğini (kemik, yumuşak doku, bağ dokusu) ve ağrıyı kontrol edin; buradan hareketi kısıtlayan faktörü çıkarın."},{"h":"Kayıt ve tekrar ölçüm","t":"Ölçüm pozisyonunu, pasif mi aktif mi ölçüldüğünü ve ağrının başladığı açıyı kaydedin. Aynı pozisyon ve yöntemle yapılan tekrar ölçüm karşılaştırılabilir."}]},"keypoints":["0° nötral sıfır pozisyonudur, 5°’lik adımlarla kaydedin","Esas olarak pasif ölçüm; aktifse belirtin","Proksimal segmenti sabitleyin, kompansasyonu dışlayın","Referans değer yalnızca yol göstericidir, daima karşı tarafla karşılaştırın","Son his ve ağrıdan kısıtlayıcı faktörü çıkarın"],"case":{"text":"40 yaşında erkek, periartritis humeroskapularis. Omuz fleksiyonu ölçülürken gövde geriye eğiliyor ve ölçülen değer neredeyse sağlam taraftakiyle aynı çıkıyor.","answer":"Değer muhtemelen gövde ekstansiyonu kompansasyonu nedeniyle olduğundan büyüktür. Gövdeyi sabitleyip yeniden ölçün; ağrının başladığı açıyı ve son hissi de kaydedin. Kompansasyonla ölçülen değere dayanarak düzelme olduğunu söylemeyin."},"questions":[{"level":"Temel","q":"Omuz fleksiyonunun referans değeri kaçtır?","options":["90°","120°","150°","180°"],"answer":3,"exp":"Omuz fleksiyonu ve abdüksiyonunun referans değeri her ikisi için de 180°’dir."},{"level":"Temel","q":"Ayak bileği dorsifleksiyonunun referans değeri kaçtır?","options":["10°","20°","30°","45°"],"answer":1,"exp":"Ayak bileği dorsifleksiyonunun referans değeri 20°’dir (plantar fleksiyon 50°). Daima orta konumdan (0°) ölçün."},{"level":"Orta","q":"EHA ölçümünün doğru temel ilkesi hangisidir?","options":["Aktif hareketle ölçülür","1°’lik adımlarla kaydedilir","Nötral sıfır pozisyonu 0°’dir","Karşı tarafla karşılaştırmak gerekmez"],"answer":2,"exp":"Nötral sıfır pozisyonu 0°’dir; esas olarak pasif, 5°’lik adımlarla ölçülür ve karşı tarafla karşılaştırılır."},{"level":"Orta","q":"Hareket sonunda sert, aniden duran kemik son his neyi gösterir?","options":["Kas spazmını","Kemik-kemik temasını","Eklem kapsülünün gerilmesini","Yumuşak dokuların temasını"],"answer":1,"exp":"Kemik son his, kemikler çarpıştığında hissedilen duruştur; normalde dirsek ekstansiyonu tipik örnektir."},{"level":"Klinik","q":"Kalça abdüksiyonu ölçülürken pelvis eğiliyor ve olduğundan büyük değer elde ediyorsunuz. İlk ne yaparsınız?","options":["Değeri bu şekilde kaydederim","Pelvisi sabitler ve yeniden ölçerim","Aktif hareketle ölçerim","Ölçümü bırakırım"],"answer":1,"exp":"Pelvis kompansasyonu abdüksiyon açısını olduğundan büyük gösterir. Pelvisi sabitleyin ve yeniden ölçün."},{"level":"Klinik","q":"Diz ameliyatı sonrası pasif fleksiyonun sonunda ağrı ortaya çıkıyor. En uygun kayıt hangisidir?","options":["Yalnızca açıyı kaydederim","Sağlam tarafın değerini kaydederim","Ağrı sürdükçe kayıt yapmam","Ağrının başladığı açıyı da kaydederim"],"answer":3,"exp":"EHA değerinin yanında ağrının başladığı açı ve niteliği, kısıtlayıcı faktörün değerlendirilmesine ve yeniden değerlendirmeye yardımcı olur."}],"seccion":"Temeller","grupo":"Hareket bilimi temelleri","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"Kas Kuvveti Testi 0–5","lead":"Manuel kas testi (MKT) yerçekimi ve manuel direnç yardımıyla kas kuvvetini 0–5 arası altı dereceli bir skalada değerlendirir. Zayıflığın derecesini ve dağılımını gösterir.","sheet":{"kind":"basics","items":[{"h":"Altı derece","t":"0: kasılma yok; 1: yalnızca kasılma; 2: yerçekimi elimine edilmiş tam EHA; 3: yerçekimine karşı tam EHA; 4: orta dirence karşı; 5: maksimal dirence karşı, normal kuvvet."},{"h":"Test sırası","t":"Önce yerçekimine karşı pozisyonda 3. derecenin başarılıp başarılmadığına bakın. Başarılıyorsa dirençle 4 ve 5’e karar verin; başarılmıyorsa yerçekimsiz pozisyonda 2 veya altına."},{"h":"Direnç verme","t":"Direnci hareket yönüne karşı, segmentin distal kısmına verin. Ani değil kademeli artırın ve hastanın tutup tutamadığını gözleyin."},{"h":"Sabitleme ve kompansasyon","t":"Proksimal segmenti sabitleyin ve başka kasların kompansatuvar hareketi olup olmadığını izleyin. Hareket kompansasyonla yapıldıysa o dereceyi veremezsiniz."},{"h":"3. derecenin anlamı","t":"3. derece, segmentin kendi ağırlığına karşı hareket ettirilebildiği sınırdır: «yerçekimi sınırı». Fonksiyonel hareketlerin değerlendirilmesinde de yol göstericidir."},{"h":"Sınırlılıklar","t":"MKT öznel unsurlar içerir; 4’ün üzerindeki farkları zor ayırt eder. Ağrı veya patolojik kas tonusu varsa bunu da bulgu ile birlikte kaydedin."}]},"keypoints":["Önce yerçekimine karşı 3. dereceyi kontrol edin","3. derece «yerçekimi sınırı»dır","Direnci harekete karşı, distalden verin","Proksimali sabitleyin, kompansasyonu gözden kaçırmayın","Santral sinir sistemi hastalığında MKT tek ölçüm olmasın"],"case":{"text":"70 yaşında erkek, hastanede yatışa bağlı inaktivite. Oturur pozisyonda dizini tam hareket açıklığında ekstansiyona getiriyor; ancak bacağın distal kısmına verilen hafif dirence artık dayanamıyor.","answer":"Yerçekimine karşı tam EHA’da hareket ediyor, dirence karşı edemiyor; bu nedenle 3. derece. Ani güçlü direnç vermeyin ve gövdenin geriye yatması gibi kompansasyonlara dikkat edin."},"questions":[{"level":"Temel","q":"«Kasılma görülür ve palpe edilir ama eklem hareketi yoktur» hangi derecedir?","options":["0. derece","1. derece","2. derece","3. derece"],"answer":1,"exp":"1. derecede kas kasılması görülür veya palpe edilir, ancak eklem hareketi oluşmaz."},{"level":"Temel","q":"Yerçekimine karşı tam EHA olup dirence karşı olmayan hangi derecedir?","options":["4. derece","2. derece","3. derece","5. derece"],"answer":2,"exp":"3. derecede yerçekimine karşı tam EHA’da hareket eder; bu «yerçekimi sınırı»dır."},{"level":"Orta","q":"MKT sırasında genellikle ilk olarak hangi derece kontrol edilir?","options":["1. derece","5. derece","0. derece","3. derece"],"answer":3,"exp":"Önce yerçekimine karşı pozisyonda 3. dereceye bakılır; direnç verilip verilmeyeceği veya yerçekimsiz pozisyona geçilip geçilmeyeceği buna bağlıdır."},{"level":"Orta","q":"MKT sırasında direnci nereye verirsiniz?","options":["Doğrudan eklemin üzerine","Segmentin proksimal kısmına","Segmentin distal kısmına","Sabitlenen vücut kısmına"],"answer":2,"exp":"Direnç hareket yönüne karşı, kuvvet kolunun daha uzun olduğu segmentin distal kısmına verilir."},{"level":"Klinik","q":"Yan yatışta alt ekstremiteyi abdüksiyonla kaldıramıyor, sırtüstü yatışta ise tam EHA’da abdüksiyon yapıyor. Hangi derece?","options":["1. derece","2. derece","3. derece","4. derece"],"answer":1,"exp":"Yerçekimine karşı pozisyonda (yan yatış) yapamıyor, yerçekimsiz (sırtüstü) tam EHA’da yapabiliyor: 2. derece."},{"level":"Klinik","q":"Belirgin spastisitesi olan hemiparetik bir hastanın üst ekstremite kuvvetini ölçecekseniz en iyi yaklaşım hangisidir?","options":["MKT tek başına zor değerlendirilir","Hedef 5. derece olmalı","Güçlü dirençle karar veririm","Sağlam tarafı test etmeye gerek yok"],"answer":0,"exp":"Santral sinir sistemi hastalığında kas tonusu ve sinerjiler nedeniyle MKT koşulları sağlanmaz; paralizi değerlendirmesi için başka bir skala da kullanın."}],"seccion":"Temeller","grupo":"Hareket bilimi temelleri","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"Anamnez","lead":"Anamnezde yakınmaların seyri, niteliği ve hastanın yaşam koşulları sorgulanır ve bir hipotez kurulur. Bu, sonraki testlerin seçimini ve güvenlik taramasını belirler.","sheet":{"kind":"basics","items":[{"h":"Amaç","t":"Ana yakınma ve seyirden bir hipotez kurulur ve testler önceliklendirilir. Bu sırada hekime yönlendirme gerektiren uyarı işaretleri de taranır."},{"h":"Ana yakınma ve öykü","t":"Ana yakınmayı hastanın sözleriyle kaydedin. Başlangıcı ve tetikleyiciyi (travma veya yavaş başlangıç), ardından seyri (düzeliyor, kötüleşiyor, değişmiyor) sorun."},{"h":"Ağrı değerlendirmesi","t":"Ağrının yerini, niteliğini, şiddetini (ör. NRS), artıran ve azaltan faktörleri, gün içi değişimini ve gece ağrısını netleştirin."},{"h":"Özgeçmiş, ilaçlar","t":"Geçirilmiş hastalıkları, ameliyatları, eşlik eden hastalıkları ve ilaçları sorun. Antikoagülan ve steroid kullanımı tedavide dikkat gerektirir."},{"h":"Yaşam koşulları","t":"İşini, ailedeki rolünü, yaşadığı ortamı ve aktivite düzeyini sorun. Hastanın ve ailesinin ihtiyaçlarını ve hedeflerini hedef belirlemeye dahil edin."},{"h":"Sorgulama tekniği","t":"Açık uçlu sorularla başlayın, kapalı sorularla netleştirin. Teknik terimlerden kaçının; özetleyerek geri söylerseniz yanlış anlamaları önlersiniz."}]},"keypoints":["Ana yakınmayı hastanın kendi sözleriyle kaydedin","Tetikleyiciyi ve seyri mutlaka sorun","Uyarı işaretlerini tarayın: gece ağrısı, kilo kaybı","İlaçlar (ör. antikoagülan) dikkat gerektirir","Açık uçlu soruyla başlayın, kapalıyla netleştirin"],"case":{"text":"55 yaşında erkek, 2 aydır süren bel ağrısı. Şöyle anlatıyor: «Son zamanlarda ağrıdan gece de uyuyamıyorum. Hiçbir şey yapmadım ama yine de 5 kilo verdim.»","answer":"İstirahatle geçmeyen gece ağrısı ve açıklanamayan kilo kaybı kırmızı bayraktır. Egzersiz tedavisine başlamadan önce durumu bildirin ve hekimle görüşün. Anamnezde bulunan uyarı işaretini sonraki bir test sonucu geçersiz kılmamalıdır."},"questions":[{"level":"Temel","q":"İlk olarak neyi sorgular ve hastanın kendi sözleriyle kaydedersiniz?","options":["Geçirilmiş hastalıklar","Ana yakınma","Soygeçmiş","İlaçlar"],"answer":1,"exp":"Ana yakınma hastayı en çok rahatsız eden şeydir; yorum katmadan, kendi sözleriyle kaydedilir."},{"level":"Temel","q":"Hastadan ağrı şiddetini 0–10 arası bir sayıyla belirtmesini hangi yöntemle istersiniz?","options":["MKT","EHA","NRS","GYA"],"answer":2,"exp":"NRS (sayısal derecelendirme ölçeği) ağrı şiddetini 0–10 arası bir sayıyla ifade eder."},{"level":"Orta","q":"Hangisi açık uçlu bir sorudur?","options":["«Sağ tarafınız mı ağrıyor?»","«Gece ağrıyor mu?»","«İlaç kullanıyor musunuz?»","«Genellikle ne zaman ağrıyor?»"],"answer":3,"exp":"Açık uçlu soruya evet veya hayır ile cevap verilemez; böylece hastadan daha fazla bilgi alırsınız."},{"level":"Orta","q":"Tedavide dikkat gerektirdiği için anamnezde özellikle hangi bilgiyi netleştirmelisiniz?","options":["Antikoagülan kullanımı","Dominant el","İşe gidiş şekli","Hobiler"],"answer":0,"exp":"Antikoagülan kanama ve hematom riski taşır; bu nedenle örneğin manuel tekniklerde dikkat gerektirir."},{"level":"Klinik","q":"Bel ağrılı hasta: «Ağrıdan gece de uyuyamıyorum ve 5 kilo verdim.» En uygun yaklaşım hangisidir?","options":["Hemen egzersiz tedavisine başlarım","Sıcak uygulamayla seyri izlerim","Bildirir ve hekimle görüşürüm","Bir sonraki seansa kadar beklerim"],"answer":2,"exp":"İstirahatle geçmeyen gece ağrısı ve açıklanamayan kilo kaybı kırmızı bayraktır; tedaviden önce hekimle görüşün."},{"level":"Klinik","q":"70 yaşında, osteoporozlu kadın. Düştüğünden beri kalçası ağrıyor ve yürüyemiyor. İlk neyi düşünürsünüz?","options":["Kas zayıflığına bağlı ağrı","Kırık olasılığı","Artrozun kötüleşmesi","Psikolojik faktörler"],"answer":1,"exp":"Osteoporozda düşme sonrası ağrı ve yürüyememe varsa kırığı düşünün; önce tıbbi değerlendirme gelir."}],"seccion":"Temeller","grupo":"Değerlendirme","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"Kırmızı Bayraklar","lead":"Kırmızı bayraklar ciddi, gizli bir hastalığa işaret edebilen uyarı bulgularıdır. Böyle bir bulgu fark ederseniz fizyoterapiye devam etmeden önce hekimle görüşün.","sheet":{"kind":"basics","items":[{"h":"Tanım","t":"Acil bir patolojiye (tümör, enfeksiyon, kırık, kauda ekina sendromu) işaret eden bulgulardır. Tek başına daha az, birlikte görüldüklerinde daha fazla önem taşırlar."},{"h":"Tümör","t":"Geçirilmiş kanser öyküsünü, açıklanamayan kilo kaybını ve istirahatle de geçmeyen gece ağrısını sorun. Yaşı ve genel durumu da göz önünde bulundurun."},{"h":"Enfeksiyon","t":"Ateşle birlikte olan sırt ve bel ağrısına, immünsüpresyona, yakın zamanda geçirilmiş enfeksiyona veya invaziv girişime dikkat edin."},{"h":"Kırık","t":"Ciddi travmadan sonra, osteoporozda ise küçük bir düşme sonrası ağrıda bile kırığı düşünün. Uzun süreli steroid kullanımını da sorun."},{"h":"Kauda ekina sendromu","t":"Mesane ve bağırsak fonksiyon bozukluğu, eyer bölgesinde duyu kaybı ve ilerleyici alt ekstremite güçsüzlüğü acil durumdur: hemen hekime haber verin."},{"h":"Yapılacaklar","t":"Bulguyu ve seyri kaydedin, bildirin ve hekimle görüşün. Hastayı korkutmayın; tıbbi değerlendirmenin neden gerekli olduğunu sakince açıklayın."}]},"keypoints":["İstirahatle de geçmeyen gece ağrısı uyarı işaretidir","Açıklanamayan kilo kaybı tümöre işaret edebilir","Mesane-bağırsak bozukluğu, eyer bölgesi duyu kaybı: acil","Travma veya osteoporoz varsa kırığı düşünün","Kırmızı bayrakta tedaviden önce hekimle görüşün"],"case":{"text":"45 yaşında kadın, bel ağrısı ve sağ alt ekstremite ağrısı. Bu sabahtan beri idrar yapmakta zorlandığını ve anüs çevresinde uyuşma olduğunu anlatıyor.","answer":"Mesane-bağırsak bozukluğu ve eyer bölgesi duyu bozukluğu kauda ekina sendromuna işaret eder. Muayeneye veya egzersizlere devam etmeyin, hemen hekime haber verin. «Bekleyip izleyelim» yaklaşımından burada kaçınılmalıdır."},"questions":[{"level":"Temel","q":"Sırt ve bel ağrısında hangisi kırmızı bayraktır?","options":["Hareketle artan bel ağrısı","Açıklanamayan kilo kaybı","Uzun oturmayla artan ağrı","Egzersiz sonrası kas ağrısı"],"answer":1,"exp":"Açıklanamayan kilo kaybı kırmızı bayraklardan biridir; tümöral bir hastalığa işaret edebilir."},{"level":"Temel","q":"Kırmızı bayrak fark edildiğinde doğru yaklaşım hangisidir?","options":["Düşük yoğunlukla devam ederim","Fizik tedavi ajanlarına geçerim","Bir sonraki seansa kadar beklerim","Tedaviden önce hekimle görüşürüm"],"answer":3,"exp":"Kırmızı bayrak varsa fizyoterapiye devam etmeden önce hekimle görüşün."},{"level":"Orta","q":"Hangi bulgu çifti kauda ekina sendromuna işaret eder?","options":["Mesane-bağırsak bozukluğu ve eyer duyu kaybı","Boyun ağrısı ve omuz sertliği","Diz şişliği ve merdiven çıkarken ağrı","Gece omuz ağrısı ve kaldırma kısıtlılığı"],"answer":0,"exp":"Mesane-bağırsak bozukluğu ve eyer bölgesinde (perine, anüs çevresi) duyu kaybı, kauda ekina basısının acil işaretidir."},{"level":"Orta","q":"Hangi durumda en çok kırığı düşünürsünüz?","options":["Ofis işi sonrası bel gerginliği","Egzersiz sonrası kas ağrısı","Osteoporozlu hastada düşme sonrası sırt ağrısı","Soğuk günlerde ortaya çıkan diz sertliği"],"answer":2,"exp":"Osteoporozda küçük bir kuvvetle bile kemik kırılabilir; bu nedenle düşme sonrası ağrıda kırığı düşünün."},{"level":"Klinik","q":"Bel ağrılı hasta: «Bu sabahtan beri idrar yapmakta zorlanıyorum ve anüs çevresi uyuşuyor.» Ne yaparsınız?","options":["Muayeneyi tamamlarım","Gövde egzersizlerine başlarım","Hemen hekime haber veririm","Bir hafta seyri izlerim"],"answer":2,"exp":"Mesane-bağırsak bozukluğu ve eyer bölgesi duyu bozukluğu kauda ekina sendromuna işaret eder: hemen hekime haber verin."},{"level":"Klinik","q":"68 yaşında erkek, kanser öyküsü var. Bir aydır istirahatle de geçmeyen gece sırt ağrısı var. Değerlendirmeniz nedir?","options":["Postüre bağlı ağrı","Hekimle görüşme gerektiren bulgu","Kuvvetlendirmeyle düzelen ağrı","Sıcak uygulamayla izlenebilir ağrı"],"answer":1,"exp":"Kanser öyküsü ile istirahatle geçmeyen gece ağrısı birlikte metastazı da dışlamaz; bu nedenle hekimle görüşme gerekir."}],"seccion":"Temeller","grupo":"Değerlendirme","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"Postür Değerlendirmesi","lead":"Postür değerlendirmesinde ayakta ve oturur pozisyonda vücudun dizilimi gözlenir ve soruna dair ipuçları aranır. Belirtilerle ilişkisi her zaman başka testlerle doğrulanmalıdır.","sheet":{"kind":"basics","items":[{"h":"Amaç","t":"Postür sapmaları değerlendirilir; kas kısalığı, kas zayıflığı ve ağrıyla ilişkileri hakkında hipotez kurulur."},{"h":"Yandan referans","t":"İdeal duruşta ağırlık hattı kulak memesinden, akromiyondan, trokanter majörden, diz ekleminin ön kısmından (patellanın arkası) ve dış malleolün önünden geçer."},{"h":"Arkadan bakış","t":"Başın eğimine, omuz ve pelvis yüksekliğine, omurganın yana sapmasına ve alt ekstremite asimetrisine bakın. Gerekirse öne eğilmede de kontrol edin."},{"h":"Hatalı postürler","t":"Kifotik (yuvarlak) sırt, öne tilt baş postürü, artmış pelvik tilt ve lomber lordozlu postür ve düz sırt bunlardandır. İlgili kasların kısalığı ve zayıflığıyla birlikte değerlendirin."},{"h":"Yorumlama","t":"Birçok kişide belirtisiz postür sapması vardır; bu yüzden bulgu tek başına ağrının nedenini kanıtlamaz. EHA ve kas kuvveti testiyle doğrulayın."},{"h":"Kayıt","t":"Gözlem yönünü, vücut pozisyonunu ve referans noktalarının konumunu kaydedin. Karşılaştırma için fotoğrafları daima aynı koşullarda çekin."}]},"keypoints":["Yandan, arkadan ve önden gözleyin","Ağırlık hattı kulak memesi, akromiyon ve trokanter majörden geçer","Arkadan omuz ve pelvis yüksekliğindeki taraf farkına bakın","Öne eğilmede kosta kamburu yapısal skolyoza işaret eder","Postüre dayanarak ağrının nedenini söylemeyin"],"case":{"text":"30 yaşında kadın, ofis çalışanı. Boyun ağrısı var; yandan bakıldığında kulak memesi belirgin şekilde akromiyonun önünde.","answer":"Bu, öne tilt baş postürüdür. Ancak postüre dayanarak nedeni söylemeyin: servikal EHA’yı, belirtiyi tetikleyen hareketleri ve nörolojik bulguları (uyuşma, güçsüzlük) değerlendirin. Nörolojik belirti varsa hekimle görüşün."},"questions":[{"level":"Temel","q":"İdeal duruşta yandan bakıldığında ağırlık hattı nereden geçer?","options":["Burun ucundan","Skapulanın alt açısından","Kulak memesinden","Kalkaneusun arka kenarından"],"answer":2,"exp":"İdealde ağırlık hattı kulak memesinden, akromiyondan, trokanter majörden, dizin ön kısmından ve dış malleolün önünden geçer."},{"level":"Temel","q":"Arkadan görünümde esas olarak neyi değerlendirirsiniz?","options":["Öne tilt baş postürünü","Omuz ve pelvis yükseklik farkını","Lomber lordozun derecesini","Diz hiperekstansiyonunu"],"answer":1,"exp":"Arkadan taraf farklarına bakılır: omuz ve pelvis yüksekliği, omurganın yana sapması."},{"level":"Orta","q":"İdeal duruşta yandan görünümdeki ağırlık hattı için hangisi doğrudur?","options":["Dış malleolün arkasından geçer","Diz ekleminin arkasından geçer","Skapulanın iç kenarından geçer","Trokanter majörden geçer"],"answer":3,"exp":"Ağırlık hattı trokanter majörden, diz ekleminin ön kısmından ve dış malleolün önünden geçer."},{"level":"Orta","q":"Postür değerlendirmesinin doğru yorumu hangisidir?","options":["Sapma ağrının nedenidir","İlişkiyi başka testle doğrularım","Tek yönden gözlemek yeterlidir","Fotoğrafları hep farklı koşullarda çekerim"],"answer":1,"exp":"Postür sapması belirtisiz kişilerde de görülür; ilişkiyi EHA ve kas kuvveti testiyle doğrulayın."},{"level":"Klinik","q":"Boyun ağrılı hastada kulak memesi belirgin şekilde akromiyonun önünde. En uygun sonraki adım hangisidir?","options":["Servikal EHA ve nörolojik bulguları test ederim","Yalnızca postür önerisi veririm","Hemen traksiyon uygularım","Yalnızca seyri izlerim"],"answer":0,"exp":"Öne tilt baş postürü yalnızca bir ipucudur. EHA’yı ve nörolojik bulguları test edin, belirtilerle ilişkisini değerlendirin."},{"level":"Klinik","q":"Arkadan omuz ve pelvis yükseklik farkı, öne eğilmede tek taraflı kosta kamburu görülüyor. Ne düşünürsünüz?","options":["Öne tilt baş postürü","Kifotik sırt","Yapısal skolyoz","Düz sırt"],"answer":2,"exp":"Öne eğilmede görülen kosta kamburu, vertebra rotasyonuyla seyreden yapısal skolyoza işaret eder; tıbbi değerlendirme gerekir."}],"seccion":"Temeller","grupo":"Değerlendirme","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"Yürüme Analizi","lead":"Yürüme analizinde yürüme siklusunun her fazında eklem hareketleri ve kas aktivitesi gözlenir ve sorun belirlenir. Düşme önleme ve hareketin iyileştirilmesi için yol gösterir.","sheet":{"kind":"basics","items":[{"h":"Yürüme siklusu","t":"Bir siklus, bir ayağın ilk temasından aynı ayağın bir sonraki temasına kadar sürer. Basma ve salınım fazlarına ayrılır ve iki çift destek dönemi içerir."},{"h":"Fazlar","t":"Basma fazı: ilk temas, yüklenme yanıtı, orta ve terminal basma, salınım öncesi. Salınım fazı: erken, orta ve terminal salınım."},{"h":"Gözlem sırası","t":"Önden, arkadan ve yandan gözleyin; her seferinde bir ekleme veya faza odaklanın. Hızı, adım uzunluğunu, ritmi ve yardımcı cihazı da kaydedin."},{"h":"Tipik patolojik yürüyüşler","t":"Trendelenburg yürüyüşü (m. gluteus medius), steppage yürüyüşü (düşük ayak kompansasyonu), sirkümdüksiyon, donma (freezing), küçük adımlı yürüyüş."},{"h":"Kas aktivitesi","t":"Yüklenme yanıtında m. quadriceps diz fleksiyonunu, m. tibialis anterior ayağın inişini eksantrik olarak frenler. Terminal basmada m. triceps surae çalışır."},{"h":"Ölçülebilir testler","t":"10 metre yürüme testi ve TUG testiyle hızı ve mobiliteyi sayısallaştırabilirsiniz. Gözlemle birlikte düşme riskini de değerlendirirsiniz."}]},"keypoints":["Bir siklus: ilk temastan aynı ayağın sonraki temasına","Basma fazı yakl. %60, salınım fazı yakl. %40","Üç yönden gözleyin, her seferinde tek noktaya","Trendelenburg yürüyüşünde m. gluteus mediusu düşünün","Steppage yürüyüşü düşük ayağın (zayıf m. tibialis anterior) kompansasyonudur"],"case":{"text":"60 yaşında erkek, n. peroneus felci. Salınım fazında kalça ve dizi belirgin fleksiyona getirip ayağını yükseğe kaldırarak adım atıyor. Giderek daha sık takılıyor.","answer":"Bu, düşük ayağı kompanse eden steppage yürüyüşüdür. Dorsifleksiyon kas kuvvetini, duyuyu ve düşme riskini değerlendirin. Ortezi tek başınıza karar vermeden hekim ve ortez-protez teknisyeniyle birlikte değerlendirin."},"questions":[{"level":"Temel","q":"Basma fazı bir yürüme siklusunun yaklaşık ne kadarını oluşturur?","options":["Yakl. %40","Yakl. %50","Yakl. %60","Yakl. %80"],"answer":2,"exp":"Normal yürüyüşte basma fazı yaklaşık %60, salınım fazı yaklaşık %40’tır."},{"level":"Temel","q":"Vücut ağırlığının tek bacakta taşındığı ve ağırlık merkezinin en yüksekte olduğu faz hangisidir?","options":["İlk temas","Orta basma","Salınım öncesi","Orta salınım"],"answer":1,"exp":"Orta basmada vücut destek bacağının üzerinden geçer; ağırlık merkezi bu sırada en yüksektedir."},{"level":"Orta","q":"Yüklenme yanıtında diz fleksiyonunu eksantrik olarak frenleyen kas hangisidir?","options":["M. quadriceps femoris","Hamstring kasları","M. iliopsoas","M. triceps surae"],"answer":0,"exp":"Yüklenme yanıtında diz şoku emmek için hafif fleksiyona gider; bunu m. quadriceps eksantrik olarak frenler."},{"level":"Orta","q":"Trendelenburg yürüyüşünde hangi kasın zayıflığından şüphelenirsiniz?","options":["M. gluteus maximus","M. quadriceps femoris","M. tibialis anterior","M. gluteus medius"],"answer":3,"exp":"M. gluteus medius zayıf olduğunda basma fazında salınım tarafındaki pelvis düşer: Trendelenburg belirtisi."},{"level":"Klinik","q":"Salınım fazında kalça ve dizi aşırı fleksiyona getiriyor, ayağını yükseğe kaldırarak adım atıyor. Neden ne olabilir?","options":["M. quadriceps zayıflığı","M. tibialis anterior zayıflığı","M. gluteus medius zayıflığı","M. gluteus maximus zayıflığı"],"answer":1,"exp":"M. tibialis anterior zayıflığı nedeniyle ayak düşer; parmaklar takılmasın diye ayağını yükseğe kaldırır: steppage yürüyüşü."},{"level":"Klinik","q":"Parkinson hastasında yürümeye başlarken ve dönerken ayak sanki yere yapışıyor, harekete geçemiyor. Bu nedir?","options":["Sirkümdüksiyon yürüyüşü","Steppage yürüyüşü","Donma (freezing)","Ördekvari yürüyüş"],"answer":2,"exp":"Donma Parkinson hastalığına özgüdür; özellikle yürümeye başlarken, dönerken ve dar alanlarda ortaya çıkar."}],"seccion":"Temeller","grupo":"Değerlendirme","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"Nörolojik Muayene","lead":"Nörolojik muayenede duyu, kas kuvveti ve refleksler segment segment test edilir; lezyonun yeri ve seviyesi çıkarılır. İlerleyici nörolojik belirtilerin erken fark edilmesi için de vazgeçilmezdir.","sheet":{"kind":"basics","items":[{"h":"Amaç","t":"Duyu, kas kuvveti ve refleks bulgularını birlikte değerlendirerek lezyonun periferik sinirde, sinir kökünde, omurilikte veya beyinde olup olmadığına karar verilir."},{"h":"Duyu muayenesi","t":"Dokunma, ağrı, ısı, pozisyon ve vibrasyon duyusunu test edin; dermatomlar boyunca iki tarafı ve proksimal ile distal kısmı karşılaştırın."},{"h":"İndikatör kaslar","t":"C5: omuz abdüksiyonu; C6: el bileği dorsifleksiyonu (ekstansiyon); C7: dirsek ekstansiyonu; L4: ayak bileği dorsifleksiyonu; L5: başparmak ekstansiyonu; S1: ayak bileği plantar fleksiyonu."},{"h":"Derin tendon refleksleri","t":"Temel refleksler: biseps refleksi (C5), brakioradyalis refleksi (C6), triseps refleksi (C7), patella refleksi (L4), Aşil refleksi (S1)."},{"h":"Üst ve alt motor nöron","t":"Üst motor nöron lezyonunda artmış tendon refleksleri ve patolojik refleksler, alt motor nöron lezyonunda azalmış veya kayıp refleksler ve kas atrofisi görülür."},{"h":"Uyarı","t":"Hızla kötüleşen kas kuvveti, yayılan duyu bozukluğu veya mesane-bağırsak bozukluğunda gecikmeden hekime haber verin. Bulguları zaman içinde izleyerek kaydedin."}]},"keypoints":["Duyu, kuvvet ve refleksleri daima iki tarafta karşılaştırın","Patella refleksi: L4, Aşil refleksi: S1","L5’i başparmak ekstansiyon kuvveti ve duyuya göre değerlendirin","Artmış refleks ve patolojik refleks: üst motor nöron","İlerleyici kas güçsüzlüğünde hemen hekime haber verin"],"case":{"text":"50 yaşında erkek, bel ağrısı, sağ bacağın dış yüzünden ayak sırtına kadar uyuşma. Sağda başparmak ekstansiyonu zayıf; patella ve Aşil reflekslerinde taraf farkı yok.","answer":"L5 sinir kökü lezyonu olasıdır. L5’in tipik bir tendon refleksi yoktur; bu nedenle duyu ve başparmak ekstansiyon kuvvetine göre karar verirsiniz. Kas kuvveti kötüleşirse veya mesane-bağırsak bozukluğu olursa hemen hekime haber verin."},"questions":[{"level":"Temel","q":"Hangi patolojik refleks üst motor nöron lezyonuna işaret eder?","options":["Patella refleksi","Abdominal deri refleksi","Babinski refleksi","Kornea refleksi"],"answer":2,"exp":"Babinski refleksi patolojik bir reflekstir: taban uyarıldığında başparmak dorsifleksiyona gider; üst motor nöron lezyonuna işaret eder."},{"level":"Temel","q":"Hangi muayenede dermatomlar boyunca iki tarafı karşılaştırırsınız?","options":["Tendon refleksleri","Duyu muayenesi","MKT","EHA ölçümü"],"answer":1,"exp":"Dermatom, her segmentin innerve ettiği deri alanıdır; duyu muayenesinde taraflar arası ve proksimal-distal karşılaştırılır."},{"level":"Orta","q":"Aşil refleksi esas olarak hangi segmenti yansıtır?","options":["L3","L4","L5","S1"],"answer":3,"exp":"Aşil refleksi esas olarak S1, patella refleksi esas olarak L4 segmentini yansıtır."},{"level":"Orta","q":"Alt motor nöron lezyonunun bulgusu hangisidir?","options":["Artmış tendon refleksleri","Pozitif patolojik refleks","Kas atrofisi","Spastisite"],"answer":2,"exp":"Alt motor nöron lezyonunda azalmış veya kayıp tendon refleksleri, kas atrofisi ve azalmış kas tonusu görülür."},{"level":"Klinik","q":"Bacağın dış yüzünden ayak sırtına uyuşma, zayıf başparmak ekstansiyonu var, reflekslerde taraf farkı yok. Lezyon seviyesi hangisidir?","options":["L3","L4","L5","S1"],"answer":2,"exp":"Bacağın dış yüzünden ayak sırtına uzanan duyu ve başparmak ekstansiyonu L5 bulgusudur. L5’in tipik bir tendon refleksi yoktur."},{"level":"Klinik","q":"Boyun ağrısı ve iki elde uyuşmanın yanında alt ekstremitede tendon refleksleri artmış, Babinski pozitif. Ne düşünürsünüz?","options":["Servikal omurilik lezyonu (miyelopati)","Tek bir sinir kökü lezyonu","Karpal tünel sendromu","Miyofasiyal ağrı"],"answer":0,"exp":"Alt ekstremitede artmış refleksler ve patolojik refleks üst motor nöron lezyonunu gösterir; servikal omurilik basısını düşünün ve hekime yönlendirin."}],"seccion":"Temeller","grupo":"Değerlendirme","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"Rotator Manşet","lead":"Rotator manşet, omuz eklemini stabilize eden dört kasın tendonlarından oluşur. Hangi kasın etkilendiğini testlerle ayırt etmek, muayenenin ve fizyoterapinin başlangıç noktasıdır.","sheet":{"kind":"tests","tests":[{"name":"Jobe testi","alias":"boş kutu testi","steps":"Hasta kolunu skapula düzleminde 90° abdüksiyonda, iç rotasyonda, başparmak aşağı bakacak şekilde tutar; fizyoterapist yukarıdan aşağıya direnç verir.","positive":"Ağrı veya zayıflık: kolu dirence karşı tutamaz","tissue":"m. supraspinatus","point":"Ağrıyı ve zayıflığı ayrı kaydedin. Sıkışmada da ağrı oluşturabilir."},{"name":"Dirençli dış rotasyon","alias":"","steps":"Dirsek 90° fleksiyonda, kol gövde yanında; hasta dışa rotasyon yapar, fizyoterapist önkola içe doğru direnç verir.","positive":"Dış rotasyonda ağrı veya sağlam tarafa göre belirgin düşük kuvvet","tissue":"m. infraspinatus ve m. teres minor","point":"Pasif verilen dış rotasyonu koruyamıyorsa (dış rotasyon lag) büyük yırtığı düşünün."},{"name":"Lift-off testi","alias":"Gerber lift-off testi","steps":"Hastanın el sırtı bel bölgesinde durur; elini sırtından geriye doğru uzaklaştırmasını isteyin.","positive":"Elini sırtından uzaklaştıramaz veya ağrı ortaya çıkar","tissue":"m. subscapularis","point":"İç rotasyon EHA’sı yetersiz olduğu için el sırta ulaşmıyorsa belly press testini kullanın."},{"name":"Drop arm testi","alias":"","steps":"Fizyoterapist kolu pasif olarak yaklaşık 90° abdüksiyona kaldırır, ardından hasta kolu yavaşça indirir.","positive":"İnerken kolu tutamaz ve kol düşer veya şiddetli ağrı olur","tissue":"Rotator manşet yırtığı (özellikle m. supraspinatus)","point":"Büyük yırtığa işaret eder. Tek başına tanı koymayın; diğer testler ve görüntülemeyle karşılaştırın."}]},"keypoints":["Ağrıyı ve zayıflığı ayrı kaydedin, daima sağlam tarafla karşılaştırın","Jobe testi skapula düzleminde, başparmak aşağıda m. supraspinatusu test eder","Dirençli dış rotasyon: m. infraspinatus ve teres minor; lift-off: m. subscapularis","Tek testten kesin sonuç çıkarmayın; bulguları birleştirin","Travma sonrası kolu aniden kaldıramıyorsa hekime yönlendirin"],"case":{"text":"58 yaşında erkek. Düşüp sağ eli üzerine destek almış, o zamandan beri sağ omzunu kaldıramıyor. Pasif EHA neredeyse korunmuş, aktif kaldırma zor. Jobe testi: zayıflık; drop arm testi pozitif.","answer":"Pasif EHA korunmuş ve yalnızca aktif hareket zor olduğundan kontraktür yerine rotator manşet yırtığı düşünülür. Testlere dayanarak tanı koymayın; hekim muayenesi ve görüntüleme için yönlendirin. Ağrı oluşturan güçlü dirençli egzersizleri tekrarlamayın."},"questions":[{"level":"Temel","q":"Jobe testi (skapula düzleminde 90°, başparmak aşağıda) öncelikle hangi kası test eder?","options":["m. supraspinatus","m. infraspinatus","m. subscapularis","m. teres minor"],"answer":0,"exp":"Skapula düzleminde 90° abdüksiyonda, başparmak aşağıdayken verilen dirençle m. supraspinatus test edilir."},{"level":"Temel","q":"Bel bölgesindeki el sırtını uzaklaştırmanın istendiği Gerber lift-off testi hangi kası test eder?","options":["m. teres major","m. supraspinatus","m. subscapularis","m. deltoideus"],"answer":2,"exp":"Eli sırttan uzaklaştırmak iç rotasyondur; bu nedenle ana iç rotator olan m. subscapularisi test eder."},{"level":"Orta","q":"Dirsek 90° fleksiyonda, kol yanda iken dirence karşı yapılan dış rotasyon neyi test eder?","options":["Yalnızca m. supraspinatus","m. infraspinatus ve m. teres minor","m. subscapularis","M. biceps brachii uzun başı"],"answer":1,"exp":"Dirençli dış rotasyon, dış rotatorlar olan m. infraspinatus ve m. teres minorun ağrısını ve zayıflığını gösterir."},{"level":"Orta","q":"Pozitif drop arm testi en çok neye işaret eder?","options":["Anterior omuz instabilitesi","Biseps uzun başı tenosinoviti","Akromiyoklaviküler eklem hasarı","Rotator manşet yırtığı"],"answer":3,"exp":"Hasta kaldırılmış kolu yavaşça indiremez ve kol düşerse, bu rotator manşet (özellikle m. supraspinatus) yırtığına işaret eder."},{"level":"Klinik","q":"62 yaşında kadın. Elini sırtına götürebiliyor ama sırtından uzaklaştıramıyor. Dirençli dış rotasyon normal. Hasar en olası nerededir?","options":["m. supraspinatus","m. subscapularis","m. infraspinatus","m. teres minor"],"answer":1,"exp":"Lift-off testi pozitif, dış rotasyon normal. En çok iç rotator m. subscapularis hasarı düşünülür."},{"level":"Klinik","q":"65 yaşında erkek, omzunu kaldırmakta zorlanıyor. Pasif EHA korunmuş, Jobe testinde belirgin zayıflık var. En uygun yaklaşım hangisidir?","options":["Maksimal dirençli kuvvetlendirmeye başlamak","Bilgilendirmek ve hekim muayenesi istemek","Güçlü germeleri tekrarlamak","Beklemeyi önermek"],"answer":1,"exp":"Rotator manşet yırtığı şüphesi vardır; tanı ve plan için hekim muayenesi ve görüntüleme gerekir. Yüksek yükten kaçının."}],"seccion":"Bölgelere göre özel testler","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"Jobe testi","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"Jobe testi","rotulo":"Değerlendirdiği yapı","texto":"supraspinatus kası","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"Sıkışma ve İnstabilite","lead":"Kaldırmada ortaya çıkan ağrı subakromiyal sıkışmaya, dış rotasyonda ortaya çıkan güvensizlik hissi anterior instabiliteye işaret eder. Ağrıyı ve güvensizlik hissini ayırt etmeniz önemlidir.","sheet":{"kind":"tests","tests":[{"name":"Neer testi","alias":"Neer sıkışma belirtisi","steps":"Skapulayı yukarıdan sabitleyin ve iç rotasyondaki kolu pasif olarak öne doğru maksimal kaldırın.","positive":"Kaldırmada omzun ön-üst kısmında ağrı","tissue":"Subakromiyal rotator manşet ve bursa","point":"Tuberculum majus akromiyonun altına sıkışır ve ağrı yapar. Pozitif test de yırtık olup olmadığını göstermez."},{"name":"Hawkins-Kennedy testi","alias":"","steps":"Omuz ve dirsek 90° fleksiyonda; fizyoterapist önkolu aşağı bastırarak omzu pasif iç rotasyona götürür.","positive":"İç rotasyonda omzun ön-üst veya yan kısmında ağrı","tissue":"Supraspinatus tendonu ve subakromiyal bursa","point":"Neer testiyle birlikte değerlendirin. Ağrının yerini ve tekrarlanabilirliğini kontrol edin."},{"name":"Apprehension testi","alias":"Anterior apprehension testi","steps":"Sırtüstü, omuz 90° abdüksiyonda, dirsek 90° fleksiyonda; fizyoterapist omzu yavaşça dış rotasyona götürür.","positive":"Çıkma korkusu, koruyucu kas gerginliği","tissue":"Omuz ekleminin anterior kapsülü ve labrumu","point":"Belirleyici olan ağrı değil, güvensizlik hissidir. Çıkık sonrası yavaş ve nazik yapın."},{"name":"Relocation testi","alias":"","steps":"Apprehension testi pozisyonunda humerus başını önden arkaya bastırarak dış rotasyon yapın.","positive":"Güvensizlik hissi azalır ve dış rotasyon daha ileri götürülebilir","tissue":"Omuz ekleminin anterior instabilitesi","point":"Apprehension testinden sonra yapın; güvensizlikteki değişim anterior instabiliteyi doğrular."}]},"keypoints":["Neer ve Hawkins-Kennedy testleri subakromiyal sıkışma ağrısını test eder","İnstabilite testinde güvensizlik hissinin ortaya çıkması ağrıdan önemlidir","Pozitif test de rotator manşet yırtığının varlığını ve boyutunu göstermez","Çıkık sonrası durumda dış rotasyonu yavaş ve zorlamadan yapın","Anamnez, diğer testler ve görüntülemeyi birlikte değerlendirin"],"case":{"text":"19 yaşında erkek ragbi oyuncusu. Bir müdahalede kolu abdüksiyon ve dış rotasyona zorlanmış; o zamandan beri aynı pozisyonda omzunun «çıkacağını» hissediyor. Apprehension testi güvensizlik yaratıyor, relocation testi bunu azaltıyor.","answer":"Anterior omuz instabilitesine işaret eden bulgular; sıkışma ağrısından ayırt edin. Abdüksiyon ve dış rotasyonu zorlayan hareketlerden kaçının; hekim değerlendirmesine dayanarak rotator manşet ve skapula çevresi kasların stabilizasyonuyla ilerleyin."},"questions":[{"level":"Temel","q":"Subakromiyal sıkışmada en sık hangi yapı sıkışır?","options":["M. triceps brachii tendonu","m. teres major","Supraspinatus tendonu","m. latissimus dorsi"],"answer":2,"exp":"Kaldırma sırasında akromiyonun altında supraspinatus tendonu ve subakromiyal bursa sıkışır ve ağrı oluşturur."},{"level":"Temel","q":"Hawkins-Kennedy testinde omuza hangi hareketi yaptırırsınız?","options":["90° fleksiyonda iç rotasyon","Kol yandayken dış rotasyon","Horizontal abdüksiyon","Ekstansiyon"],"answer":0,"exp":"Omuz ve dirsek 90° fleksiyondayken pasif iç rotasyon, tuberculum majusu korakoakromiyal arkın altına sıkıştırır."},{"level":"Orta","q":"Apprehension testinin pozitif bulgusu hangisidir?","options":["Kaldırmada ön-üst omuz ağrısı","Çıkma korkusu","Dirsek fleksiyonunda ağrı","Kolun düşmesi"],"answer":1,"exp":"Abdüksiyon ve dış rotasyonda ortaya çıkan çıkma korkusu veya koruyucu kas gerginliği pozitiftir; anterior instabiliteye işaret eder."},{"level":"Orta","q":"Relocation testinde güvensizlik hissinin azalması neye işaret eder?","options":["Rotator manşet yırtığı","Akromiyoklaviküler eklem hasarı","Donuk omuz","Anterior omuz instabilitesi"],"answer":3,"exp":"Humerus başı geriye bastırıldığında güvensizlik azalıyorsa bu, anterior instabiliteyi doğrular."},{"level":"Klinik","q":"45 yaşında erkek, baş üstü çalışırken omzunun önü-üstü ağrıyor. Neer ve Hawkins testleri ağrılı, kuvvet korunmuş. En olası tanı hangisidir?","options":["Anterior instabilite","Subakromiyal sıkışma","Servikal radikülopati","Akromiyoklaviküler çıkık"],"answer":1,"exp":"Kaldırma ve iç rotasyonda ön-üst ağrı ile korunmuş kuvvet, en çok subakromiyal sıkışmayı düşündürür."},{"level":"Klinik","q":"20 yaşında kadın, iki kez anterior omuz çıkığı geçirmiş. Apprehension testini yaparken en uygun yaklaşım hangisidir?","options":["Hızla maksimal dış rotasyona götürmek","Güvensizlik başlar başlamaz durmak","Ağrıya kadar dış rotasyona devam etmek","Hızlı, salınımlı yapmak"],"answer":1,"exp":"Amaç güvensizlik hissini saptamaktır; ortaya çıktığında durun. Zorlamada yeniden çıkma riski vardır."}],"seccion":"Bölgelere göre özel testler","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"Neer testi","img":"img/fichas/neer.jpg"},{"nombre":"Hawkins-Kennedy testi","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"Biseps ve Glenoid Labrum","lead":"M. biceps brachii uzun baş tendonu sulcus intertubercularisten geçer ve üst labruma yapışır. Fırlatma ve çekmede sık yaralanır; tendonu ve labrumu ayrı değerlendirin.","sheet":{"kind":"tests","tests":[{"name":"Speed testi","alias":"","steps":"Dirsek düz, önkol supinasyonda hasta omzunu öne kaldırır; fizyoterapist önkola aşağı doğru direnç verir.","positive":"Sulcus intertubercularis bölgesinde ağrı","tissue":"M. biceps brachii uzun baş tendonu","point":"Üst labrum yaralanması da ağrı yapabilir. Hassas noktayla birlikte değerlendirin."},{"name":"Yergason testi","alias":"","steps":"Dirsek 90° fleksiyonda, önkol pronasyondan başlayarak hasta fizyoterapistin direncine karşı supinasyon yapar.","positive":"Sulcus intertubercularisde ağrı veya tendonun yerinden çıkma hissi","tissue":"Uzun baş tendonu ve lig. transversum humeri","point":"Tendon sublüksasyonunda klik eşlik edebilir. Ağrının yerini daima kontrol edin."},{"name":"O’Brien testi","alias":"Aktif kompresyon testi","steps":"Omuz 90° fleksiyonda, hafif horizontal addüksiyonda, başparmak aşağıda aşağıya direnç verin; sonra avuç yukarıda tekrarlayın.","positive":"Başparmak aşağıda: derin ağrı veya klik; avuç yukarıda: hafifler","tissue":"Üst labrum ve akromiyoklaviküler eklem","point":"Omuz tepesindeki ağrı AK ekleme, derin ağrı labruma işaret eder. Ağrının yerini ayırt edin."},{"name":"Crank testi","alias":"","steps":"Omuz belirgin elevasyondayken humerusun uzun ekseni boyunca baskı vererek iç ve dış rotasyon yapın.","positive":"Ağrı veya klik (takılma hissi) oluşması","tissue":"Glenoid labrum","point":"Labrum yaralanması tek başına testle zor doğrulanır; görüntülemeyle birlikte değerlendirin."}]},"keypoints":["Uzun baş tendonu sulkusta ilerler, tuberculum supraglenoidale ve üst labruma yapışır","Speed ve Yergason testleri sulcus intertubercularis ağrısını kontrol eder","O’Brien testi ağrının yerine göre labrumu ve AK eklemi ayırt eder","Klik veya takılma hissi olup olmadığını da kaydedin","Labrum yaralanmasını yalnızca testle doğrulamayın; görüntülemeyle karşılaştırın"],"case":{"text":"22 yaşında erkek beyzbol atıcısı. Fırlatmada derin omuz ağrısı ve takılma hissi. O’Brien testi başparmak aşağıda derin ağrı yapıyor, avuç yukarıda hafifliyor. Speed testi de ağrılı.","answer":"Üst labrum (SLAP) yaralanmasından şüphelenilir. Ağrı omuz tepesindeyse AK eklem kaynağını düşünün. Fırlatmaya devam kararını tek başınıza vermeyin; hekime yönlendirin ve ağrı yapan fırlatma hareketinden kaçınmasını isteyin."},"questions":[{"level":"Temel","q":"M. biceps brachii uzun baş tendonu hangi oluktan geçer?","options":["Cavitas glenoidalis","Sulcus intertubercularis","Sulcus nervi radialis","Akromiyon"],"answer":1,"exp":"Uzun baş tendonu humerusun tuberculum majus ve minusu arasındaki sulcus intertubercularisten ekleme girer."},{"level":"Temel","q":"Biseps uzun baş tendonu tuberculum supraglenoidalenin yanı sıra hangi yapıya yapışır?","options":["Üst labrum","Lig. glenohumerale inferius","Lig. acromioclaviculare","Lig. coracoclaviculare"],"answer":0,"exp":"Uzun baş tuberculum supraglenoidale ve üst labruma yapışır; bu nedenle tendon ve labrum yaralanmaları sıklıkla birliktedir."},{"level":"Orta","q":"Yergason testinde hangi harekete karşı direnç verirsiniz?","options":["Omuz abdüksiyonu","El bileği dorsifleksiyonu","Önkol supinasyonu","Dirsek ekstansiyonu"],"answer":2,"exp":"Dirsek 90° fleksiyonda önkol supinasyonuna direnç verilir; sulkus ağrısı uzun baş tendon hasarına işaret eder."},{"level":"Orta","q":"O’Brien testi omuz tepesinde ağrı yapıyorsa ne düşünürsünüz?","options":["Üst labrum yaralanması","Akromiyoklaviküler eklem hasarı","Rotator manşet yırtığı","Anterior instabilite"],"answer":1,"exp":"Omuz tepesindeki ağrı AK ekleme, derin omuz ağrısı üst labrum yaralanmasına işaret eder."},{"level":"Klinik","q":"25 yaşında erkek voleybolcu. Smaçta derin omuz ağrısı ve klik var; O’Brien testi derin ağrı yapıyor. En olası tanı hangisidir?","options":["AK eklem hasarı","Donuk omuz","Servikal spondiloz","SLAP yaralanması"],"answer":3,"exp":"Baş üstü harekette derin ağrı ve klik ile pozitif O’Brien testi (derin ağrı): SLAP yaralanmasından şüphelenilir."},{"level":"Klinik","q":"40 yaşında erkek ağır bir yük kaldırırken kolunun önünde kopma sesi duymuş ve biseps karnı aşağı inmiş. En iyi yaklaşım hangisidir?","options":["Maksimal dirençli kuvvetlendirme","Yergason testini tekrarlamak","Hekim muayenesine yönlendirmek","Isıtıp beklemek"],"answer":2,"exp":"Uzun baş tendon rüptürüne işaret eden bulgular; önce hekim muayenesi gerekir. Yükleyici test ve egzersizden kaçının."}],"seccion":"Bölgelere göre özel testler","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"Dirsek","lead":"Dirsek ağrısını lateralde ekstansör kaslar, medialde fleksör kaslar ve bağlar ile n. ulnaris olarak ayırarak düşünün. Ağrının yerini uygun testle eşleştirin.","sheet":{"kind":"tests","tests":[{"name":"Thomsen testi","alias":"","steps":"Dirsek düz, el bileği hafif dorsifleksiyonda hasta yumruk yapar; fizyoterapist el sırtını palmar fleksiyon yönüne bastırır.","positive":"Epicondylus lateralis humeri çevresinde ağrı","tissue":"M. extensor carpi radialis brevis orijini","point":"Lateral epikondilit testidir. Orta parmak ekstansiyon testi ve sandalye testiyle birleştirin."},{"name":"Orta parmak ekstansiyon testi","alias":"","steps":"Dirsek düz, hasta orta parmağını ekstansiyona getirir; fizyoterapist proksimal falanksı palmar yöne bastırır.","positive":"Epicondylus lateralis humeri çevresinde ağrı","tissue":"ECRB ve m. extensor digitorum orijini","point":"Thomsen testi gibi lateral epikondilitte pozitiftir. Ağrının nerede ortaya çıktığını kontrol edin."},{"name":"Valgus stres testi","alias":"","steps":"Dirsek hafif fleksiyondayken humerusu sabitleyin ve önkola valgus yönünde yük verin.","positive":"Medial dirsek ağrısı veya sağlam taraftan fazla açılma","tissue":"Lig. collaterale ulnare (medial kollateral bağ)","point":"Atıcı dirseği değerlendirmesi içindir. Daima sağlam tarafla karşılaştırın; ağrıyı ve laksiteyi ayrı kaydedin."},{"name":"Tinel belirtisi (kubital tünel)","alias":"","steps":"Epicondylus medialis ile olekranon arasındaki kubital tünele parmak ucu veya refleks çekiciyle hafifçe vurun.","positive":"Serçe parmağa ve yüzük parmağın ulnar yüzüne yayılan uyuşma","tissue":"n. ulnaris (kubital tünel)","point":"Kubital tünel sendromu testidir. Dirsek fleksiyon testi ve Froment belirtisiyle birlikte değerlendirin."}]},"keypoints":["Lateral epikondil ağrısında el bileği ve parmak ekstansörlerinin orijinini düşünün","Valgus stres testini hafif fleksiyonda yapın, sağlam tarafla karşılaştırın","N. ulnaris belirtileri serçe parmak ve yüzük parmak ulnar yüzü uyuşmasıyla belirir","Ağrıyı ve laksiteyi (instabilite) ayrı kaydedin","Süregen uyuşma veya el kası atrofisi varsa hekime yönlendirin"],"case":{"text":"45 yaşında kadın, ofis çalışanı. Havlu sıkarken ve çanta kaldırırken dirseğinin dış yanı ağrıyor. Lateral epikondil hassas; Thomsen testi ve orta parmak ekstansiyon testi ağrıyı tetikliyor.","answer":"Lateral humeral epikondilite işaret eden bulgular. Ağrı yapan kavrama hareketlerini tekrarlamaktan kaçınmasını isteyin ve yükü dozlayın. Uyuşma, şişlik veya şiddetli gece ağrısı eşlik ederse başka bir hastalığı da düşünün ve hekime yönlendirin."},"questions":[{"level":"Temel","q":"Epicondylus lateralis humeriden hangi kas grubu köken alır?","options":["El bileği fleksörleri","El bileği ekstansörleri","m. biceps brachii","m. pronator teres"],"answer":1,"exp":"Lateral epikondilden el bileği ve parmak ekstansörleri, medial epikondilden fleksörler ve m. pronator teres köken alır."},{"level":"Temel","q":"Kubital tünelden hangi sinir geçer?","options":["n. medianus","n. radialis","n. ulnaris","n. musculocutaneus"],"answer":2,"exp":"N. ulnaris medial epikondilin arkasındaki kubital tünelden geçer; bu yüzden medial dirseğe vurmak serçe parmağa doğru uyuşma yapar."},{"level":"Orta","q":"Thomsen testinde hangi harekete karşı direnç verirsiniz?","options":["El bileği dorsifleksiyonu","El bileği palmar fleksiyonu","Önkol pronasyonu","Dirsek fleksiyonu"],"answer":0,"exp":"El bileği dorsifleksiyonuna verilen direnç lateral epikondil çevresinde (ekstansör orijini) ağrıyı tetikler."},{"level":"Orta","q":"Valgus stres testi öncelikle hangi yapıyı test eder?","options":["Lateral kollateral bağ","Lig. anulare radii","Caput radii","Medial kollateral bağ"],"answer":3,"exp":"Önkola verilen valgus yükü dirseğin medial yüzünü gerer; böylece medial kollateral bağın ağrısını ve laksitesini test eder."},{"level":"Klinik","q":"14 yaşında erkek beyzbol atıcısı. Fırlatmada medial dirsek ağrısı; valgus stres testi medialde ağrı yapıyor. En olası tanı hangisidir?","options":["Lateral humeral epikondilit","Medial tip atıcı dirseği","Dadı dirseği","Radius başı kırığı"],"answer":1,"exp":"Tekrarlayan fırlatma ve valgus yükte medial ağrı, medial atıcı dirseğine (bağ, epifiz hasarı) işaret eder."},{"level":"Klinik","q":"50 yaşında erkek. Medial dirseğe vurunca serçe parmağına uyuşma yayılıyor ve ince parmak hareketleri de zorlaşmış. En iyi yaklaşım hangisidir?","options":["Dirseği uzun süre fleksiyonda tutmak","Uyuşmayı izlemek","Hekime bilgi vermek","Medial dirseğe güçlü masaj"],"answer":2,"exp":"Beceri kaybıyla seyreden n. ulnaris hasarında hekim muayenesi gerekir. Süreli dirsek fleksiyonu ve bası belirtileri kötüleştirir."}],"seccion":"Bölgelere göre özel testler","grupo":"Dirsek, el bileği ve el","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"El Bileği ve El","lead":"Eldeki uyuşma ve ağrıda dağılıma bakarak hangi sinirin veya tendonun etkilendiğini çıkarın. Karpal tünel sendromu ve tenosinovit klinikte ve final sınavında da sık görülür.","sheet":{"kind":"tests","tests":[{"name":"Phalen testi","alias":"","steps":"Hasta iki el sırtını birleştirerek el bileklerini bir süre maksimal palmar fleksiyonda tutar; uyuşmanın ortaya çıkışını izleyin.","positive":"Başparmaktan yüzük parmağın radial yüzüne kadar uyuşma veya artışı","tissue":"n. medianus (karpal tünel)","point":"Karpal tünel sendromu testidir. Uyuşmanın n. medianus alanına uyup uymadığını kontrol edin."},{"name":"Tinel belirtisi (el bileği)","alias":"","steps":"El bileğinin palmar yüzünde karpal tünele parmak ucu veya refleks çekiciyle hafifçe vurun.","positive":"N. medianus alanında parmak uçlarına yayılan uyuşma","tissue":"n. medianus (karpal tünel)","point":"Sinir basısının yerini ve rejenerasyonu tahmin etmek için de kullanılır. Çok sert vurmayın."},{"name":"Finkelstein testi","alias":"","steps":"Hasta başparmağını diğer parmaklarıyla yumruk içine alır (veya fizyoterapist başparmağı tutar); el bileğini pasif ulnar deviasyona götürün.","positive":"Processus styloideus radii bölgesinde şiddetli ağrı","tissue":"m. abductor poll. longus ve m. extensor poll. brevis","point":"De Quervain hastalığı testidir. Yumruklu varyantın adı Eichhoff testidir. Sağlam tarafla karşılaştırın."},{"name":"Froment belirtisi","alias":"","steps":"Hasta iki elinin başparmağı ile işaret parmağı arasında kâğıt tutar, fizyoterapist kâğıdı çeker.","positive":"Kâğıdı tutmak için başparmak IP eklemi fleksiyona gider","tissue":"n. ulnaris (m. adductor pollicis)","point":"Zayıf m. adductor pollicisi, n. medianusun innerve ettiği m. flexor pollicis longus kompanse eder."}]},"keypoints":["Uyuşmanın dağılımına göre n. medianus, ulnaris ve radialisi ayırt edin","Phalen testi ve Tinel belirtisi karpal tüneldeki n. medianusu test eder","Finkelstein testi başparmak tenosinovitini değerlendirir","İki tarafta da yapın ve sağlam tarafla karşılaştırarak değerlendirin","Tenar atrofi veya süregen uyuşma varsa hekime yönlendirin"],"case":{"text":"52 yaşında kadın. Sabaha karşı başparmağı, işaret ve orta parmağı uyuşuyor, eli sallayınca hafifliyor. Phalen testi aynı bölgede uyuşma yapıyor, karpal tünel üzerindeki Tinel belirtisi de pozitif.","answer":"Karpal tünel sendromundan şüphelenilir. Uyuşma serçe parmağa da yayılıyorsa veya boyun hareketiyle değişiyorsa başka bir seviyeyi de düşünün. Tenar atrofi veya güçsüzlük varsa hekime yönlendirin; el bileğinin güçlü sıkıştırılmasından kaçının."},"questions":[{"level":"Temel","q":"Karpal tünelden hangi sinir geçer?","options":["n. ulnaris","n. medianus","n. radialis","n. musculocutaneus"],"answer":1,"exp":"Karpal tünelde parmak fleksör tendonları ve n. medianus geçer; burada sıkışması karpal tünel sendromudur."},{"level":"Temel","q":"Finkelstein testinde ağrı nerede ortaya çıkar?","options":["Processus styloideus radii","Processus styloideus ulnae","Os pisiforme","5. metakarp başı"],"answer":0,"exp":"Başparmak tendonlarının (m. abductor pollicis longus, m. extensor pollicis brevis) üzerinden geçtiği proc. styloideus radiide ağrır."},{"level":"Orta","q":"Froment belirtisi hangi siniri test eder?","options":["n. medianus","n. radialis","n. axillaris","n. ulnaris"],"answer":3,"exp":"N. ulnarisin innerve ettiği m. adductor pollicis zayıfsa m. flexor pollicis longus kompanse eder ve IP eklemi bükülür."},{"level":"Orta","q":"Phalen testinin pozitif bulgusu hangisidir?","options":["Serçe parmak uyuşması","Tüm el sırtında ağrı","1.–4. parmağın radial yarısına kadar uyuşma","El bileğinde instabilite hissi"],"answer":2,"exp":"Sürdürülen palmar fleksiyon tünel basıncını artırır; n. medianus alanında (başparmaktan 4. parmağın radial yarısına) uyuşma olur."},{"level":"Klinik","q":"30 yaşında kadın. Doğumdan beri bebek bakarken el bileğinin başparmak tarafı ağrıyor; başparmak yumrukta ulnar deviasyonda ağrı var. Tanı?","options":["Karpal tünel sendromu","TFCC yaralanması","De Quervain hastalığı","Tetik parmak"],"answer":2,"exp":"Başparmağın aşırı kullanımı ve yumruk + ulnar deviasyonda proc. styloideus radiide ağrı, de Quervain hastalığına işaret eder."},{"level":"Klinik","q":"60 yaşında erkek. Serçe ve yüzük parmağın ulnar yüzü uyuşuyor; kâğıt sıkıştırmada başparmak IP eklemi bükülüyor. Hangi sinir hasarlı?","options":["n. medianus","n. radialis","n. interosseus posterior","n. ulnaris"],"answer":3,"exp":"Serçe parmak ve yüzük parmak ulnar yüzü uyuşması ile pozitif Froment belirtisi n. ulnaris hasarına işaret eder."}],"seccion":"Bölgelere göre özel testler","grupo":"Dirsek, el bileği ve el","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"Phalen testi","img":"img/fichas/phalen.jpg"},{"nombre":"Finkelstein testi","img":"img/fichas/finkelstein.jpg"},{"nombre":"El bileğinde Tinel belirtisi","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"Servikal Omurga","lead":"Boyundan kola yayılan ağrı ve uyuşmaya sinir kökü basısı neden olabilir. Radiküler bir belirti olup olmadığını provokasyon ve rahatlatma testleriyle de kontrol edin.","sheet":{"kind":"tests","tests":[{"name":"Spurling testi","alias":"Foraminal kompresyon testi","steps":"Oturur pozisyonda boynu ağrılı tarafa eğin (hafif ekstansiyon ve rotasyon), ardından başın tepesinden aşağı doğru baskı verin.","positive":"Ağrılı taraftaki kola yayılan ağrı veya uyuşmanın oluşması","tissue":"Servikal sinir kökü (intervertebral foramen)","point":"Yalnızca boyun ağrısı oluşması pozitif değildir. Şiddetli ağrı veya baş dönmesi olursa hemen bırakın."},{"name":"Jackson testi","alias":"Jackson kompresyon testi","steps":"Oturur pozisyonda, boyun hafif ekstansiyondayken başın tepesinden aşağı doğru baskı verin.","positive":"Kola yayılan ağrı veya uyuşmanın oluşması","tissue":"Servikal sinir kökü","point":"Ekstansiyonda foramenin daralmasından yararlanır. Spurling testiyle birleştirin."},{"name":"Servikal distraksiyon testi","alias":"Distraksiyon testi","steps":"Oturur pozisyonda çene altından ve oksiputtan destekleyerek başı yavaşça yukarı çekin.","positive":"Kola yayılan ağrı veya uyuşma hafifler","tissue":"Servikal sinir kökü (foraminal bası)","point":"Hafifleme olursa pozitiftir. Çekme belirtileri artırırsa başka bir nedeni düşünün ve bırakın."},{"name":"Omuz abdüksiyon testi","alias":"Bakody belirtisi","steps":"Oturur pozisyonda hasta ağrılı taraftaki elini başının üstüne koyar; kol belirtilerindeki değişimi izleyin.","positive":"Kola yayılan ağrı veya uyuşma hafifler","tissue":"Servikal sinir kökü","point":"Sinir kökündeki gerilim azalır, belirtiler hafifler. Hasta bu pozisyonu kendiliğinden de alabilir."}]},"keypoints":["Kola yayılan ağrı veya uyuşmanın oluşması radiküler belirtiye işaret eder","Kompresyon testlerini nazik yapın, belirti şiddetliyse durun","Çekme veya omuz abdüksiyonuyla belirtilerin hafifleyip hafiflemediğini de kontrol edin","Dermatom, kas kuvveti ve tendon reflekslerine göre seviyeyi tahmin edin","İki elde uyuşma veya yürüme bozukluğu: miyelopati şüphesi, hekime"],"case":{"text":"48 yaşında erkek, masa başı çalışıyor. Boyun ağrısı ile sağ başparmaktan önkolun radial yüzüne kadar uyuşma. Spurling testi sağ kolda uyuşmayı tetikliyor, başın çekilmesiyle hafifliyor.","answer":"Servikal radikülopatiden şüphelenilir; uyuşmanın dağılımına göre C6 alanı. Tendon reflekslerini ve kas kuvvetini de kontrol edin. İki elin becerisi azalıyorsa veya yürüme bozukluğu varsa miyelopatiyi düşünün ve hekime yönlendirin. Güçlü kompresyonu tekrarlamayın."},"questions":[{"level":"Temel","q":"Spurling testinde boyun hangi pozisyondayken başa aşağı baskı verirsiniz?","options":["Ağrılı tarafa lateral fleksiyon","Sağlam tarafa lateral fleksiyon","Maksimal fleksiyon","Orta pozisyonda çekme"],"answer":0,"exp":"Ağrılı tarafa eğilmede (hafif ekstansiyonla) foramen daralır; başa verilen baskı radiküler belirtiyi tetikler."},{"level":"Temel","q":"Boyun ekstansiyonu ve ağrılı tarafa eğilmede hangi alan daralarak sinir kökünü kolayca sıkıştırır?","options":["Vertebra gövdesinin ön kenarı","İntervertebral foramen","Spinöz çıkıntılar arası","Transvers çıkıntı ucu"],"answer":1,"exp":"Sinir kökü intervertebral foramenden çıkar; bu nedenle ekstansiyon ve lateral fleksiyondaki daralma onu kolayca sıkıştırır."},{"level":"Orta","q":"Servikal distraksiyon testinin pozitif bulgusu hangisidir?","options":["Kol belirtilerinin artması","Baş dönmesi ortaya çıkması","Kol belirtilerinin hafiflemesi","Boyun EHA’sının artması"],"answer":2,"exp":"Çekme foramenleri genişletir, sinir kökü basısı azalır; kol ağrısı ve uyuşması hafiflerse test pozitiftir."},{"level":"Orta","q":"Spurling testini hangi bulguya göre pozitif kabul edersiniz?","options":["Yalnızca boyun ağrısı","Omuz sertliği hissi","Boyun kas gerginliği","Ağrılı taraftaki kola yayılan ağrı"],"answer":3,"exp":"Kola yayılan ağrı veya uyuşma oluşursa pozitiftir. Yalnızca lokal boyun ağrısı pozitif değildir."},{"level":"Klinik","q":"50 yaşında kadın, boyun ağrısı ve sol orta parmakta uyuşma. Solda triseps tendon refleksi azalmış. Hangi sinir kökünden şüphelenirsiniz?","options":["C5","C6","C7","C8"],"answer":2,"exp":"Orta parmakta duyu bozukluğu ve azalmış triseps refleksi C7 sinir kökü hasarına işaret eder."},{"level":"Klinik","q":"65 yaşında erkek. İki eli uyuşuyor, düğme iliklemekte zorlanıyor ve yürürken dengesiz. En uygun yaklaşım hangisidir?","options":["Hekime bilgi vermek","Boynu güçlü çekmek","Spurling testini tekrarlamak","Servikal manuel düzeltme"],"answer":0,"exp":"İki taraflı beceri kaybı ve yürüme bozukluğu servikal miyelopatiye işaret eder. Provokasyon testlerinden kaçının, hekime yönlendirin."}],"seccion":"Bölgelere göre özel testler","grupo":"Omurga ve pelvis","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"Lomber Omurga","lead":"Bel ağrısına alt ekstremite ağrısı veya uyuşma eşlik ediyorsa sinir kökü tutulumunu değerlendirin. Testlerle tetiklenen belirtilerden ve nörolojik bulgulardan lezyon seviyesini tahmin edin.","sheet":{"kind":"tests","tests":[{"name":"SLR testi","alias":"Lasègue testi (DBK testi)","steps":"Sırtüstü, diz düzken fizyoterapist alt ekstremiteyi yavaşça, pasif olarak kaldırır.","positive":"Kalçaya ve bacağa yayılan ağrı veya uyuşmanın oluşması","tissue":"L5 ve S1 sinir kökü, n. ischiadicus","point":"Uyluk arkasındaki gerginliği hamstring gerilmesinden ayırt edin. Açıyı ve belirtiyi kaydedin."},{"name":"Femoral sinir germe testi","alias":"FNS testi (ters Lasègue)","steps":"Yüzüstü pozisyonda dizi pasif olarak fleksiyona getirin; gerekirse kalçayı da ekstansiyona götürün.","positive":"Uyluğun ön yüzüne yayılan ağrı","tissue":"Üst lomber sinir kökleri (L2–L4), n. femoralis","point":"M. quadriceps gerilme ağrısından ve kalça kaynaklı ağrıdan ayırt edin."},{"name":"Kemp testi","alias":"","steps":"Ayakta veya oturarak fizyoterapist gövdeyi geriye ekstansiyona götürür ve aynı anda ağrılı tarafa eğip rotasyon yaptırır.","positive":"Bel ağrısı veya ağrılı taraftaki bacağa yayılan ağrı","tissue":"Faset eklemler ve sinir kökü (foramen)","point":"Lokal bel ağrısında faset eklem, bacağa yayılan ağrıda sinir kökü tutulumunu düşünün."},{"name":"Bragard testi","alias":"","steps":"SLR’de belirti oluşturan açıdan ekstremiteyi biraz indirin, ardından ayak bileğini pasif dorsifleksiyona götürün.","positive":"Bacağa yayılan ağrı yeniden ortaya çıkar veya artar","tissue":"n. ischiadicus ve lumbosakral sinir kökleri","point":"Hamstring gerilme ağrısını sinir kaynaklı belirtiden ayırt etmeye yardımcı olur."}]},"keypoints":["Önce ayırt edin: yalnızca bel ağrısı mı, bacak belirtileri de var mı?","SLR alt, femoral germe testi üst lomber sinir köklerini test eder","Kas gerilme hissini ve nörojenik yayılan ağrıyı ayrı kaydedin","Dermatom, kas kuvveti ve tendon reflekslerine göre seviyeyi tahmin edin","İdrar veya dışkılama bozukluğu, perine uyuşması: acilen hekime"],"case":{"text":"35 yaşında erkek. Ağır bir yük kaldırdığından beri bel ağrısı ile sağ bacağın dış yüzünden ayak sırtına uyuşma var. SLR testi sağ bacağa yayılan ağrı yapıyor, Bragard testi artırıyor. Başparmak dorsifleksiyon kuvveti azalmış.","answer":"L5 radiküler belirtiden şüphelenilir (ör. lomber disk hernisi). Ağrıyı artıran öne eğilmeli yüklenmeden kaçının. İdrar veya dışkılama bozukluğu, perine uyuşması ya da hızla kötüleşen kas kuvveti varsa acilen hekime yönlendirin."},"questions":[{"level":"Temel","q":"SLR testi öncelikle hangi siniri gerer?","options":["n. femoralis","n. ischiadicus","n. obturatorius","n. pudendus"],"answer":1,"exp":"Diz düzken kalça fleksiyonu, ekstremitenin arkasından geçen n. ischiadicusu ve L5–S1 sinir köklerini gerer."},{"level":"Temel","q":"Femoral sinir germe testi öncelikle hangi sinir kökü seviyelerini test eder?","options":["L2–L4","L5–S1","S2–S4","C5–C6"],"answer":0,"exp":"N. femoralis L2–L4 sinir köklerinden çıkar; bu nedenle üst lomber radiküler belirtilerin değerlendirilmesinde kullanılır."},{"level":"Orta","q":"Bragard testinde hangi manevrayı yaparsınız?","options":["Ayak bileği plantar fleksiyonu","Kalça dış rotasyonu","Diz fleksiyonu","Ayak bileği dorsifleksiyonu"],"answer":3,"exp":"SLR’de belirti veren açıdan bacağı biraz indirir, ardından ayak bileği dorsifleksiyonuyla siniri daha da gerersiniz."},{"level":"Orta","q":"Kemp testi bacak belirtisi olmadan yalnızca lokal bel ağrısı yapıyorsa öncelikle ne düşünürsünüz?","options":["Sinir kökü basısı","N. femoralis hasarı","Faset eklem kaynaklı ağrı","M. piriformis sendromu"],"answer":2,"exp":"Ekstansiyon ve rotasyon faset eklemleri yükler. Yalnızca lokal ağrıda faset eklem kaynağını düşünün."},{"level":"Klinik","q":"40 yaşında kadın, bel ağrısı, sol ayağın dış kenarından tabana uyuşma. Solda Aşil tendon refleksi azalmış. Hangi sinir kökünden şüphelenirsiniz?","options":["L3","L4","L5","S1"],"answer":3,"exp":"Ayağın dış kenarı ve tabanda duyu bozukluğu ile azalmış Aşil refleksi S1 sinir kökü hasarına işaret eder."},{"level":"Klinik","q":"50 yaşında erkekte bel ağrısının yanında aniden perine uyuşması ve idrar yapmada zorluk ortaya çıktı. En iyi yaklaşım hangisidir?","options":["Hemen hekime yönlendirmek","SLR’yi tekrar test etmek","Lomber egzersizlere başlamak","Sıcak uygulama ve beklemek"],"answer":0,"exp":"Perine uyuşması ve mesane-bağırsak bozukluğu kauda ekina sendromuna işaret eden kırmızı bayraktır; acil bakım gerekir."}],"seccion":"Bölgelere göre özel testler","grupo":"Omurga ve pelvis","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"Sakroiliak Eklem","lead":"Sakroiliak (Sİ) eklem kaynaklı ağrı bel ağrısıyla kolayca karıştırılır. Ağrının yerini hastaya gösterterek ve birkaç provokasyon testini birleştirerek sonuca varın.","sheet":{"kind":"tests","tests":[{"name":"FABER (Patrick) testi","alias":"","steps":"Sırtüstü, ağrılı taraftaki ayağı karşı dizin üzerine koyun, karşı pelvisi sabitleyin ve dizi aşağı bastırın.","positive":"Kalçada, Sİ eklem üzerinde ağrı (kasık ağrısı: kalça eklemi)","tissue":"Sakroiliak eklem ve kalça eklemi","point":"Ağrının yerine göre ayırın: kasıkta kalça eklemi, gluteal bölge ve Sİ eklem üzerinde Sİ eklem."},{"name":"Gaenslen testi","alias":"","steps":"Sırtüstü, bir alt ekstremite muayene masasının kenarından sarkar (kalça ekstansiyonu), hasta diğer dizini fleksiyonda kendine çeker.","positive":"Ekstansiyondaki taraf Sİ eklemi üzerinde ağrı","tissue":"Sakroiliak eklem","point":"Lomber hiperekstansiyondan kaçının; düşmeyi önlemek için gövdeyi destekleyin."},{"name":"Thigh thrust testi","alias":"Uyluk itme testi","steps":"Sırtüstü, kalça 90° fleksiyondayken uyluğun uzun ekseni boyunca aşağı doğru baskı verin.","positive":"Aynı taraf gluteal bölgede, Sİ eklem üzerinde ağrı","tissue":"Sakroiliak eklem","point":"Hastadan ağrının yerini göstermesini isteyin ve bunun bilinen ağrısı olup olmadığını kontrol edin."},{"name":"Pelvik kompresyon testi","alias":"","steps":"Yan yatışta üstteki krista iliakaya yukarıdan aşağı kompresyon uygulayın.","positive":"Sİ eklem üzerinde ağrı","tissue":"Sakroiliak eklem","point":"Tek başına yeterli değildir. Sİ kaynaklı ağrıya birkaç provokasyon testinin birleşimiyle karar verin."}]},"keypoints":["Hastadan ağrının yerini tek parmakla göstermesini isteyin","Spina iliaca posterior superior çevresindeki ağrıda Sİ kaynağını düşünün","Tek bir teste değil, birkaç provokasyon testine göre karar verin","Kasık ağrısında kalçayı, bacağa yayılan ağrıda sinir kökünü de düşünün","Ateş veya şiddetli istirahat ağrısı varsa hekime yönlendirin"],"case":{"text":"32 yaşında kadın, doğumdan 3 ay sonra. Dönerken ve tek ayak üzerinde dururken artan tek taraflı kalça ağrısı. Tek parmakla spina iliaca posterior superior çevresini gösteriyor. Thigh thrust ve Gaenslen testleri ağrıyı tetikliyor.","answer":"Sİ eklem kaynaklı ağrıdan şüphelenilir. Bacağa yayılan ağrı veya nörolojik belirti varsa lomber kaynağı da düşünün. Ateş veya şiddetli istirahat ağrısında hekime yönlendirin. Pelvik kuşak stabilizasyonu ve yük dozlamasıyla ilerleyin."},"questions":[{"level":"Temel","q":"Tek parmak testinde Sİ kaynaklı ağrıda hasta tipik olarak hangi bölgeyi gösterir?","options":["Spina iliaca ant. sup. çevresi","Spina iliaca post. sup. çevresi","Simfizis pubis","Tuber ischiadicum"],"answer":1,"exp":"Sİ eklem kaynaklı ağrıda hasta sıklıkla tek parmakla spina iliaca posterior superior çevresini gösterir."},{"level":"Temel","q":"Sakroiliak eklemi hangi kemikler oluşturur?","options":["Sakrum ve ilium","Sakrum ve iskium","İlium ve pubis","L5 vertebra ve sakrum"],"answer":0,"exp":"Sİ eklem sakrum ile iki ilium arasındaki eklemdir; pelvik halkanın arka kısmını oluşturur."},{"level":"Orta","q":"FABER (Patrick) testi kasık ağrısı yapıyorsa hangi eklemi düşünürsünüz?","options":["Sakroiliak eklem","Kalça eklemi","Diz eklemi","Faset eklemler"],"answer":1,"exp":"Fleksiyon, abdüksiyon ve dış rotasyonda kasık ağrıyorsa kalça eklemini, gluteal bölgenin arkası ağrıyorsa Sİ eklemi düşünün."},{"level":"Orta","q":"Thigh thrust testinde hangi yönde baskı verirsiniz?","options":["Uyluğu dışa doğru","Pelvisi öne doğru","Uyluğun uzun ekseni boyunca aşağı","Dizi içe doğru"],"answer":2,"exp":"Kalça 90° fleksiyondayken uyluğun uzun ekseni boyunca verilen baskı Sİ ekleme makaslama yükü uygular."},{"level":"Klinik","q":"28 yaşında kadın, doğum sonrası tek taraflı kalça ağrısı. Gaenslen, thigh thrust ve pelvik kompresyon testleri ağrıyı tetikliyor. Olası kaynak?","options":["Kalça eklemi","L5 sinir kökü","m. piriformis","Sakroiliak eklem"],"answer":3,"exp":"Birkaç Sİ provokasyon testi aynı ağrıyı tetikliyor; bu nedenle en çok Sİ eklem kaynaklı ağrı düşünülür."},{"level":"Klinik","q":"45 yaşında erkek, tek taraflı kalça ağrısı. Yalnızca FABER (Patrick) testi gluteal ağrı yaptı. En uygun sonraki adım hangisidir?","options":["Sİ eklem disfonksiyonu demek","Ek provokasyon testleri yapmak","Lomber ve kalça muayenesini atlamak","Güçlü manuel düzeltme"],"answer":1,"exp":"Tek pozitif teste göre karar veremezsiniz. Birkaç provokasyon testini lomber omurga ve kalça muayenesiyle birleştirin."}],"seccion":"Bölgelere göre özel testler","grupo":"Omurga ve pelvis","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"Kalça","lead":"Kalça eklemi kaynaklı ağrı sıklıkla kasıkta hissedilir; kontraktür ve kas zayıflığı ise yürüyüşte görülür. Eklem içi etkiyi, kas etkisini ve yürüyüşe etkisini testlerle kontrol edin.","sheet":{"kind":"tests","tests":[{"name":"Thomas testi","alias":"","steps":"Sırtüstü hasta bir dizini göğsüne çekerek lomber lordozu ortadan kaldırır; karşı uyluğun masadan kalkıp kalkmadığını izleyin.","positive":"Karşı uyluk destek yüzeyinden kalkar (kalça fleksiyon kontraktürü)","tissue":"M. iliopsoas (kalça fleksörleri) kısalığı","point":"Diz ekstansiyona gidiyorsa m. rectus femoris kısalığını da düşünün. Lordoz kalktıktan sonra değerlendirin."},{"name":"FABER (Patrick) testi","alias":"","steps":"Sırtüstü, kalçayı fleksiyon, abdüksiyon ve dış rotasyona getirin (ayak karşı dizin üstünde), ardından dizi aşağı bastırın.","positive":"Kasık ağrısı veya dizin inişinde kısıtlılık","tissue":"Kalça eklemi ve sakroiliak eklem","point":"Kasık ağrısında kalçayı, arka gluteal ağrıda Sİ eklemi düşünün. Sağlam tarafla karşılaştırın."},{"name":"Anterior sıkışma testi","alias":"FADIR testi","steps":"Sırtüstü, kalça 90° fleksiyondayken pasif olarak addüksiyon ve iç rotasyon verin.","positive":"Kasık ağrısının oluşması","tissue":"Kalça ekleminin ön kısmı (labrum, asetabulum kenarı)","point":"Femoroasetabular sıkışma ve labrum yaralanmasında sıklıkla pozitiftir. Görüntülemeyle karşılaştırın."},{"name":"Trendelenburg belirtisi","alias":"","steps":"Hasta ağrılı bacağı üzerinde tek ayak durur; arkadan karşı (kaldırılan) taraf pelvisin yüksekliğini izleyin.","positive":"Kaldırılan taraftaki pelvis düşer","tissue":"Destek bacağı m. gluteus medius (kalça abduktörleri)","point":"Gövde destek bacağına eğilerek kompanse ediyorsa bu Duchenne belirtisidir. Düşmeyi önlemek için destekleyin."}]},"keypoints":["Kalça eklemi kaynaklı ağrı sıklıkla kasıkta hissedilir","Thomas testi lordoz ortadan kaldırıldıktan sonra fleksiyon kontraktürünü test eder","Trendelenburg belirtisi destek bacağının m. gluteus medius kuvvetini gösterir","Lomber omurga ve Sİ eklem kaynaklı ağrıdan da ayırt edin","Travma sonrası yük verememe veya kötüleşen istirahat ağrısı: hekime"],"case":{"text":"68 yaşında kadın, koksartroz. Yürürken sağ kasıkta ağrı. Sağ ayak üzerinde dururken sol pelvis düşüyor; sol dizini göğsüne çektiğinde sağ uyluk destek yüzeyinden kalkıyor.","answer":"Sağ m. gluteus medius zayıflığı ve sağ kalça fleksiyon kontraktürü düşünülür. Yürüme sırasındaki kompansasyonu da gözleyin; ağrıya dikkat ederek abduktör kuvvetlendirme ve EHA egzersizleri yapın. Aniden kötüleşen istirahat ağrısında hekime yönlendirin."},"questions":[{"level":"Temel","q":"Thomas testi öncelikle hangi kasın kısalığını test eder?","options":["m. gluteus maximus","m. iliopsoas","m. gluteus medius","Hamstringler"],"answer":1,"exp":"Karşı uyluğun kalkması kalça fleksiyon kontraktürünü gösterir; böylece ana kalça fleksörü m. iliopsoasın kısalığını ortaya koyar."},{"level":"Temel","q":"Tek ayak duruşta karşı taraf pelvisin düştüğü Trendelenburg belirtisi hangi kasın zayıflığına işaret eder?","options":["Salınım bacağının m. gluteus mediusu","Destek bacağının m. quadricepsi","Destek bacağının m. gluteus mediusu","Salınım bacağının m. iliopsoası"],"answer":2,"exp":"Destek bacağının m. gluteus mediusu zayıfsa pelvisi yatay tutamaz ve karşı (kaldırılan) taraf düşer."},{"level":"Orta","q":"Thomas testinde diz ekstansiyona gidiyorsa hangi kasın kısalığını düşünürsünüz?","options":["m. rectus femoris","m. sartorius","m. adductor magnus","m. biceps femoris"],"answer":0,"exp":"M. rectus femoris kalça ve diz eklemini geçen iki eklemli bir kastır; kısaldığında diz ekstansiyona gider."},{"level":"Orta","q":"Anterior sıkışma (FADIR) testinde hangi hareket kombinasyonunu yaparsınız?","options":["Fleksiyon, abdüksiyon, dış rotasyon","Ekstansiyon, abdüksiyon, iç rotasyon","Ekstansiyon, addüksiyon, dış rotasyon","Fleksiyon, addüksiyon, iç rotasyon"],"answer":3,"exp":"Kalça 90° fleksiyondayken addüksiyon ve iç rotasyon verir, anterior kalça ağrısının oluşup oluşmadığını izlersiniz."},{"level":"Klinik","q":"70 yaşında erkek. Sağ ayağına her bastığında yürürken gövdesini belirgin şekilde sağa eğiyor. Bu yürüyüşün adı nedir?","options":["Steppage (horoz) yürüyüşü","Sirkümdüksiyon yürüyüşü","Donma (freezing)","Duchenne yürüyüşü"],"answer":3,"exp":"Hasta m. gluteus medius zayıflığını gövdeyi destek bacağına eğerek kompanse ediyorsa bu Duchenne yürüyüşüdür."},{"level":"Klinik","q":"30 yaşında erkek futbolcu. Derin çömelmede kasığı ağrıyor; kalça fleksiyon, addüksiyon ve iç rotasyonu ağrıyı tetikliyor. En olası tanı hangisidir?","options":["Gonartroz","Femoroasetabular sıkışma","L5 radikülopatisi","M. piriformis sendromu"],"answer":1,"exp":"Derin fleksiyonda ortaya çıkan kasık ağrısı ve pozitif anterior sıkışma testi femoroasetabular sıkışmaya işaret eder."}],"seccion":"Bölgelere göre özel testler","grupo":"Kalça ve diz","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"Diz: Bağlar","lead":"Diz bağ testleriyle ön ve arka çapraz bağ ile medial ve lateral kollateral bağ yaralanmaları ayırt edilir. Karar, yaralanma mekanizmasına ve sağlam tarafla karşılaştırmaya dayanır.","sheet":{"kind":"tests","tests":[{"name":"Lachman testi","alias":"","steps":"Sırtüstü yatış, diz 20–30° fleksiyonda. Bir el femurun distalini, diğer el tibianın proksimalini kavrar ve tibiayı öne çeker.","positive":"Sağlam taraftan fazla öne kayma veya belirsiz son his.","tissue":"Ön çapraz bağ (ÖÇB)","point":"ÖÇB yaralanmasına duyarlı testtir. 90° diz fleksiyonu gerektirmediği için akut dönemde de rahat uygulanır."},{"name":"Ön çekmece testi","alias":"","steps":"Sırtüstü yatış, kalça 45°, diz 90° fleksiyonda. Ayağı sabitleyin, tibianın proksimalini iki elle kavrayıp öne çekin.","positive":"Sağlam tarafa göre fazla öne tibial kayma.","tissue":"Ön çapraz bağ (ÖÇB)","point":"Kasların koruyucu gerginliği yalancı negatif verebilir. AÇB yaralanmasına bağlı arkaya düşmeye dikkat edin."},{"name":"Arka çekmece testi","alias":"","steps":"Sırtüstü yatış, kalça 45°, diz 90° fleksiyonda. Ayağı sabitleyin ve tibianın proksimalini geriye itin.","positive":"Sağlam taraftan fazla arkaya tibial kayma, belirsiz son his.","tissue":"Arka çapraz bağ (AÇB)","point":"Başlamadan önce tibianın arkaya düşmesine (sag belirtisi) bakın; başlangıç pozisyonunu doğru belirleyin."},{"name":"Valgus ve varus stres testi","alias":"","steps":"Sırtüstü yatış, diz 0° ve 30° fleksiyonda. Femurun distalini sabitleyin, bacağa valgus veya varus yönünde kuvvet uygulayın.","positive":"Eklem aralığında ağrı veya sağlam taraftan fazla açılma.","tissue":"Valgus = MKB, varus = LKB","point":"Yalnız 30°'de pozitif: izole kollateral bağ yaralanması. 0°'de de pozitif: eşlik eden yaralanma şüphesi."}]},"keypoints":["ÖÇB değerlendirmesinde ilk tercih Lachman testidir; daima sağlam tarafla karşılaştırın","Anamnezde dizin boşalmasını, patlama sesini ve hızlı şişliği sorun","Arka çekmece testinden önce sag belirtisiyle tibianın konumunu kontrol edin","Kollateral bağları hem 0°'de hem 30° fleksiyonda zorlayın","Koruyucu gerginlik yalancı negatif verir; gevşek pozisyonda değerlendirin"],"case":{"text":"20 yaşında kadın. Basketbolda yere inerken dizi içe doğru burkuldu. Patlama sesi duydu, diz hemen şişti. Lachman testinde öne kayma sağlam taraftan fazla, son his belirsiz.","answer":"ÖÇB yaralanmasını düşündüren bulgu. Eşlik eden menisküs ve kollateral bağ yaralanmasını da değerlendirin ve görüntüleme için hekime yönlendirin. Belirgin şişlik ve ağrı varken güçlü stres testlerini tekrarlamayın."},"questions":[{"level":"Temel","q":"Şekilde hangi test diz 20–30° fleksiyondayken tibiayı öne çeker?","options":["Ön çekmece testi","Lachman testi","Arka çekmece testi","Valgus stres testi"],"answer":1,"exp":"Lachman testi diz 20–30° fleksiyondayken tibiayı öne çeker ve ÖÇB'yi değerlendirir. Ön çekmece testi diz 90°'deyken yapılır."},{"level":"Temel","q":"Şekilde varus stres testi hangi bağı değerlendirir?","options":["Medial kollateral bağ (MKB)","Ön çapraz bağ (ÖÇB)","Lateral kollateral bağ (LKB)","Arka çapraz bağ (AÇB)"],"answer":2,"exp":"Varus stresi dizin lateralini açar, böylece lateral kollateral bağı (LKB) değerlendirir. Valgus stresi MKB'yi değerlendirir."},{"level":"Orta","q":"Pozitif arka çekmece testi hangi yaralanmayı düşündürür?","options":["AÇB yaralanması","ÖÇB yaralanması","LKB yaralanması","Patella çıkığı"],"answer":0,"exp":"Arka çekmece testi diz 90° fleksiyondayken tibiayı geriye iter ve arka çapraz bağı (AÇB) değerlendirir."},{"level":"Orta","q":"Valgus stres testi diz 0°'deyken de pozitifse önce ne düşünürsünüz?","options":["Hafif, izole MKB yaralanması","Yalnız lateral menisküs yaralanması","Patellar instabilite","Eşlik eden (ör. çapraz bağ) yaralanma"],"answer":3,"exp":"Ekstansiyonda çapraz bağlar ve eklem kapsülü de stabilize eder. 0°'de de aralık açılıyorsa izole MKB değil, eşlik eden yaralanma şüphesi vardır."},{"level":"Klinik","q":"25 yaşında erkek. Futbolda diz bükülüyken tibia önüne sert darbe aldı. 90° fleksiyonda tibia arkaya düştü. En olası tanı nedir?","options":["ÖÇB yaralanması","AÇB yaralanması","MKB yaralanması","Medial menisküs yaralanması"],"answer":1,"exp":"Tibia ön yüzüne gelen kuvvet ve sag belirtisi tipik AÇB yaralanmasıdır. Arka çekmece testiyle doğrulayın ve tıbbi tanı için yönlendirin."},{"level":"Klinik","q":"30 yaşında kadın. Kayak yaparken dizi valgusa burkuldu. Valgus streste 30° fleksiyonda ağrı ve açılma var, 0°'de stabil. En olası tanı nedir?","options":["İzole ÖÇB yaralanması","LKB yaralanması","İzole MKB yaralanması","AÇB yaralanması"],"answer":2,"exp":"Valgus mekanizması ve yalnız 30°'de pozitif test izole MKB yaralanmasını düşündürür. 0°'de de pozitifse eşlik eden yaralanma düşünülmelidir."}],"seccion":"Bölgelere göre özel testler","grupo":"Kalça ve diz","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"Lachman testi","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"Diz: Menisküsler ve Patella","lead":"Menisküs ve patella testleriyle dönme veya yere inme sırasında ortaya çıkan diz ağrısı, takılma ve instabilite hissinin nedeni aranır. Karar birden fazla bulgunun birlikte değerlendirilmesiyle verilir.","sheet":{"kind":"tests","tests":[{"name":"McMurray testi","alias":"","steps":"Sırtüstü yatış; dizi maksimum fleksiyona getirin, ardından bacağı dışa veya içe rotasyonda tutarak yavaşça ekstansiyona getirin.","positive":"Eklem aralığında klik veya ağrı.","tissue":"Menisküs (medial ve lateral)","point":"Dış rotasyon medial, iç rotasyon lateral menisküsü değerlendirir. Tek başına tanı koydurmaz."},{"name":"Apley testi","alias":"Apley kompresyon testi","steps":"Yüzüstü yatış, diz 90° fleksiyonda. Topuktan aşağı doğru basınç uygularken bacağı içe ve dışa rotasyona getirin.","positive":"Kompresyon ve rotasyonla eklem aralığında ağrı.","tissue":"Menisküs","point":"Distraksiyonla rotasyonda ağrı varsa daha çok bağ veya menisküs dışı bir yapı düşünün."},{"name":"Thessaly testi","alias":"","steps":"Fizyoterapist hastanın iki elini tutar. Tek ayak üstünde, diz 20° fleksiyonda hasta gövdesini ve dizini içe–dışa döndürür. Sağlam taraftan başlanır.","positive":"Eklem aralığında ağrı, kilitlenme veya takılma hissi.","tissue":"Menisküs","point":"Yük altında yapılan testtir. Düşmeye dikkat edin, iki elden destek sağlayın."},{"name":"Patellar aprehensiyon testi","alias":"","steps":"Sırtüstü yatış, diz hafif fleksiyonda. M. quadriceps femoris gevşekken patellayı yavaşça laterale itin.","positive":"Korku ortaya çıkar, hasta quadricepsi kasarak korunur.","tissue":"Patella stabilizatörleri (MPFL)","point":"Geçirilmiş patella çıkığı veya subluksasyonunu göstermede yararlıdır. Nazik yapın, çıkık provoke etmeyin."}]},"keypoints":["Eklem aralığında ağrı, menisküs yaralanmasını düşündüren önemli bir bulgudur","Menisküs testleri tek başına belirleyici değildir; birden fazla bulguyu karşılaştırın","Tam ekstansiyonu engelleyen kilitlenme (locking) hekim konsültasyonu gerektirir","Patella testlerinde korku tepkisini izleyin ve testi nazik yapın","Yük altındaki testlerde düşmeyi önlemek için destek sağlayın"],"case":{"text":"35 yaşında erkek. Diz bükülüyken dönme hareketi yaptı, birkaç saat sonra diz şişti. Merdivende dizin iç tarafında takılma hissediyor. Medial eklem aralığı hassas, McMurray testi ağrılı ve klikli.","answer":"Medial menisküs yaralanması şüphesi. Eşlik eden bağ yaralanmasını da değerlendirin ve görüntüleme için hekime yönlendirin. Kilitlenme varsa ekstansiyonu zorlamayın."},"questions":[{"level":"Temel","q":"Şekilde hangi test yüzüstü yatışta, diz 90°'deyken kompresyon ve rotasyon uygular?","options":["McMurray testi","Thessaly testi","Apley testi","Patellar aprehensiyon testi"],"answer":2,"exp":"Apley testi yüzüstü yatışta, diz 90° fleksiyondayken topuktan basınçla rotasyon uygular ve menisküsü değerlendirir."},{"level":"Temel","q":"Şeklin özetine göre hangi bulgu menisküs yaralanmasını düşündürür?","options":["Eklem aralığında ağrı","Patella üzerinde ağrı","Tuberositas tibiada ağrı","Uyluk arka yüzünde ağrı"],"answer":0,"exp":"Eklem aralığındaki (femur ile tibia arasındaki aralık) ağrı menisküs yaralanmasını düşündürür."},{"level":"Orta","q":"McMurray testinde bacak dış rotasyondayken yapılan ekstansiyon öncelikle neyi değerlendirir?","options":["Lateral menisküs","Medial menisküs","Ön çapraz bağ","Patellar tendon"],"answer":1,"exp":"Dış rotasyonla medial, iç rotasyonla lateral menisküs değerlendirilir."},{"level":"Orta","q":"Patellar aprehensiyon testinde pozitif bulgu nedir?","options":["Patellada klik","Medial eklem aralığında ağrı","Kısıtlı diz ekstansiyonu","Korku ve quadriceps ile korunma"],"answer":3,"exp":"Patella laterale itilirken hasta korku gösterip quadricepsle korunuyorsa test pozitiftir: patellar instabiliteyi düşündürür."},{"level":"Klinik","q":"18 yaşında kadın. Sıçrayıp yere inerken patellasının yerinden çıkıp kendiliğinden geri girdiğini hissetti. En uygun değerlendirme hangisidir?","options":["Patellar aprehensiyon testi","Arka çekmece testi","Thompson testi","Varus stres testi"],"answer":0,"exp":"Patella çıkığı veya subluksasyonunu düşündüren öykü. İnstabiliteyi patellar aprehensiyon testiyle kontrol edersiniz."},{"level":"Klinik","q":"40 yaşında erkek. Uzun süredir dizinin içinde takılma var, bu sabahtan beri dizini tam düzeltemiyor. Doğru yaklaşım nedir?","options":["Güçlü pasif ekstansiyonla yerine oturtmak","Hekime yönlendirip tetkik istemek","Thessaly testini tekrarlamak","Hemen kuvvetlendirmeye başlamak"],"answer":1,"exp":"Ekstansiyonu engelleyen kilitlenme sıkışmış bir menisküsü düşündürebilir; hekim değerlendirmesi gerekir. Zorlamalı ekstansiyondan ve test tekrarından kaçının."}],"seccion":"Bölgelere göre özel testler","grupo":"Kalça ve diz","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"McMurray testi","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"Ayak Bileği ve Ayak","lead":"Ayak bileği ve ayak testleriyle burkulmaya bağlı bağ yaralanması ile Aşil tendonu yırtığı ayırt edilir. Kırık olasılığı her zaman akılda tutulmalıdır.","sheet":{"kind":"tests","tests":[{"name":"Thompson testi","alias":"Simmonds testi","steps":"Yüzüstü yatış, ayak yatağın kenarından sarkar. M. triceps surae kas karnını sıkın.","positive":"Ayak bileğinde plantar fleksiyon yok veya sağlam taraftan belirgin şekilde az.","tissue":"Aşil tendonu","point":"Yırtıkta da aktif plantar fleksiyon (ör. ayak parmağı fleksörleriyle) olabilir; bu yüzden test değerlidir."},{"name":"Ön çekmece testi (ayak bileği)","alias":"","steps":"Oturma veya sırtüstü yatış, ayak bileği hafif plantar fleksiyonda. Distal tibiayı sabitleyin, topuğu kavrayıp talusu öne çekin.","positive":"Sağlam taraftan fazla öne kayma, belirsiz son his.","tissue":"Ön talofibular bağ (ATFL)","point":"İnversiyon burkulmasında en sık yaralanan bağı değerlendirir. Akut dönemde ağrıyı gözeterek yapın."},{"name":"Talar tilt testi","alias":"Varus stres testi","steps":"Bacağın distalini sabitleyin, kalkaneusu kavrayıp ayak bileğini inversiyon yönünde eğin.","positive":"Sağlam taraftan fazla talus eğimi, ağrı.","tissue":"Kalkaneofibular bağ (CFL) (ATFL)","point":"Ön çekmece testiyle birlikte lateral bağ yaralanmasının şiddetini değerlendirin."},{"name":"Squeeze testi","alias":"","steps":"Sırtüstü yatış. Bacağın ortasında tibia ve fibulayı iki elle birbirine doğru sıkın.","positive":"Ayak bileği üstünde, tibia ile fibula arasında ağrı.","tissue":"Distal tibiofibular bağlar (sindezmoz)","point":"Yüksek ayak bileği burkulması şüphesinde kullanın. Kırığı dışlamak da önemlidir."}]},"keypoints":["İnversiyon burkulmasında en sık ön talofibular bağ (ATFL) yaralanır","Aşil tendonu yırtığında da aktif plantar fleksiyon olabilir","Kemik hassasiyeti veya yük verememe varsa kırık düşünün, hekime yönlendirin","Bağ testlerini daima sağlam tarafla karşılaştırarak değerlendirin","Tibia ile fibula arasındaki ağrı yüksek ayak bileği burkulmasını düşündürebilir"],"case":{"text":"45 yaşında erkek. Tenis oynarken arkadan tekme yemiş gibi hissetti. Parmak ucunda duramıyor. Yüzüstü yatışta m. triceps surae sıkıldığında plantar fleksiyon oluşmuyor.","answer":"Pozitif Thompson testi: Aşil tendonu yırtığı şüphesi. Acilen hekim değerlendirmesine yönlendirin. Aktif plantar fleksiyonun olması yırtığı dışlamaz."},"questions":[{"level":"Temel","q":"Thompson testi hangi yapıyı değerlendirir?","options":["Ön talofibular bağ","Aşil tendonu","Kalkaneofibular bağ","Plantar fasya (aponeurosis plantaris)"],"answer":1,"exp":"M. triceps surae sıkıldığında plantar fleksiyon oluşup oluşmadığına bakılır: Aşil tendonunun devamlılığını değerlendirir."},{"level":"Temel","q":"İnversiyon burkulmasında en sık hangi bağ yaralanır?","options":["Arka talofibular bağ","Deltoid bağ","Kalkaneofibular bağ","Ön talofibular bağ"],"answer":3,"exp":"Yaralanma çoğunlukla plantar fleksiyonla birlikte inversiyonda oluşur; en sık ön talofibular bağ yaralanır. Ağır olgularda kalkaneofibular bağ da."},{"level":"Orta","q":"Talar tilt testi öncelikle hangi bağı değerlendirir?","options":["Kalkaneofibular bağ","Deltoid bağ","Aşil tendonu","M. tibialis posterior tendonu"],"answer":0,"exp":"Kalkaneus inversiyona eğilerek talusun eğimi izlenir; böylece öncelikle kalkaneofibular bağ değerlendirilir."},{"level":"Orta","q":"Squeeze testinde ayak bileği üstünde ağrı oluşuyor. Ne düşünürsünüz?","options":["Aşil tendonu yırtığı","Plantar fasiit","Distal tibiofibular bağ yaralanması","Halluks valgus"],"answer":2,"exp":"Bacak ortasının sıkılması distal tibiofibular eklemde ağrı yapıyorsa sindezmoz yaralanması (yüksek ayak bileği burkulması) şüphesi vardır."},{"level":"Klinik","q":"22 yaşında erkek, inversiyon yaralanması. Lateral malleol önünde şişlik ve hassasiyet var; kemik hassasiyeti yok. ATFL'yi hangi test değerlendirir?","options":["Ön çekmece testi (ayak bileği)","Thompson testi","Lachman testi","Squeeze testi"],"answer":0,"exp":"Ön talofibular bağ talusun öne kaymasını sınırlar. Ayak bileği ön çekmece testiyle, sağlam tarafla karşılaştırarak değerlendirirsiniz."},{"level":"Klinik","q":"60 yaşında kadın. Düşüp ayak bileğini burktu. Lateral malleolde kemik hassasiyeti var, yük vererek yürüyemiyor. Doğru yaklaşım nedir?","options":["Ön çekmece testini tekrarlamak","Kırık şüphesiyle hekime yönlendirmek","Hemen denge egzersizleri","Bantlayarak yürüme çalışması"],"answer":1,"exp":"Kemik hassasiyeti ve yük verememe kırığı düşündürür. Stres testi ve egzersizden önce hekim değerlendirmesi gerekir."}],"seccion":"Bölgelere göre özel testler","grupo":"Ayak bileği ve ayak","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"Thompson testi","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"Thompson testi","rotulo":"Değerlendirdiği yapı","texto":"Aşil tendonu","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"Nörolojik ve Nörodinamik Testler","lead":"Nörodinamik testlerde sinir sistemi adım adım gerilir ve semptomların yeniden ortaya çıkışı izlenir. Sinir kökü kaynaklı ağrıyı periferik sinir kaynaklı ağrıdan ayırmaya yardımcı olur.","sheet":{"kind":"tests","tests":[{"name":"Lasègue testi (DBK testi)","alias":"Düz bacak kaldırma testi","steps":"Sırtüstü yatışta diz düz bacağı pasif kaldırın. Semptomun başladığı açıyı kaydedin, dorsifleksiyonla artışı kontrol edin.","positive":"Semptomlar tekrarlanır, ör. kalçadan bacak arka yüzüne yayılan ağrı.","tissue":"Siyatik sinir, L5 ve S1 sinir kökleri vb.","point":"Hamstring gerginliğini ayırmak için ayak bileği dorsifleksiyonu veya boyun fleksiyonu eklemek yararlıdır."},{"name":"Femoral sinir germe testi","alias":"FNST (ters Lasègue)","steps":"Yüzüstü yatışta dizi pasif fleksiyona getirin. Gerekirse kalça ekstansiyonu da ekleyin.","positive":"Uyluk ön yüzüne yayılan ağrı.","tissue":"Femoral sinir, L2–L4 sinir kökleri","point":"Quadriceps gerginliğinden ayırın. Üst lomber sinir kökü tutulumunu değerlendirmede kullanılır."},{"name":"Slump testi","alias":"","steps":"Oturarak sırayla: gövde fleksiyonu → boyun fleksiyonu → diz ekstansiyonu → dorsifleksiyon; sonra boyun fleksiyonunu bırakıp değişimi izleyin.","positive":"Semptomlar tekrarlanır ve boyun fleksiyonu bırakılınca azalır.","tissue":"Spinal kanaldan alt ekstremiteye sinir sistemi","point":"Adım adım ilerleyin, semptom ortaya çıkınca durun. İki tarafı karşılaştırın."},{"name":"Üst ekstremite sinir germe testi","alias":"ULNT1 (median sinir)","steps":"Sırtüstü: omuz kuşağı depresyonu, abdüksiyon, supinasyon, el bileği ve parmak ekstansiyonu, dış rotasyon, dirsek ekstansiyonu; sonda boyun lateral fleksiyonu.","positive":"Kol semptomları tekrarlanır ve boyun lateral fleksiyonuyla değişir.","tissue":"Median sinir, servikal sinir kökleri","point":"Sağlam tarafla karşılaştırın. Uzak bir bölgenin hareketi semptomu değiştiriyorsa sinir kaynağı olasıdır."}]},"keypoints":["Sinir testlerini semptom tekrarına ve taraf farkına göre değerlendirin","Uzak bir bölgenin hareketi semptomu değiştiriyorsa sinir kaynağı düşünün","Kas gerginliğini ve sinir kaynaklı semptomu ayrı kaydedin","Semptom ortaya çıkınca durun, şiddetli ağrı provoke etmeyin","İlerleyen felç veya mesane-barsak bozukluğunda hemen hekime yönlendirin"],"case":{"text":"42 yaşında erkek. Ağır yük kaldırdıktan sonra bel ağrısı ve sağ bacak arka yüzünde ağrı başladı. DBK testi sağ bacak arka yüzünde yayılan ağrıyı tekrarlıyor, dorsifleksiyonla artıyor.","answer":"Lomber sinir kökü kaynaklı semptomları düşündüren bulgu. Kas kuvveti, duyu ve reflekslerle etkilenen segmenti belirleyin. Mesane-barsak bozukluğu veya ilerleyen felç varsa hemen hekime yönlendirin."},"questions":[{"level":"Temel","q":"DBK testi öncelikle hangi siniri gerer?","options":["Median sinir","Femoral sinir","Siyatik sinir","Ulnar sinir"],"answer":2,"exp":"Diz düzken bacak kaldırıldığında arka yüzde seyreden siyatik sinir ve alt lomber sinir kökleri gerilir."},{"level":"Temel","q":"Femoral sinir germe testi hangi pozisyonda yapılır?","options":["Yüzüstü yatış","Sırtüstü yatış","Uzun oturma","Ayakta durma"],"answer":0,"exp":"Yüzüstü yatışta diz fleksiyona getirilerek uyluk ön yüzünde seyreden femoral sinir gerilir."},{"level":"Orta","q":"DBK testinde ayak bileği dorsifleksiyonu semptomları artırdı. Bu neyi düşündürür?","options":["Hamstring kısalığı","Sinir kaynaklı semptom","Kalça kontraktürü","Ayak bileği burkulması"],"answer":1,"exp":"Dorsifleksiyon kas boyunu değiştirmeden sinir gerginliğini artırır. Semptom artıyorsa sinir kaynağını düşündürür."},{"level":"Orta","q":"Slump testinde boyun fleksiyonu bırakılınca bacak semptomları azaldı. Ne düşünürsünüz?","options":["Kas germe ağrısı","Eklem instabilitesi","Psikojenik ağrı","Sinir sisteminin artmış duyarlılığı"],"answer":3,"exp":"Boyun hareketi bacak kaslarını etkilemez; bu yüzden semptom değişimi sinir sistemi tutulumunu düşündürür."},{"level":"Klinik","q":"50 yaşında kadın. Uyluk önünden diz iç yüzüne uyuşma var. Yüzüstü diz fleksiyonu uyluk ön ağrısını tekrarlıyor. Hangi segment şüphelidir?","options":["L2–L4","L5","S1","C6"],"answer":0,"exp":"Pozitif femoral sinir germe testi ve uyluk ön yüzü semptomları: üst lomber (L2–L4) sinir kökü tutulumu şüphesi."},{"level":"Klinik","q":"38 yaşında erkek. DBK testi bacak ağrısını tekrarlıyor. Son zamanlarda idrar yapmakta zorlanıyor, perinede duyu azalmış. Doğru yaklaşım nedir?","options":["DBK testini tekrar kontrol etmek","Lomber kas kuvvetlendirme","Hemen hekime yönlendirmek","Sinir kaydırmaya devam etmek"],"answer":2,"exp":"İdrar bozukluğu ve perine duyu kaybı kauda ekuina sendromunu düşündüren kırmızı bayraktır. Acil hekim değerlendirmesi gerekir."}],"seccion":"Bölgelere göre özel testler","grupo":"Nörolojik testler","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"Lasègue testi (DBK testi)","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"Lasègue testi","rotulo":"Değerlendirdiği yapı","texto":"siyatik sinir (L4–S1)","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"Subakromiyal Sıkışma ve Rotator Manşet Yırtığı","lead":"Subakromiyal sıkışmada kol kaldırılırken rotator manşet ve subakromiyal bursa irrite olur ve ağrı yapar. Rotator manşet yırtığından ayırmak ve kademeli terapötik egzersiz vermek önemlidir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Kol kaldırılırken rotator manşet (özellikle m. supraspinatus tendonu) ve subakromiyal bursa irrite olur ve ağrır. Yaş, aşırı yüklenme veya travmayla rotator manşet yırtığı gelişebilir."},{"h":"Ana semptomlar","t":"Kol kaldırırken ağrı (ağrılı ark), gece ağrısı, etkilenen tarafa yatmada zorluk. Yırtıkta kaldırma ve dış rotasyon kuvveti azalır."},{"h":"Değerlendirme noktaları","t":"Neer ve Hawkins-Kennedy testiyle sıkışmayı, Jobe testi ve dış rotasyon kuvvetiyle rotator manşet işlevini değerlendirin. Skapula hareketini ve postürü de inceleyin."},{"h":"Tedavi akışı","t":"Ağrı kontrolü ve aktivite düzenleme → EHA'yı artırma → rotator manşet ve skapular kasların kademeli kuvvetlendirilmesi → hareket eğitimi, işe ve spora dönüş."},{"h":"Dikkat, kontrendikasyon","t":"Ağrıyı artıran tekrarlı kaldırmadan kaçının. Yüklemeyi yırtığın derecesine ve hekim planına göre ayarlayın, germeyi zorlamayın."},{"h":"Hekime yönlendirme","t":"Travma sonrası ani kol kaldıramama, ilerleyen güçsüzlük, kötüleşen istirahat ağrısı, ateş veya şişlik, uyuşma ve diğer nörolojik semptomlar."}]},"keypoints":["Ağrılı ark ve gece ağrısı sık görülen yakınmalardır","Kaldırma ve dış rotasyonda güçsüzlük rotator manşet yırtığını düşündürebilir","Skapula hareketini ve postürü de değerlendirin","Egzersiz yükünü ağrı sınırında, kademeli artırın","Travma sonrası ani kol kaldıramamada hekime yönlendirin"],"case":{"text":"62 yaşında erkek. Aylardır abdüksiyonda omzu ağrıyor, gece ağrısı da var. Kaldırmanın orta açıklığında ağrı belirgin, Jobe testi ağrılı ve güçsüzlük de görülüyor.","answer":"M. supraspinatus tendon hasarı veya rotator manşet yırtığı şüphesi. Hekimin görüntüleme sonucunu ve planını öğrenin; ağrı sınırında EHA, rotator manşet ve skapular kas egzersizleriyle ilerleyin. Ağrıyı artıran tekrarlı kaldırmadan kaçının."},"questions":[{"level":"Temel","q":"Akromiyonun altından geçen ve kol kaldırılırken kolayca irrite olan tendon hangisidir?","options":["M. supraspinatus tendonu","M. teres minor tendonu","M. pectoralis major tendonu","M. triceps brachii tendonu"],"answer":0,"exp":"M. supraspinatus tendonu akromiyonun altından geçer; bu yüzden kol kaldırılırken subakromiyal bursayla birlikte kolayca irrite olur."},{"level":"Temel","q":"Omuz kaldırmanın yalnız orta açıklığında ağrı olmasına ne denir?","options":["Omuz-el sendromu","Gece ağrısı","Ağrılı ark","Drop arm belirtisi"],"answer":2,"exp":"Kaldırma sırasında ağrı çıkıp daha yukarıda azalıyorsa buna ağrılı ark denir. Subakromiyal sorunlarda görülür."},{"level":"Orta","q":"Hawkins-Kennedy testi öncelikle neyi değerlendirir?","options":["Anterior omuz instabilitesi","Subakromiyal sıkışma","Akromiyoklaviküler çıkık","Torasik çıkış sendromu"],"answer":1,"exp":"Omuz 90° fleksiyondayken iç rotasyon verilerek yapıların akromiyon altında sıkışıp ağrıyıp ağrımadığına bakılır: sıkışma testidir."},{"level":"Orta","q":"Hangi bulgu en çok rotator manşet yırtığını düşündürür?","options":["Kısıtlı dirsek fleksiyonu","Artmış kavrama kuvveti","Yalnız parmak uyuşması","Kaldırma ve dış rotasyonda güçsüzlük"],"answer":3,"exp":"Rotator manşet kaldırma ve dış rotasyonda görev alır. Güçsüzlük yırtığı düşündürebilir; tıbbi görüntülemeyle doğrulanır."},{"level":"Klinik","q":"58 yaşında kadın. Düştüğünden beri kolunu kaldıramıyor. Pasif kaldırılabiliyor, aktif kaldıramıyor. En olası tanı nedir?","options":["Donuk omuz","Rotator manşet yırtığı","Servikal spondiloz","Omuz çıkığı"],"answer":1,"exp":"Pasif hareket var ama aktif kaldırma yoksa kas-tendon işlev bozukluğu düşünülür; travma sonrası rotator manşet yırtığı şüphelidir. Donuk omuzda pasif hareket de kısıtlıdır."},{"level":"Klinik","q":"45 yaşında erkek, uzun süreli kaldırma ağrılı subakromiyal sıkışma. Uygun başlangıç terapötik egzersizi hangisidir?","options":["Ağrıya katlanarak tekrarlı kaldırma","Ağır dambılla kaldırma","Ağrı sınırında rotator manşet egzersizi","Tam istirahati sürdürmek"],"answer":2,"exp":"Ağrıyı artırmayan rotator manşet ve skapular kas egzersizleriyle başlayın ve yükü kademeli artırın."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"Donuk Omuz","lead":"Donuk omuzda ağrı ve hareket kısıtlılığı yavaş yavaş gelişir; orta ve ileri yaşta sıktır. Tedavi hastalığın fazına göre ayarlanmalıdır.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Omuz eklem kapsülünün enflamasyonu ve fibrozisi ağrı ve hareket kısıtlılığı yapar. Neden çoğu zaman belirsizdir; diyabetle ilişkisi bildirilmiştir."},{"h":"Ana semptomlar","t":"Gece ağrısı, saç taramada ve eli arkaya götürmede zorluk. Aktif ve pasif EHA birlikte azalır, özellikle dış rotasyon."},{"h":"Değerlendirme noktaları","t":"Aktif ve pasif EHA'yı karşılaştırın; ağrı düzeyini, gece ağrısını ve ADL güçlüklerini değerlendirin. Rotator manşet yırtığı gibi diğer tablolardan ayırmak önemlidir."},{"h":"Faza göre rehabilitasyon","t":"Enflamatuvar faz: ağrı kontrolü ve koruyucu hareket. Donma fazı: ağrı sınırında germe ve EHA egzersizi. Çözülme fazı: EHA ve kas kuvvetinin geri kazanılması."},{"h":"Dikkat, kontrendikasyon","t":"Enflamatuvar fazda güçlü germe ağrıyı artırabilir. Ağrıya katlanmayı gerektiren zorlamalı pasif hareketten kaçının."},{"h":"Hekime yönlendirme","t":"Travma sonrası başlangıç, ani güçsüzlük, ateş veya şişlik, genel semptomlar (ör. kilo kaybı), istirahat ağrısının ani kötüleşmesi."}]},"keypoints":["Aktif ve pasif EHA'nın birlikte azalması tipiktir","Özellikle dış rotasyon kısıtlılığı dikkat çeker","Enflamatuvar fazda ağrıyı artıran germeden kaçının","Her fazda tedavi hedefini değiştirin","Rotator manşet yırtığı gibi diğer tablolardan ayırın"],"case":{"text":"55 yaşında kadın. Belirgin bir neden olmadan omzu ağrımaya başladı, geceleri ağrıdan uyuyamıyor. Birkaç ayda saç taramak ve eli arkaya götürmek zorlaştı; dış rotasyon aktif ve pasif olarak belirgin kısıtlı.","answer":"Donuk omuz şüphesi. Diğer tabloları hekim tanısıyla dışlayın ve mevcut fazı belirleyin. Şiddetli ağrı döneminde güçlü germeden kaçının; ağrı kontrolü ve koruyucu hareketle başlayın."},"questions":[{"level":"Temel","q":"Donuk omuzda özellikle hangi hareket kısıtlıdır?","options":["Dirsek fleksiyonu","El bileği dorsifleksiyonu","Skapula elevasyonu","Omuz dış rotasyonu"],"answer":3,"exp":"Donuk omuzda kapsül büzüşmesi nedeniyle omuz birçok yönde kısıtlanır, özellikle dış rotasyon."},{"level":"Temel","q":"Donuk omuzda ağrının azaldığı ve hareket kısıtlılığının öne çıktığı faz hangisidir?","options":["Enflamatuvar faz","Donma fazı","Çözülme fazı","Akut faz"],"answer":1,"exp":"Enflamatuvar fazın şiddetli ağrısı azalınca hareket kısıtlılığıyla seyreden donma fazı, ardından çözülme fazı gelir."},{"level":"Orta","q":"Donuk omuzu rotator manşet yırtığından ayırmaya hangi bulgu yardımcı olur?","options":["Gece ağrısının varlığı","Pasif EHA'nın kısıtlı olması","Yaş","Ağrının yeri"],"answer":1,"exp":"Donuk omuzda pasif EHA da kısıtlıdır. Rotator manşet yırtığında pasif hareket görece iyidir, ancak aktif kaldırma çoğu zaman zordur."},{"level":"Orta","q":"Donuk omuzun enflamatuvar fazında en uygun tedavi hangisidir?","options":["Ağrı kontrolü, koruyucu hareket","Güçlü pasif germe","Yüksek yüklü kuvvetlendirme","Spora dönüş çalışması"],"answer":0,"exp":"Enflamatuvar fazda ağrı şiddetlidir, güçlü germe kötüleştirebilir. Ağrı kontrolü ve ağrıyı artırmayan hareket temel unsurdur."},{"level":"Klinik","q":"52 yaşında kadın, donma fazında donuk omuz. Ağrı hafif, dış rotasyon ve eli arkaya götürme kısıtlı. Uygun tedavi nedir?","options":["Tam istirahat","Askı ile sabitleme","Ağrı sınırında EHA egzersizi","Ağrıya katlanarak güçlü germe"],"answer":2,"exp":"Donma fazında ağrı azalmıştır; bu yüzden ağrı sınırında germe ve EHA egzersizleriyle ilerleyin."},{"level":"Klinik","q":"60 yaşında erkek. Omuz ağrısı ve hareket kısıtlılığının yanında son zamanlarda kilo kaybetmiş ve şiddetli istirahat ağrısı var. Doğru yaklaşım nedir?","options":["Hekime yönlendirmek","EHA egzersizlerini artırmak","Yalnız sıcak uygulama ve izlem","Kuvvetlendirmeye başlamak"],"answer":0,"exp":"Kilo kaybı ve şiddetli istirahat ağrısı ciddi hastalığı düşündüren kırmızı bayraktır. Önce hekim değerlendirmesine yönlendirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"Rotator Manşet Onarımı Sonrası","lead":"Rotator manşet onarımı sonrası rehabilitasyon, onarılan tendonu korurken EHA ve kas kuvvetini kademeli olarak geri kazandırır. Hekimin belirlediği zamanlamaya ve kısıtlamalara uymak temel koşuldur.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Yırtık rotator manşet cerrahiyle kemiğe yeniden tespit edilir. Onarılan tendonun kemiğe iyileşmesi zaman alır; çok erken yükleme yeniden yırtığa yol açabilir."},{"h":"Ana semptomlar","t":"Postoperatif ve gece ağrısı, hareket kısıtlılığı, güçsüzlük. Ortez nedeniyle omuz kuşağı ve boyun gerilebilir, dirsek ve el hareketi de azalabilir."},{"h":"Değerlendirme noktaları","t":"Ağrıyı, pasif ve aktif EHA'yı, skapula hareketini, kas kuvvetini ve ADL'yi değerlendirin. Ameliyat notunu ve hekim talimatını (yasak pozisyonlar, zamanlama) inceleyin."},{"h":"Faza göre rehabilitasyon","t":"Koruma fazı (ortez, pasif hareket) → aktif yardımlı ve aktif hareket → kademeli kuvvetlendirme → günlük yaşama, işe ve spora dönüş."},{"h":"Dikkat, kontrendikasyon","t":"Belirlenen zamandan önce aktif kaldırma ve dirençli egzersizden, onarılan tendonu güçlü geren pozisyonlardan kaçının. Sabitleme sırasında da dirsek ve parmakları hareket ettirin."},{"h":"Hekime yönlendirme","t":"Ağrının ani artışı veya kaldırma kuvvetinin azalması (yeniden yırtık şüphesi), yara çevresinde kızarıklık, şişlik, ısı artışı, ateş, uyuşma."}]},"keypoints":["Zamanlamayı ve yasak pozisyonları hekim talimatı ve ameliyat notundan kontrol edin","Koruma fazında onarılan tendonu koruyun; merkezde pasif hareket vardır","Sabitleme sırasında da dirsek, parmak ve skapula egzersizlerini yaptırın","Dirençli egzersizi belirlenen zamandan itibaren kademeli verin","Kaldırma kuvveti aniden azalırsa yeniden yırtık düşünün, hekime yönlendirin"],"case":{"text":"60 yaşında erkek, rotator manşet onarımı sonrası erken postoperatif dönemde, ortez kullanıyor. İşe çabuk dönmek istediği için kendi kendine kol kaldırma çalışmış.","answer":"Koruma fazında talimat dışı aktif kaldırma onarılan tendonu zorlar. Hekim talimatını kontrol edin, izin verilen pasif harekete ve dirsek-parmak egzersizlerine odaklanın ve zamanlamaya uymanın neden önemli olduğunu açıklayın."},"questions":[{"level":"Temel","q":"Rotator manşet onarımı sonrası erken dönemde ortezin temel amacı nedir?","options":["Kas kuvvetini artırmak","EHA'yı artırmak","Onarılan tendonu korumak","Ödemi önlemek"],"answer":2,"exp":"Koruma fazında ortez sabitler ve onarılan tendon kemiğe iyileşene kadar onu korur."},{"level":"Temel","q":"Rotator manşet onarımı sonrası rehabilitasyonda en son ne eklenir?","options":["Ortezle sabitleme","Pasif hareket","Aktif yardımlı hareket","Dirençli egzersiz"],"answer":3,"exp":"Koruma fazındaki sabitleme ve pasif hareketten sonra aktif yardımlı ve aktif hareket, en son dirençli kuvvetlendirme gelir."},{"level":"Orta","q":"Onarım sonrası koruma fazında hangi hareketten kaçınılmalıdır?","options":["Omzun zamanından önce aktif kaldırılması","Dirseğin aktif fleksiyon-ekstansiyonu","Parmak egzersizleri","Talimat verilen pasif hareket"],"answer":0,"exp":"Koruma fazında talimat dışı aktif omuz kaldırma onarılan tendonu zorlar. Dirsek ve parmak hareketleri sabitleme sırasında da sürdürülür."},{"level":"Orta","q":"Postoperatif egzersiz akışını planlarken önce neyi kontrol etmelisiniz?","options":["Yalnız hastanın isteğini","Hekim talimatını ve ameliyat notunu","Sağlam tarafın kas kuvvetini","Yalnız yaşı"],"answer":1,"exp":"Yırtık boyutu ve onarım tekniğine göre zamanlama ve yasak pozisyonlar değişir; bu yüzden talimatı ve ameliyat notunu inceleyin."},{"level":"Klinik","q":"65 yaşında kadın, manşet onarımı sonrası iyi ilerliyordu; bir eşyayı kaldırırken ağrı hissetti ve aniden kolunu kaldıramıyor. Ne yaparsınız?","options":["Dirençli egzersizi artırmak","Aynı egzersizlere devam etmek","Güçlü germe","Hekime bildirip tetkik istemek"],"answer":3,"exp":"Ani ağrı ve kaldırma kuvvetinde azalma yeniden yırtığı düşündürebilir. Egzersizleri durdurun ve hekim değerlendirmesi isteyin."},{"level":"Klinik","q":"58 yaşında erkek, manşet onarımı sonrası ortezde. Dirsek ve parmak sertliğinden yakınıyor. Doğru yaklaşım nedir?","options":["Dirsek ve parmak egzersizlerini öğretmek","Omzun aktif kaldırılmasına başlamak","Hiçbir şey, sabitlemeye devam","Dirençli omuz egzersizi"],"answer":0,"exp":"Sertliği önlemek için sabitleme sırasında da dirsek ve parmakları hareket ettirin. Aktif omuz kaldırma ve direnç belirlenen zamanı beklemelidir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omuz","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"Tendinopatiler","lead":"Tendinopatide tendon tekrarlayan yüke uyum sağlayamaz; ağrı ve işlev kaybı gelişir. İyileşmenin anahtarı istirahat değil, yükün düzenlenmesi ve kademeli artırılmasıdır.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Tendona binen tekrarlayan yük rejenerasyonu aşar, tendonun yapısı ve işlevi değişir, ağrı ortaya çıkar. Sık tetikleyici, antrenman miktarının ani artırılmasıdır."},{"h":"Ana semptomlar","t":"Hareketin başında ve ertesi sabah ağrı ve sertlik, tendonda lokal hassasiyet. Hareket sırasında azalabilir, yük sonrası kötüleşebilir."},{"h":"Değerlendirme noktaları","t":"Tendon hassasiyetini, yükle ağrıyı (tek ayak topuk kaldırma, tek bacak çömelme) değerlendirin; antrenman miktarı, ayakkabı ve zemin değişikliğini sorun."},{"h":"Tedavi akışı","t":"Yükün düzenlenmesi → izometrik egzersizler → izotonik (eksantrik dahil) kuvvetlendirme → sıçrama gibi hızlı hareketler → spora dönüş."},{"h":"Dikkat, kontrendikasyon","t":"Tam istirahat tendonun yük kapasitesini azaltabilir. Ağrıyı belirgin kötüleştiren yüklemeden ve ertesi güne kalan şiddetli ağrıdan kaçının."},{"h":"Hekime yönlendirme","t":"Ani yırtılma hissi veya patlama sesi, belirgin güçsüzlük, şiddetli şişlik ve ısı artışı, geçmeyen gece veya istirahat ağrısı."}]},"keypoints":["Antrenman miktarının ani artışı sıklıkla tendinopatiyi tetikler","Tam istirahat yerine yükü ağrıya göre düzenleyin","Yük miktarını yük sonrası ve ertesi günkü ağrıya göre ayarlayın","İzometrik egzersizlerden daha yüksek yüke kademeli ilerleyin","Yırtılma hissi veya ani güçsüzlükte hekime yönlendirin"],"case":{"text":"28 yaşında koşucu erkek. Koşu mesafesini aniden artırdığından beri sabahları Aşil tendonu uzun süre sert ve ağrılı. Koşunun başında ağrıyor, koşarken azalıyor. Tendonun orta kısmında hassasiyet var.","answer":"Aşil tendinopatisi şüphesi. Tam istirahat önermeyin; koşu miktarını düzenleyin ve ağrıya göre topuk kaldırma gibi kademeli yüklemeyle ilerleyin. Yırtılma hissi veya güçsüzlükte hekime yönlendirin."},"questions":[{"level":"Temel","q":"Tendinopatinin tipik tetikleyicisi hangisidir?","options":["Uzun istirahat","Antrenman miktarının ani artışı","Yeterli uyku","Esnekliğin artması"],"answer":1,"exp":"Tendonun rejenerasyonunu aşan yük, özellikle antrenman miktarının ani artışı, tendinopatinin tipik tetikleyicisidir."},{"level":"Temel","q":"Tendinopatide hangi ağrı özelliği sıktır?","options":["Yalnız gece şiddetli ağrı","İstirahatte sürekli kötüleşme","Her zaman aynı şiddet","Hareket başı ağrı, sabah sertliği"],"answer":3,"exp":"Hareketin başında ve ertesi sabah ağrı ve sertlik olur; hareket sırasında çoğu zaman azalır."},{"level":"Orta","q":"Tendinopatinin kademeli yüklemesinde görece geç ne eklenir?","options":["İzometrik egzersiz","Yavaş kuvvetlendirme","Sıçrama gibi hızlı hareketler","Yükün düzenlenmesi"],"answer":2,"exp":"Ağrıyı kontrol ederek izometrik ve izotonik egzersizlerle yük kapasitesi artırılır, sonra sıçrama gibi hızlı hareketlere geçilir."},{"level":"Orta","q":"Tendinopatide yükü yeniden değerlendirmek için uygun ölçüt nedir?","options":["Ertesi günkü ağrı değişimi","Vücut ağırlığı değişimi","Hava sıcaklığı","Antrenmanın günün saati"],"answer":0,"exp":"Yalnız hareket sırasındaki değil, ertesi günkü ağrı ve sertlik değişimini de izleyin ve yükü buna göre ayarlayın."},{"level":"Klinik","q":"22 yaşında voleybolcu kadın. Sıçramalardan sonra patellanın alt ucu ağrıyor, patellar tendon hassas. En olası tanı nedir?","options":["Ön çapraz bağ yaralanması","Patellar tendinopati","Menisküs yaralanması","Patella çıkığı"],"answer":1,"exp":"Tekrarlayan sıçrama ile patella alt ucu ve patellar tendondaki hassasiyet patellar tendinopatiye özgüdür."},{"level":"Klinik","q":"40 yaşında erkek, Aşil tendinopatisi tedavisinde. Tenis oynarken arkadan tekme yemiş gibi hissetti; parmak ucunda duramıyor. Ne yaparsınız?","options":["Eksantrik egzersize devam","Yükü daha da artırmak","Germeyi artırmak","Yırtık şüphesiyle hekime yönlendirmek"],"answer":3,"exp":"Ani darbe hissi ve parmak ucunda duramama Aşil tendonu yırtığını düşündürür. Egzersizleri durdurun ve hekim değerlendirmesine yönlendirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Spor, tendonlar ve kaslar","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"Ayak Bileği Burkulması","lead":"Ayak bileği burkulması en sık spor yaralanmalarından biridir; çoğunlukla plantar fleksiyonla birlikte inversiyonda oluşur. Yeniden burkulmayı önlemede proprioseptif eğitim kilit önemdedir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Plantar fleksiyonla birlikte inversiyonda lateral bağlar yaralanır. En sık ön talofibular bağ (ATFL), ağır olgularda kalkaneofibular bağ (CFL) da yaralanır."},{"h":"Ana semptomlar","t":"Lateral malleol çevresinde ağrı, şişlik ve ekimoz, yük verirken ağrı. Hasta instabilite hissi veya tekrarlayan burkulmalar da tarifleyebilir."},{"h":"Değerlendirme noktaları","t":"Yaralanma mekanizması, hassasiyetin yeri, yük verebilme, ön çekmece testi ve talar tilt testi. Kırığı ve diğer bağ yaralanmalarını gözden kaçırmayın."},{"h":"Faza göre rehabilitasyon","t":"1 koruma, soğuk, kompresyon, elevasyon → 2 mobilite ve kademeli yük verme → 3 kuvvetlendirme ve propriosepsiyon → 4 koşu, sıçrama, spora dönüş."},{"h":"Dikkat, kontrendikasyon","t":"Akut dönemde ağrıyı artıran egzersizlerden kaçının. Proprioseptif ve denge eğitimi atlanırsa burkulma kolayca tekrarlar ve instabilite hissi kalır."},{"h":"Hekime yönlendirme","t":"Kemik hassasiyeti veya yük verememe (kırık şüphesi), belirgin şişlik veya deformite, uyuşma, geçmeyen ağrı veya tekrarlayan instabilite."}]},"keypoints":["Yaralanma mekanizması çoğunlukla plantar fleksiyonla birlikte inversiyondur","En sık ön talofibular bağ (ATFL) yaralanır","Kemik hassasiyeti veya yük verememe varsa kırık düşünün","Proprioseptif eğitim tekrarlama riskini azaltır","Spora dönüş, tek bacak hareketleri kontrol edildikten sonra kademelidir"],"case":{"text":"19 yaşında erkek. Futbolda ayağı içe burkuldu. Ertesi gün lateral malleol önünde şişlik ve hassasiyet var, kemik hassasiyeti yok, yük verebiliyor. Ön çekmece testinde öne kayma sağlam taraftan fazla.","answer":"ATFL yaralanmasıyla seyreden inversiyon burkulması şüphesi. Koruma, soğuk, kompresyon, elevasyon ve ağrıya göre yük vermeyle başlayın; kuvvetlendirme ve proprioseptif eğitimden sonra kademeli spora dönüş sağlayın."},"questions":[{"level":"Temel","q":"Şekilde ayak bileği burkulmasının tipik yaralanma mekanizması hangisidir?","options":["Dorsifleksiyonla birlikte eversiyon","Plantar fleksiyonla birlikte inversiyon","Dorsifleksiyonla birlikte inversiyon","Plantar fleksiyonla birlikte eversiyon"],"answer":1,"exp":"Ayak bileği burkulması çoğunlukla plantar fleksiyonla birlikte inversiyonda oluşur; en sık lateraldeki ön talofibular bağ yaralanır."},{"level":"Temel","q":"Şekilde 3. fazın içeriği nedir?","options":["Koruma, soğuk, kompresyon, elevasyon","Mobilite ve kademeli yük verme","Kuvvetlendirme ve propriosepsiyon","Koşu, spora dönüş"],"answer":2,"exp":"1. faz: koruma, soğuk, kompresyon, elevasyon; 2.: mobilite ve yük verme; 3.: kuvvetlendirme ve propriosepsiyon; 4.: spora dönüş."},{"level":"Orta","q":"Kademeli yük verme hangi fazda başlar?","options":["1. faz","2. faz","3. faz","4. faz"],"answer":1,"exp":"1. fazdaki korumadan sonra 2. fazda mobiliteyi artırmayla birlikte, ağrıya göre yük kademeli artırılır."},{"level":"Orta","q":"Ayak bileği burkulmasının tekrarını önlemede özellikle hangi eğitim önemlidir?","options":["Uzun süreli sabitleme","Tam istirahat","Üst ekstremite kuvvetlendirme","Proprioseptif eğitim"],"answer":3,"exp":"Denge tahtası veya tek ayak duruşuyla proprioseptif eğitim tekrarlama riskini azaltır."},{"level":"Klinik","q":"24 yaşında kadın. Burkulmadan 3 hafta sonra neredeyse ağrısı yok, ama tek ayak duruşta ayak bileği sallanıyor. Hangi tedavi önceliklidir?","options":["Denge ve proprioseptif egzersiz","Soğuk uygulama ve elevasyon","Tam istirahat","Hemen tam hızda sprint"],"answer":0,"exp":"Ağrı azalmış ama instabilite kalmış. Tek ayak duruşla proprioseptif ve kuvvetlendirme egzersizleri önceliklidir, ardından kademeli dönüş."},{"level":"Klinik","q":"20 yaşında erkek. Ayak bileğini defalarca burkmuş, günlük yaşamda da boşalma hissediyor. Ne düşünürsünüz?","options":["Aşil tendonu yırtığı","Plantar fasiit","Kronik ayak bileği instabilitesi","Halluks valgus"],"answer":2,"exp":"Tekrarlayan burkulma ve instabilite hissi kronik ayak bileği instabilitesini düşündürür. Proprioseptif ve kuvvetlendirme eğitimi önemlidir, gerekirse hekim konsültasyonu."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Spor, tendonlar ve kaslar","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"Kas Yaralanmaları","lead":"Kas yaralanması bir spor yaralanmasıdır; iki ana formu kas gerilmesi (kısmi yırtık) ve kas kontüzyonudur. Sık tekrarladığı için kademeli yükleme ve dönüş kriterlerinin belirlenmesi önemlidir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Gerilme özellikle eksantrik kasılmada (kasılan kas uzarken), en sık kas-tendon bileşkesinde oluşur. Kontüzyon doğrudan dış kuvvetle oluşan yaralanmadır, özellikle m. quadriceps femoriste."},{"h":"Ana semptomlar","t":"Yaralanma anında ağrı veya yırtılma hissi, hassasiyet, şişlik, ekimoz, germe ve dirençle ağrı, kuvvet kaybı. Ağır olguda çöküntü palpe edilir."},{"h":"Değerlendirme noktaları","t":"Yaralanma mekanizması, hassas nokta, germe ağrısı (ör. DBK açısında taraf farkı), dirençle ağrı, yürüyüş paterni. Şiddeti görüntülemeyle birlikte hekim belirler."},{"h":"Faza göre rehabilitasyon","t":"Akut fazda koruma ve şişlik kontrolü. Ağrıya göre izometrik → konsentrik → eksantrik çalışma, koşu da kademeli. Dönüşten önce spora özgü hareketleri kontrol edin."},{"h":"Dikkat, kontrendikasyon","t":"Akut fazda güçlü germe ve güçlü masajdan kaçının. Uyluk kontüzyonu sonrası güçlü uyaran miyozitis ossifikans tetikleyebilir. Ağrı varken çalıştırmayın."},{"h":"Hekime yönlendirme","t":"Belirgin çöküntü veya yırtılma hissi, hızla artan şişlik, süren şiddetli ağrı, uyuşma veya cilt rengi değişimi (kompartman sendromu şüphesi)."}]},"keypoints":["Gerilme en sık eksantrik kasılmada, kas-tendon bileşkesinde olur","Akut fazda koruma ve şişlik kontrolü; güçlü germe yok","Yükleme sırası: izometrik → konsentrik → eksantrik","Hamstringlerde eksantrik antrenmanı programa ekleyin","Dönüşe ağrı, esneklik, kas kuvveti ve spora özgü harekete göre karar verin"],"case":{"text":"20 yaşında erkek kısa mesafe koşucusu. Tam hızda sprintte uyluk arkasında ağrı hissetti ve yarışı bıraktı. Ertesi gün m. biceps femoris üzerinde hassasiyet ve ekimoz, DBK'de taraf farkı ve germe ağrısı var.","answer":"Hamstring gerilmesi düşünülür. Akut fazda koruma ve şişlik kontrolü önceliklidir; güçlü germe ve masajdan kaçının. Ağrıya göre izometrik çalışmayla başlayıp yükü kademeli artırın. Çöküntü veya başka ciddi bulguda hekime yönlendirin."},"questions":[{"level":"Temel","q":"Kas gerilmesi en sık nerede oluşur?","options":["Kas karnının ortasında","Kas-tendon bileşkesinde","Periostta","Tendonun kemiğe yapışma yerinde"],"answer":1,"exp":"Gerilme en sık kas ile tendonun bileşkesinde oluşur. Hamstringlerde özellikle m. biceps femoris uzun başını etkiler."},{"level":"Temel","q":"Gerilme en sık hangi kasılma tipinde oluşur?","options":["İzometrik","Konsentrik","Eksantrik","İzokinetik"],"answer":2,"exp":"Kasılan kas uzarken, yani eksantrik kasılmada; tipik an sprintin salınım fazının sonudur."},{"level":"Orta","q":"Gerilme sonrası kuvvetlendirmenin olağan sırası nedir?","options":["Eksantrik → konsentrik → izometrik","İzometrik → konsentrik → eksantrik","Konsentrik → izometrik → eksantrik","Hemen maksimal eksantrik çalışma"],"answer":1,"exp":"Ağrıya göre düşük yüklü izometrik çalışmayla başlanır, ardından konsentrik, en son eksantrik kasılma gelir."},{"level":"Orta","q":"Uyluk kontüzyonu sonrası neden güçlü masaj ve germeden kaçınılır?","options":["Miyozitis ossifikans tetikleyebilir","Kas atrofisi ortadan kalkar","Tendon kısalır","Sinir rejenerasyonu durur"],"answer":0,"exp":"Kontüzyon sonrası erken güçlü uyaran kas içi kanamayı artırabilir ve miyozitis ossifikans gelişimine yol açabilir."},{"level":"Klinik","q":"Futbolcu: şut atarken uyluk önünde ağrı oldu, ertesi gün de hassas ve germeyle ağrıyor. Akut fazda doğru yaklaşım nedir?","options":["Güçlü germe","Koruma ve şişlik kontrolü","Tam sprintle kontrol","Güçlü masaj"],"answer":1,"exp":"Akut fazda koruma ve şişlik kontrolü önceliklidir. Güçlü germe, masaj ve maksimal hareket denemesi yaralanmayı kötüleştirebilir."},{"level":"Klinik","q":"Lise öğrencisi, uyluğuna sert darbe aldı. Şişlik hızla artıyor, şiddetli ağrı ve ayakta uyuşmadan yakınıyor. İlk yapılacak nedir?","options":["Sıcak uygulama","Germe öğretmek","Hemen hekime yönlendirmek","Kuvvetlendirmeye başlamak"],"answer":2,"exp":"Hızla artan şişlik, şiddetli ağrı ve uyuşma kompartman sendromunu düşündürür; acil hekim değerlendirmesi gerekir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Spor, tendonlar ve kaslar","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"Ön Çapraz Bağ ve Menisküs Yaralanması","lead":"ÖÇB yaralanması sporda, yere inerken veya yön değiştirirken sıktır ve çoğu zaman menisküs yaralanmasıyla birliktedir. Prognozu erken değerlendirme ve hareket paternlerinin yeniden öğretilmesi belirler.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"ÖÇB yaralanması çoğunlukla temassız, yere iniş veya yön değişiminde olur; diz valgusu ve bacak rotasyonu rol oynar. Menisküs yük altında rotasyonda yaralanır, sıklıkla ÖÇB ile birlikte."},{"h":"Ana semptomlar","t":"ÖÇB: yaralanma anında patlama sesi, hemartroza bağlı şişlik, dizin boşalması (giving way). Menisküs: eklem aralığında ağrı, takılma hissi, kilitlenme (locking), hareket kısıtlılığı."},{"h":"Değerlendirme noktaları","t":"ÖÇB: Lachman testi, ön çekmece testi, pivot shift testi. Menisküs: eklem aralığı hassasiyeti, McMurray testi. Kesin tanıyı hekim koyar."},{"h":"Tedavi akışı","t":"Akut fazda şişlik kontrolü, ekstansiyon EHA'sı ve quadriceps kasılmasının sağlanması. Konservatif tedavi veya rekonstrüksiyona hekim karar verir. Ameliyattan önce de kuvvet ve EHA'yı geliştirin."},{"h":"Dikkat, kontrendikasyon","t":"Tekrarlayan diz boşalması menisküs ve kıkırdağa ek hasar verebilir. Kilitli dizde EHA egzersizlerini zorlamayın. Hareket sırasında dizin içe çökmesine dikkat edin."},{"h":"Hekime yönlendirme","t":"Kilitlenme nedeniyle düzelemeyen diz, yaralanmadan hemen sonra hızla gelişen eklem şişliği, tekrarlayan boşalma, süren şiddetli ağrı, kırığı düşündüren bulgular."}]},"keypoints":["ÖÇB yaralanması çoğunlukla temassızdır; riskli an dizin içe çökmesidir","ÖÇB değerlendirmesinin temeli Lachman testidir","Menisküs yaralanması: eklem aralığı hassasiyeti ve takılma hissi","Diz kilitlenme nedeniyle düzelemiyorsa hekime yönlendirin","Önleme için yere iniş ve yön değiştirme tekniğini öğretin"],"case":{"text":"17 yaşında kız basketbolcu. Sıçrayıp yere inerken dizi içe çöktü, patlama sesi duydu ve düştü. Birkaç saatte dizi şişti; Lachman testinde artmış öne kayma ve son his yokluğu var.","answer":"ÖÇB yaralanması şüphesi. Akut fazda şişlik kontrolü, ekstansiyon EHA'sı ve quadriceps kasılmasının sağlanması önceliklidir. Eşlik eden menisküs yaralanması için kilitlenmeyi sorun. Konservatif tedavi veya rekonstrüksiyona hekim karar verir; kendi kararıyla spora dönmesin."},"questions":[{"level":"Temel","q":"Temassız ÖÇB yaralanmasının tipik pozisyonu hangisidir?","options":["Diz varusu (diz dışa açılır)","Diz valgusu (diz içe çöker)","Dizin hiperfleksiyonu","Patellaya doğrudan darbe"],"answer":1,"exp":"Temassız ÖÇB yaralanması tipik olarak yere iniş veya yön değişiminde, diz içe çöktüğünde (valgus) oluşur."},{"level":"Temel","q":"Menisküs yaralanmasına özgü semptom hangisidir?","options":["Kilitlenme (locking)","Düşük ayak","Patellar refleks kaybı","Uyluk önünde duyu azalması"],"answer":0,"exp":"Yaralı menisküs parçası eklem içine sıkışırsa diz belli bir açıda takılır: buna kilitlenme denir."},{"level":"Orta","q":"ÖÇB yaralanmasına en duyarlı manuel test hangisidir?","options":["McMurray testi","Arka çekmece testi","Lachman testi","Valgus stres testi"],"answer":2,"exp":"Lachman testi diz hafif fleksiyondayken tibiayı öne çeker, kaymayı ve son hissi değerlendirir. ÖÇB değerlendirmesinin temelidir."},{"level":"Orta","q":"Pozitif McMurray testinin bulgusu nedir?","options":["Artmış öne tibial kayma","Rotasyonla ekstansiyonda klik ve ağrı","Patellar instabilite hissi","Medial eklem aralığının açılması"],"answer":1,"exp":"Fleksiyondaki dizde bacak rotasyona getirilerek düzeltilir; eklem aralığında klik veya ağrı olursa menisküs yaralanmasından şüphelenilir."},{"level":"Klinik","q":"Futbolcu: yön değiştirirken dizini burktu, o zamandan beri takılıyor ve tam düzeltemiyor. En olası tanı nedir?","options":["Patellar tendinopati","İliotibial bant sendromu","Menisküs yaralanmasına bağlı kilitlenme","Osgood-Schlatter hastalığı"],"answer":2,"exp":"Rotasyonel yaralanma sonrası düzeltememe kilitlenmeyi düşündürür. EHA egzersizlerini zorlamayın, hekim değerlendirmesine yönlendirin."},{"level":"Klinik","q":"ÖÇB yaralanmasından sonraki 2. gün, diz şiş. Konservatif tedavinin başında öncelik nedir?","options":["Sıçrama çalışması","Şişlik kontrolü ve ekstansiyonun sağlanması","Maksimal yön değiştirme çalışması","Yük altında derin çömelme"],"answer":1,"exp":"Başlangıçta şişlik tedavi edilir, ekstansiyon EHA'sı ve quadriceps kasılması sağlanır. Yüksek yük boşalmaya ve ikincil yaralanmaya yol açabilir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Spor, tendonlar ve kaslar","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"Ön Çapraz Bağ Rekonstrüksiyonu Sonrası","lead":"ÖÇB rekonstrüksiyonu sonrası rehabilitasyon, grefti korurken EHA'yı, kas kuvvetini ve hareket paternlerini kademeli olarak geri kazandırır. İlk hedef: ekstansiyon kısıtlılığı kalmamalı.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo ve cerrahi","t":"Bağ, hastanın kendi tendonuyla (ör. hamstring tendonu veya kemik-patellar tendon-kemik grefti) rekonstrükte edilir. Greft ameliyattan sonra yeniden yapılanır ve sağlamlığını zamanla kazanır."},{"h":"Postoperatif sorunlar","t":"Erken dönemde şişlik, ağrı, ekstansiyon kısıtlılığı ve zayıf quadriceps aktivasyonu sıktır. Greft alınan bölgedeki ağrı ve güçsüzlüğe de dikkat edin."},{"h":"Değerlendirme noktaları","t":"Şişlik, diz ekstansiyon ve fleksiyonunda taraf farkı, quadricepsin istemli kasılması (extension lag), yürüyüş paterni, kas kuvveti, fonksiyonel testler (ör. hop testleri)."},{"h":"Faza göre rehabilitasyon","t":"0–2. hafta: tam ekstansiyon, quadriceps. 2–6. hafta: normal yürüyüş, fleksiyon artışı. 6–12. hafta: kuvvet, propriosepsiyon. 3–6. ay: kademeli koşu, sıçrama. 6. aydan: dönüş testleri."},{"h":"Dikkat, kontrendikasyon","t":"Ekstansiyon kısıtlılığı kalmamalı. Grefti zorlayan egzersizlerin başlangıcını cerrahi teknik ve hekim talimatı belirler. Şişlik artarsa yükü azaltın; yalnız zamana göre ilerlemeyin."},{"h":"Hekime yönlendirme","t":"Ateş, yarada kızarıklık, ısı artışı, pürülan akıntı, aniden artan şişlik, baldırda ağrı ve şişlik (derin ven trombozu şüphesi), diz boşalması."}]},"keypoints":["Bir numaralı hedef tam ekstansiyona ulaşmaktır","Quadricepsi erken dönemden itibaren istemli olarak aktive edin","Yalnız zamana göre değil, şişlik, EHA ve kas kuvvetine göre ilerleyin","Spora dönüşe fonksiyonel testler ve hekim karar verir","Yeniden yaralanmayı önlemek için yere iniş ve yön değiştirmeyi öğretin"],"case":{"text":"22 yaşında erkek, ÖÇB rekonstrüksiyonundan 2 hafta sonra. Diz hafif şiş, ekstansiyon −10°. Quadriceps kasılması zayıf, extension lag görülüyor. Bir an önce koşmak istediğini söylüyor.","answer":"Bu dönemde tam ekstansiyon ve quadriceps kontrolünün sağlanması önceliklidir; koşu için henüz erken. Kalıcı ekstansiyon kısıtlılığı patolojik yürüyüşe ve ön diz ağrısına yol açar. Şişliği tedavi edin ve ancak kriterler karşılanınca ilerleyin."},"questions":[{"level":"Temel","q":"ÖÇB rekonstrüksiyonu sonrası rehabilitasyonun öncelikli hedefi nedir?","options":["Erken sıçrama çalışması","Önce derin fleksiyona ulaşmak","Tam ekstansiyonu geri kazanmak","Ameliyattan hemen sonra koşu"],"answer":2,"exp":"Kalıcı ekstansiyon kısıtlılığı patolojik yürüyüşe ve ön diz ağrısına yol açar; bu yüzden tam ekstansiyonu geri kazanmak önceliklidir."},{"level":"Temel","q":"Spora dönüş testleri hangi fazda yapılır?","options":["2. faz (2–6. hafta)","3. faz (6–12. hafta)","4. faz (3–6. ay)","5. faz (6. aydan itibaren)"],"answer":3,"exp":"Dönüş testleri son faz olan 5. fazda (6. aydan itibaren), kuvvet ve fonksiyonel test sonuçlarına göre yapılır."},{"level":"Orta","q":"Erken postoperatif dönemde değerlendirilen extension lag ne anlama gelir?","options":["Dizin anterior instabilitesi","Aktif ekstansiyon pasiften geride kalır","Pasif fleksiyon kısıtlılığı","Patellanın lateral konumu"],"answer":1,"exp":"Diz pasif olarak tam düzelir ama aktif olarak düzelmez: bu, quadriceps aktivasyonunun azaldığını gösterir."},{"level":"Orta","q":"Rehabilitasyonun bir sonraki aşamasına neye göre geçmek doğrudur?","options":["Şişlik, EHA ve kuvvet kriterlerine göre","Yalnız ameliyattan bu yana geçen haftaya göre","Artan ağrıya rağmen plana göre","Öncelikle hastanın isteğine göre"],"answer":0,"exp":"Zaman yalnızca yol göstericidir. Şişlik, EHA, kas kuvveti ve hareket kalitesi kriterleri karşılandığında ilerlenir."},{"level":"Klinik","q":"Rekonstrüksiyondan 1 hafta sonra aniden baldırda ağrı, şişlik ve ısı artışı oluyor. Doğru yaklaşım nedir?","options":["Masajla şişliği dağıtmak","Yükü artırmak","Hemen hekime bildirmek","Sıcak uygulama"],"answer":2,"exp":"Derin ven trombozunu düşündüren bulgu. Masajdan kaçınılmalı, hemen hekime bildirilmelidir."},{"level":"Klinik","q":"Ameliyattan 4 ay sonra kuvvette belirgin taraf farkı var ve yere inerken diz içe çöküyor. Şimdi doğru yaklaşım nedir?","options":["Hemen maçlara dönmek","Kuvvetlendirme ve iniş düzeltmeye devam","Rehabilitasyonu sonlandırmak","Yalnız ortezle dönmek"],"answer":1,"exp":"Kuvvette taraf farkı ve dizin içe çökmesi yeniden yaralanma risk faktörleridir. Kuvvetlendirme ve hareket düzeltmeye devam edin; dönüş ancak kriterlerden sonra düşünülür."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Spor, tendonlar ve kaslar","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"Osteoartrit","lead":"Osteoartrit, eklem kıkırdağının dejenerasyonuyla seyreden ve ağrı ile işlev kaybının yavaşça ilerlediği bir hastalıktır. Özellikle diz ve kalçayı tutar; konservatif tedavinin temeli egzersiz ve hasta eğitimidir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Temelinde eklem kıkırdağının dejenerasyonu ve aşınması vardır; osteofit oluşumu, subkondral skleroz ve sinovit eşlik eder. Diz OA'sı çoğunlukla mediyaldir, kalça OA'sı sıklıkla displazi zemininde gelişir."},{"h":"Ana semptomlar","t":"Başlangıç ağrısı, ayağa kalkarken ve merdivende ağrı, sertlik, eklem efüzyonu, hareket kısıtlılığı. İlerledikçe deformite (ör. O bacak) ve yürüme bozukluğu belirginleşir."},{"h":"Değerlendirme noktaları","t":"Ağrının yeri ve tetikleyicisi, EHA (ör. diz ekstansiyonu, kalça iç rotasyonu kısıtlılığı), kas kuvveti, yürüyüş (lateral thrust, Trendelenburg belirtisi), ADL."},{"h":"Tedavi akışı","t":"Hasta eğitimi, egzersiz (quadriceps ve kalça abdüktörlerini güçlendirme, EHA'yı koruma), aerobik egzersiz, kilo kontrolü, baston, tabanlık. Konservatif tedavi yetmezse cerrahi düşünülür."},{"h":"Dikkat, kontrendikasyon","t":"Belirgin enflamasyon veya efüzyon döneminde yükü azaltın. Ertesi güne kalan ağrı yapan yük fazladır. Baston kural olarak etkilenen tarafın karşı elinde tutulur."},{"h":"Hekime yönlendirme","t":"Ani şiddetli şişlik ve ısı artışı (enfeksiyon veya psödogut şüphesi), ateş, artan gece ağrısı, ani yürüyememe, düşme sonrası şiddetli ağrı."}]},"keypoints":["Diz OA'sı çoğunlukla mediyaldir, sıklıkla O bacak deformitesiyle","Kalça OA'sının altında sıklıkla asetabular displazi vardır","Konservatif tedavinin temeli egzersiz ve hasta eğitimidir","Baston etkilenen tarafın karşı elinde tutulmalıdır","Ertesi güne kadar ağrı bırakan yükü yeniden gözden geçirin"],"case":{"text":"70 yaşında kadın. Yıllardır sağ dizi ağrıyor, özellikle ayağa kalkarken, hareketin başında ve merdivende. O bacak deformitesi, ekstansiyon kısıtlılığı ve yürürken dizin dışa kayması (lateral thrust) görülüyor.","answer":"Mediyal diz osteoartriti düşünülür. Hasta eğitimi, quadriceps ve kalça çevresi kaslarını güçlendirme, EHA'yı koruma, kilo kontrolü; gerekirse sol elde baston. Ani ısı artışı veya şişlikte hekime yönlendirin."},"questions":[{"level":"Temel","q":"Diz osteoartritinin en sık tipi hangisidir?","options":["Lateral (X bacak)","Mediyal (O bacak)","Yalnız patellofemoral","Tibiofibular"],"answer":1,"exp":"Diz OA'sı en sık mediyal kompartmanı tutar ve sıklıkla O bacak (varus) deformitesiyle seyreder."},{"level":"Temel","q":"Osteoartritin tipik görüntüleme bulgusu hangisidir?","options":["Eklem aralığının genişlemesi","Büyüme kıkırdağının genişlemesi","Periosteal reaksiyon","Osteofit oluşumu"],"answer":3,"exp":"OA'nın tipik bulguları eklem aralığında daralma, osteofitler ve subkondral sklerozdur."},{"level":"Orta","q":"Sağ diz OA'lı hastaya baston kullanımını öğretiyorsunuz. Baston hangi elde tutulmalı?","options":["Sağ elde","Sol elde","İki elde","Fark etmez"],"answer":1,"exp":"Baston kural olarak etkilenen tarafın karşı elinde tutulur ve etkilenen bacakla birlikte öne alınır; böylece etkilenen tarafın yükü azalır."},{"level":"Orta","q":"Kalça OA'sında m. gluteus medius zayıfsa hangi belirti tipiktir?","options":["Drop arm belirtisi","Lasègue belirtisi","Trendelenburg belirtisi","Homans belirtisi"],"answer":2,"exp":"M. gluteus medius zayıfsa etkilenen taraf üzerinde tek ayak duruşta karşı taraf pelvis düşer: bu Trendelenburg belirtisidir."},{"level":"Klinik","q":"65 yaşında erkek, diz OA'sı. Egzersiz tedavisinden sonra ertesi güne kadar şiddetli ağrı ve şişlik kaldı. Doğru yaklaşım nedir?","options":["Yükü daha da artırmak","Tüm egzersizleri durdurmak","Yükü azaltıp yeniden dozlamak","Yalnız istirahat önermek"],"answer":2,"exp":"Ertesi güne kalan ağrı ve şişlik aşırı yüklenmeyi gösterir. Bırakmayın; miktar ve şiddeti değiştirerek devam edin."},{"level":"Klinik","q":"Diz OA'lı hastanın dizi aniden çok şişti, ısındı ve ateşi de var. İlk yapılacak nedir?","options":["Hekime bildirmek","Egzersizi artırmak","Sıcak uygulama","Germe öğretmek"],"answer":0,"exp":"Ani şişlik, ısı artışı ve ateş enfeksiyon veya psödogutu düşündürebilir. Sıcak uygulama ve egzersizden kaçının, hekime bildirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Ortopedi ve travmatoloji","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"Kalça ve Diz Protezi","lead":"Eklem protezi, hasarlı eklem yüzeylerini yapay materyalle değiştirerek ağrıyı azaltır ve işlevi iyileştirir. İyileşmenin anahtarı cerrahi yaklaşıma uygun hareket eğitimi ve erken mobilizasyondur.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo ve cerrahi","t":"Osteoartrit veya başka nedenle hasarlanan eklem yüzeylerinin ağrıyı azaltmak ve işlevi iyileştirmek için protezle değiştirilmesi. Kalça protezinde (TKP) çıkık riskli pozisyon cerrahi yaklaşıma bağlıdır."},{"h":"Postoperatif sorunlar","t":"Ağrı, şişlik, hareket kısıtlılığı, kas güçsüzlüğü, bozulan yürüyüş. Kalça protezinde çıkığı önleme, diz protezinde (TDP) fleksiyon ve ekstansiyon EHA'sına ulaşma ana hedeftir."},{"h":"Değerlendirme noktaları","t":"Yara ve şişlik, EHA, kas kuvveti (quadriceps, m. gluteus medius), bacak boyu farkı hissi, yürüyüş paterni, denge, ADL. Yük sınırını ve yasak pozisyonları hekimle netleştirin."},{"h":"Tedavi akışı","t":"Erken dönemde ayak bileği egzersizleri, izometrik egzersizler, mobilizasyon ve yürüme eğitimi. EHA ve kuvvetlendirme egzersizleri, yürüme yardımcısının kademeli değişimi, ADL ve ev yaşamı eğitimi."},{"h":"Dikkat, kontrendikasyon","t":"Posterior yaklaşımlı kalça protezinde fleksiyon-addüksiyon-iç rotasyon, anterior yaklaşımda ekstansiyon-addüksiyon-dış rotasyon kombinasyonundan kaçının. Diz protezinde peroneal sinir felcine dikkat edin."},{"h":"Hekime yönlendirme","t":"Çıkığı düşündüren ani ağrı, bacakta kısalma ve rotasyon, baldırda şişlik ve ağrı, ani nefes darlığı veya göğüs ağrısı, yarada kızarıklık, akıntı, ateş."}]},"keypoints":["Kalça protezinde çıkık riskli pozisyon cerrahi yaklaşıma bağlıdır","Posterior yaklaşımda fleksiyon-addüksiyon-iç rotasyon kombinasyonundan kaçının","Ayak bileği dorsi ve plantar fleksiyonu trombozu önlemeye yardımcı olur","Diz protezinde fleksiyon ve ekstansiyon EHA'sına erken ulaşmak önemlidir","Yük vermeyi ve yasak pozisyonları daima hekimle netleştirin"],"case":{"text":"75 yaşında kadın, kalça osteoartriti nedeniyle posterior yaklaşımla kalça protezi, postoperatif 3. gün. Yürüteçle çalışıyor ve yerden bir şey almak istiyor: gövdesini döndürerek derin eğilmek üzere.","answer":"Derin fleksiyon-addüksiyon-iç rotasyon kombinasyonu posterior yaklaşımlı kalça protezinde çıkık açısından risklidir; hemen durdurun. Yardımcı araçla (ör. uzun saplı tutucu) güvenli hareketleri öğretin. Ani ağrı, bacakta kısalma veya rotasyonda hekime yönlendirin."},"questions":[{"level":"Temel","q":"Posterior yaklaşımlı kalça protezinden sonra hangi pozisyon çıkık açısından risklidir?","options":["Ekstansiyon, addüksiyon, dış rotasyon","Fleksiyon, addüksiyon, iç rotasyon","Fleksiyon, abdüksiyon, dış rotasyon","Ekstansiyon, abdüksiyon, iç rotasyon"],"answer":1,"exp":"Posterior yaklaşımlı kalça protezinden sonra kalçanın fleksiyon-addüksiyon-iç rotasyon kombinasyonunda çıkık riski artar."},{"level":"Temel","q":"Diz protezinin temel amacı nedir?","options":["Kemik büyümesini uyarmak","Bağı rekonstrükte etmek","Siniri onarmak","Ağrıyı azaltmak ve işlevi iyileştirmek"],"answer":3,"exp":"Diz protezi hasarlı eklem yüzeylerini protezle değiştirir; amacı ağrıyı azaltmak, yürüme ve diğer işlevleri iyileştirmektir."},{"level":"Orta","q":"Derin ven trombozunu önlemek için erken dönemde hangi egzersizi öğretirsiniz?","options":["Boyun rotasyonu","Parmak fleksiyon-ekstansiyonu","Ayak bileği dorsi ve plantar fleksiyonu","Derin çömelme"],"answer":2,"exp":"Ayak bileği dorsi ve plantar fleksiyonu baldır kas pompası aracılığıyla venöz dönüşü destekler ve trombozu önlemeye yardımcı olur."},{"level":"Orta","q":"Diz protezinden sonra hangi sinir felcine dikkat edilmelidir?","options":["Peroneal sinir felci","Median sinir felci","Fasiyal sinir felci","Radial sinir felci"],"answer":0,"exp":"Diz protezinden sonra fibula başı çevresindeki basıya bağlı peroneal sinir felci gelişebilir; düşük ayak ve uyuşmaya dikkat edin."},{"level":"Klinik","q":"Posterior yaklaşımlı kalça protezi sonrası 5. gün: hasta alçak sandalyede oturuyor ve bacak bacak üstüne atmak istiyor. Doğru yaklaşım nedir?","options":["Yalnızca gözlemlemek","Yüksek sandalye, bacak çaprazlamaktan kaçınma","Bacak çaprazlamayı çalıştırmak","Derin eğilmeyi çalıştırmak"],"answer":1,"exp":"Alçak sandalyede derin fleksiyon ve bacak çaprazlama (addüksiyon, iç rotasyon) çıkık açısından risklidir. Yüksek oturma yeri kullanmalı ve bacak çaprazlamamalıdır."},{"level":"Klinik","q":"Diz protezi sonrası 2. gün: yürüme eğitimi sırasında ani nefes darlığı ve göğüs ağrısı oluyor. İlk yapılacak nedir?","options":["Yürüme eğitimine devam","Solunum egzersizi öğretmek","Hemen durdurup hekime bildirmek","Dinlendirip izlemek"],"answer":2,"exp":"Pulmoner emboliyi düşündüren bulgu. Egzersiz hemen durdurulmalı ve hekime bildirilmelidir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Ortopedi ve travmatoloji","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"Sık Görülen Kırıklar","lead":"Yaşlılarda osteoporoz zemininde düşmeye bağlı kırıklar sıktır. Kemik iyileşme evresine ve hekimin izin verdiği sınırlara uyarak hareketsizliği önleyin ve işlevi geri kazandırın.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Yaşlılarda osteoporoz zemininde, düşme sonrası proksimal femur, distal radius, proksimal humerus ve vertebra gövdesi kırıkları sıktır. Gençlerde yüksek enerjili travma tipiktir."},{"h":"Ana semptomlar","t":"Ağrı, şişlik, deformite, ekimoz, işlev kaybı. Proksimal femur kırığında hasta ayağa kalkamaz, bacak kısalmış ve dış rotasyondadır; kompresyon kırığında hareketle sırt ağrısı olur."},{"h":"Değerlendirme noktaları","t":"Kırık tipini, tespiti, yük ve EHA sınırını hekimle netleştirin. Ağrı, şişlik, komşu eklem EHA'sı, kuvvet, sinir ve dolaşım durumu, yaralanma öncesi ADL ve biliş."},{"h":"Tedavi akışı","t":"Sabitleme sırasında şişlik ve kontraktüre karşı serbest eklemleri hareket ettirin. Kemik iyileşmesi ve izne göre EHA, yük verme ve kuvvetlendirme. Yaşlılarda erken mobilizasyon, düşme önleme."},{"h":"Dikkat, kontrendikasyon","t":"İzin verilen yükü ve EHA'yı aşmayın. Uzun yatak istirahatinde hareketsizliğe, pnömoniye, bası yarasına ve deliryuma dikkat edin. Distal radius kırığı sonrası parmak sertliğine dikkat edin."},{"h":"Hekime yönlendirme","t":"Sabitleme sırasında şiddetli ağrı, uyuşma, parmaklarda renk değişimi (dolaşım bozukluğu veya kompartman sendromu şüphesi), aniden artan ağrı veya deformite, baldırda şişlik, ateş."}]},"keypoints":["Yaşlılarda osteoporoz zemininde, düşme sonrası kırık sıktır","Yük ve EHA için izin verilen sınırı daima hekimle netleştirin","Sabitleme sırasında da sabitlenmemiş eklemleri aktif hareket ettirin","Proksimal femur kırığı sonrası erken mobilizasyonla hareketsizliği önleyin","Yeni kırığa karşı: düşme önleme ve osteoporoz tedavisi"],"case":{"text":"82 yaşında kadın evde düştü, sağ kalçası ağrıyor, ayağa kalkamıyor. Sağ bacak kısalmış ve dış rotasyonda. Pertrokanterik femur kırığı nedeniyle osteosentez yapıldı, ameliyat sonrası gün rehabilitasyon istendi.","answer":"İzin verilen yükü hekimle netleştirin, erken mobilizasyon ve yürüme eğitimine başlayın; hareketsizlik, pnömoni ve deliryumu önleyin. Hedef yaralanma öncesi ADL'dir; taburculuk öncesi düşme önleme ve osteoporoz tedavisini anlatın."},"questions":[{"level":"Temel","q":"Yaşlı biri uzanmış eli üzerine düşerse hangi kırık sıktır?","options":["Skafoid kırığı","Distal radius kırığı","Olekranon kırığı","Metakarp kırığı"],"answer":1,"exp":"Yaşlılarda uzanmış el üstüne düşme sonrası distal radius kırığı tipiktir. Distal parça dorsale yer değiştirirse Colles kırığı denir."},{"level":"Temel","q":"Proksimal femur kırığında bacak hangi pozisyondadır?","options":["Uzamış ve iç rotasyonda","Değişiklik yok","Kısalmış ve dış rotasyonda","Uzamış ve abdüksiyonda"],"answer":2,"exp":"Proksimal femur kırığında bacak tipik olarak kısalmış ve dış rotasyondadır; ayakta durma ve yürüme zorlaşır."},{"level":"Orta","q":"Kırığın sabitleme döneminde doğru fizyoterapi hangisidir?","options":["Sabitlenmiş bölgede güçlü pasif EHA","İzinden önce tam yük","Kırık bölgesine güçlü masaj","Sabitlenmemiş eklemleri hareket ettirmek"],"answer":3,"exp":"Sabitleme sırasında kırık korunur; sabitlenmemiş eklemler hareket ettirilerek şişlik, kontraktür ve kas zayıflığı önlenir."},{"level":"Orta","q":"Yaşlılarda proksimal femur kırığı ameliyatı sonrası erken mobilizasyonun temel amacı nedir?","options":["Kırık tipini belirlemek","İmmobilizasyon sendromunu önlemek","Ameliyatın yerine geçmek","Kemik iyileşmesini gereksiz kılmak"],"answer":1,"exp":"Yaşlılarda uzun yatışta kas zayıflığı, pnömoni, bası yarası ve deliryum hızla gelişir; bu yüzden erken mobilize edilir."},{"level":"Klinik","q":"70 yaşında kadın, distal radius kırığı nedeniyle alçıda. Parmakları belirgin şiş, uyuşuyor ve rengi değişmiş. Doğru yaklaşım nedir?","options":["Parmak egzersizini artırmak","Sıcak uygulama","Hemen hekime bildirmek","Bir sonraki seansı beklemek"],"answer":2,"exp":"Sabitleme sırasında belirgin şişlik, uyuşma ve renk değişimi dolaşım bozukluğu veya kompartman sendromunu düşündürür. Hemen hekime bildirin."},{"level":"Klinik","q":"85 yaşında kadın, lomber vertebra kompresyon kırığı, sırt ağrısı; hekim mobilizasyona izin verdi. Doğru yaklaşım nedir?","options":["İzin verilen sınırda mobilizasyon","Yatakta kalıp izlemek","Güçlü gövde fleksiyon egzersizleri","Ağır eşya kaldırma çalışması"],"answer":0,"exp":"Hareketsizliğe karşı izin verilen sınırda mobilize edilir. Kompresyon kırığında güçlü gövde fleksiyonu ve ağır yük kaldırma zorlayıcıdır, kaçınılmalıdır."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Ortopedi ve travmatoloji","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"Bel Ağrısı ve Disk Hernisi","lead":"Bel ağrısının çoğu nonspesifiktir ve nedeni belirlenemez; ancak radiküler semptomları ve ciddi hastalıkları ayırmak önemlidir. Kırmızı bayraklar dışlandıktan sonra aktif kalmayı destekleriz.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Bel ağrısının çoğu nonspesifiktir. Disk hernisinde nucleus pulposus anulus fibrozusu yırtarak dışarı taşar ve sinir köküne bası yapar. En sık L4/5 ve L5/S1 seviyesinde görülür."},{"h":"Ana semptomlar","t":"Bel ağrısı ve tek taraflı, bacağa yayılan ağrı (siyatalji), uyuşma, öne eğilme ve oturmayla artan yakınma. Etkilenen köke uyan duyu, kuvvet ve refleks azalması."},{"h":"Değerlendirme noktaları","t":"DBK testi (üst lomber köklerde femoral sinir germe testi), dermatomlar, kas kuvveti (L5: başparmak dorsifleksiyonu, S1: ayak bileği plantar fleksiyonu), refleksler (S1: Aşil refleksi)."},{"h":"Tedavi akışı","t":"Hasta eğitimiyle korkuyu azaltın, olanaklı sınırda aktif kalmayı sürdürün. Semptomu azaltan pozisyon ve egzersizi bulun; gövde ve alt ekstremite egzersizleri, kademeli artan aktivite."},{"h":"Dikkat, kontrendikasyon","t":"Uzun yatak istirahati önermeyin. Semptomları ayak parmaklarına doğru yayan egzersizi durdurun. Korku-kaçınma ve diğer psikososyal etmenler kronikleşmede rol oynar."},{"h":"Hekime yönlendirme","t":"Mesane-barsak bozukluğu, eyer anestezisi (kauda ekuina sendromu), ilerleyen güçsüzlük, ateş, açıklanamayan kilo kaybı, kanser öyküsü, travma sonrası şiddetli ağrı."}]},"keypoints":["Bel ağrısının çoğu nonspesifiktir","L4/5 hernisinde tipik olarak L5 kökü etkilenir","DBK testi alt lomber radiküler semptomları değerlendirir","Uzun istirahat yerine olanaklı sınırda aktif kalmayı sürdürün","Mesane-barsak bozukluğu, eyer anestezisi: acilen hekime"],"case":{"text":"35 yaşında erkek, ofiste çalışıyor. Ağır bir şey kaldırdığından beri bel ağrısı ve sol bacak dış yüzünden ayak sırtına uzanan uyuşma var. Sol DBK bacağa yayılan ağrıyı başlatıyor, sol başparmak dorsifleksiyonu zayıf. İdrar bozukluğu yok.","answer":"L4/5 disk hernisine bağlı L5 kök lezyonundan şüphelenilir. Eğitim, olanaklı sınırda aktif kalma, semptomları kötüleştirmeyen egzersizler; kas güçsüzlüğünün seyrini düzenli olarak yeniden değerlendirin. İlerleyen felç veya mesane-barsak bozukluğunda hemen hekime."},"questions":[{"level":"Temel","q":"Lomber disk hernisi en sık hangi seviyede görülür?","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"Lomber disk hernisi en sık L4/5, ardından L5/S1 seviyesinde görülür."},{"level":"Temel","q":"Disk hernisinde başlıca hangi doku dışarı taşar?","options":["Nucleus pulposus","Ligamentum flavum","Vertebra arkı","Spinöz çıkıntı"],"answer":0,"exp":"Diskin merkezi olan nucleus pulposus, anulus fibrozustaki yırtıktan dışarı taşar ve sinir köküne bası yapar."},{"level":"Orta","q":"L5 kök lezyonunda tipik olarak hangi hareketin kuvveti azalır?","options":["Ayak bileği plantar fleksiyonu","Başparmak dorsifleksiyonu","Diz ekstansiyonu","Kalça fleksiyonu"],"answer":1,"exp":"L5 kökü m. extensor hallucis longus'u innerve eder; lezyonunda başparmak dorsifleksiyonu zayıflar. Ayak bileği plantar fleksiyonu S1'dir."},{"level":"Orta","q":"S1 kök lezyonunda tipik olarak hangi refleks azalır?","options":["Patellar refleks","Biseps refleksi","Aşil refleksi","Brakiyoradiyal refleks"],"answer":2,"exp":"Aşil refleksinde başlıca S1 rol oynar. Patellar refleks öncelikle L4'ü değerlendirmeye yarar."},{"level":"Klinik","q":"40 yaşında kadın, akut bel ağrısı, kırmızı bayrak yok. Doğru öneri hangisidir?","options":["2 hafta katı yatak istirahati","Ağrı geçene kadar iş izni","Tüm hareketlerin yasaklanması","Olanaklı sınırda aktif kalmak"],"answer":3,"exp":"Kırmızı bayrak olmayan akut bel ağrısında uzun istirahat yerine olanaklı sınırda günlük aktivitenin sürdürülmesi önerilir."},{"level":"Klinik","q":"Bel ağrılı hasta, iki bacağı da uyuşuyor; idrarının zor başladığından ve anüs çevresinde duyu azlığından yakınıyor. Ne yaparsınız?","options":["Egzersiz tedavisine devam","Traksiyon tedavisi","Hemen hekime bildirmek","Bir sonraki seansı beklemek"],"answer":2,"exp":"Mesane-barsak bozukluğu ve eyer anestezisi kauda ekuina sendromunu düşündüren acil işaretlerdir. Hemen hekime bildirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omurga","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"Boyun Ağrısı","lead":"Boyun ağrısının çoğu nonspesifiktir; ancak radikülopati ve miyelopatiyi ayırmak önemlidir. Tehlike işaretleri kontrol edildikten sonra egzersiz tedavisi uygulanır ve postür düzeltilir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"En sık nonspesifik boyun ağrısıdır. Disk veya osteofit sinir köküne bası yaparsa radikülopati, omuriliğe bası yaparsa miyelopati gelişir. Travma sonrası kamçı yaralanması (whiplash) da görülür."},{"h":"Ana semptomlar","t":"Boyun ağrısı, hareket kısıtlılığı, skapula çevresinde ağrı. Radikülopatide tek taraflı kol ağrısı, uyuşma. Miyelopatide iki elde uyuşma, bozulan ince motor beceri (düğme, çatal), yürüme bozukluğu."},{"h":"Değerlendirme noktaları","t":"Servikal EHA, Spurling testi, dermatomlar, kas kuvveti, refleksler (C6: brakiyoradiyal, C7: triseps), Hoffmann refleksi, yürüyüş, postür."},{"h":"Tedavi akışı","t":"Eğitim ve aktif kalma, boyun ve omuz kuşağı egzersizleri (ör. derin boyun fleksör egzersizleri), postür ve çalışma ortamı düzenlemesi. Değerlendirmeye göre dikkatli manuel terapi."},{"h":"Dikkat, kontrendikasyon","t":"Miyelopati şüphesinde güçlü servikal manuel tekniklerden kaçının. Baş dönmesi, çift görme veya konuşma bozukluğu yapan teknik ya da egzersizi hemen durdurun."},{"h":"Hekime yönlendirme","t":"İki elde uyuşma, bozulan ince motor beceri ve yürüme bozukluğu, ilerleyen felç, travma sonrası ağrı, ateş, baş dönmesi, konuşma veya yutma bozukluğu, açıklanamayan kilo kaybı."}]},"keypoints":["Boyun ağrısının çoğu nonspesifiktir","Spurling testi radikülopatiyi değerlendirmeye yarar","İki elde bozulan beceri ve yürüme bozukluğu: miyelopati şüphesi","Derin boyun fleksör ve omuz kuşağı egzersizleri yaptırın","Miyelopati şüphesinde güçlü servikal manuel tekniklerden kaçının"],"case":{"text":"45 yaşında kadın, ofis çalışanı. Bir aydır boyun ağrısı ve sağ başparmakta uyuşma var. Boyun sağa ekstansiyon ve lateral fleksiyona getirilince sağ kola yayılan ağrı oluyor. Sağ brakiyoradiyal refleks azalmış.","answer":"Sağ C6 radikülopatisi düşünülür. Semptomları kötüleştirmeyen sınırda eğitim, egzersiz tedavisi, postür ve çalışma ortamı düzenlemesi. İlerleyen güçsüzlük veya miyelopati bulgularında (iki elde uyuşma, yürüme bozukluğu) hekime yönlendirin."},"questions":[{"level":"Temel","q":"Hangi semptom servikal spondilotik miyelopatiyi düşündürür?","options":["Yalnız tek taraflı skapula ağrısı","İki elde bozulan beceri","Boyun kası sertliği","Yalnız baş ağrısı"],"answer":1,"exp":"Omurilik basısında iki el uyuşur, ince motor beceri (çatal, düğme) bozulur ve yürüme bozukluğu ortaya çıkar."},{"level":"Temel","q":"Derin boyun fleksörlerinin tipik egzersizi hangisidir?","options":["Güçlü boyun ekstansiyonu","Hızlı boyun rotasyonu","Çene içeri alma (kraniyoservikal fleksiyon)","Omuz silkme"],"answer":2,"exp":"Çeneyi hafifçe içeri alarak yapılan kraniyoservikal fleksiyon, derin boyun fleksörlerinin (ör. m. longus colli) aktivitesini artıran tipik egzersizdir."},{"level":"Orta","q":"Pozitif Spurling testinin bulgusu nedir?","options":["Ekstansiyon + lateral fleksiyon: kola yayılan ağrı","Boyun fleksiyonu: sırta vuran ağrı","Omuz abdüksiyonuyla azalan semptomlar","El bileği fleksiyonuyla uyuşma"],"answer":0,"exp":"Boyun etkilenen tarafa ekstansiyon ve lateral fleksiyona getirilip aksiyel basınç verilir; kola yayılan ağrı veya uyuşma radikülopatiyi düşündürür."},{"level":"Orta","q":"C7 kök lezyonunda tipik olarak hangi refleks azalır?","options":["Biseps refleksi","Brakiyoradiyal refleks","Triseps refleksi","Patellar refleks"],"answer":2,"exp":"Triseps refleksi başlıca C7'yi, biseps refleksi C5'i, brakiyoradiyal refleks C6'yı değerlendirir."},{"level":"Klinik","q":"60 yaşında erkek: son zamanlarda düğme iliklemekte zorlanıyor, yürüyüşü dengesiz, Hoffmann refleksi pozitif. En çok neden şüphelenirsiniz?","options":["Nonspesifik boyun ağrısı","Torasik çıkış sendromu","Karpal tünel sendromu","Servikal spondilotik miyelopati"],"answer":3,"exp":"Bozulan ince motor beceri, yürüme bozukluğu ve patolojik refleks miyelopatiyi düşündürür. Güçlü servikal tekniklerden kaçının, hekime yönlendirin."},{"level":"Klinik","q":"Boyun ağrılı hastada servikal rotasyon egzersizi sırasında baş dönmesi ve çift görme oluyor. Doğru yaklaşım nedir?","options":["Alışması için devam etmek","Hemen durdurup hekime yönlendirmek","EHA'yı daha da artırmak","Sıcak uygulamaya geçmek"],"answer":1,"exp":"Baş dönmesi ve çift görme vasküler veya nörolojik bir soruna işaret edebilir. Hemen durdurun ve hekim değerlendirmesine yönlendirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omurga","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"Skolyoz","lead":"Skolyoz, omurganın vertebra rotasyonuyla birlikte yana eğriliğidir: üç boyutlu bir deformitedir. Büyüme döneminde ilerlemeye eğilimli olduğundan erken tanı ve düzenli kontrol önemlidir.","sheet":{"kind":"condition","items":[{"h":"Klinik tablo","t":"Omurga frontal düzlemde yana eğrilir: vertebra rotasyonuyla seyreden üç boyutlu bir deformitedir. Çoğunlukla nedeni bilinmez (idiyopatik), ergen kızlarda daha sıktır. Fonksiyonel skolyozdan ayrılmalıdır."},{"h":"Ana semptomlar","t":"Çoğunlukla az ağrılıdır; omuz, skapula, bel çizgisi asimetrisi veya öne eğilmede kaburga ya da lomber kambur dikkat çeker. Ağır olguda solunum işlevini de bozar."},{"h":"Değerlendirme noktaları","t":"Ayakta omuz, pelvis ve bel çizgisi simetrisi, öne eğilme testi, bacak boyu farkı (fonksiyonelden ayırma), esneklik, solunum. Eğriliği hekim röntgende Cobb açısıyla ölçer."},{"h":"Tedavi akışı","t":"İzlem, korse veya cerrahiye büyüme evresi ve Cobb açısına göre hekim karar verir. Fizyoterapist gövde ve solunum egzersizleri yaptırır ve korse kullanımını destekler."},{"h":"Dikkat, kontrendikasyon","t":"Büyüme döneminde ilerlemeye eğilimli olduğundan düzenli kontrol önemlidir. Yalnızca egzersizle düzeltilebileceğini söylemeyin. Korse kullanım süresini hekim belirler."},{"h":"Hekime yönlendirme","t":"Şiddetli veya gece ağrısı, nörolojik semptomlar (uyuşma, güçsüzlük), hızlı ilerleme, atipik eğrilik (ör. sola konveks torakal eğrilik), ateş."}]},"keypoints":["Skolyoz, vertebra rotasyonuyla seyreden üç boyutlu bir deformitedir","En tipik olanı ergen kızlarda sık görülen idiyopatik skolyozdur","Kaburga kamburunu öne eğilme testiyle kontrol edin","Büyüme döneminde ilerlemeye eğilimlidir, düzenli kontrol önemlidir","Ağrı veya nörolojik semptomla seyreden skolyozda hekime yönlendirin"],"case":{"text":"13 yaşında kız, okul taramasında skolyoz saptandı. Ayakta sağ omzu daha yüksek, öne eğilince sağda kaburga kamburu görülüyor. Ağrı ve nörolojik semptom yok. Ortopedi hekimi korse önerdi.","answer":"Adölesan idiyopatik skolyoz düşünülür. Fizyoterapist korsenin sürekli kullanımını destekler, gövde ve solunum egzersizleri yaptırır. Yalnızca egzersizle iyileşeceğini söylemeyin. Ağrı, nörolojik semptom veya hızlı ilerlemede hekime yönlendirin."},"questions":[{"level":"Temel","q":"Skolyoz taramasında öne eğilme testinde neye bakarsınız?","options":["Diz hiperekstansiyonuna","Kaburga kamburuna","Ayak arkının düşmesine","Artmış servikal lordoza"],"answer":1,"exp":"Öne eğilirken sırta arkadan bakılır ve vertebra rotasyonuna bağlı kaburga ya da lomber kambur aranır."},{"level":"Temel","q":"Skolyozda eğriliğin derecesini hangi ölçüt gösterir?","options":["Q açısı","Kollodiyafizer açı","Cobb açısı","Femorotibial açı"],"answer":2,"exp":"Eğriliğin derecesi röntgende, eğriliğin üst ve alt uç vertebralarına göre Cobb açısıyla ölçülür."},{"level":"Orta","q":"İdiyopatik skolyoz için hangisi doğrudur?","options":["Yaşlı erkeklerde sıktır","Ergen kızlarda sıktır","Her zaman şiddetli ağrılıdır","Yalnız frontal düzlemde deformitedir"],"answer":1,"exp":"İdiyopatik skolyoz ergen kızlarda daha sıktır, çoğunlukla az ağrılıdır ve vertebra rotasyonuyla seyreden üç boyutlu bir deformitedir."},{"level":"Orta","q":"Fonksiyonel skolyoza ne yol açabilir?","options":["Doğuştan vertebra anomalisi","Nöromüsküler hastalık","Vertebra rotasyon deformitesi","Bacak boyu farkı"],"answer":3,"exp":"Bacak boyu farkı veya ağrıya bağlı korunma postürünün yol açtığı fonksiyonel skolyoz neden ortadan kalkınca düzelir; yapısal olandan ayrılmalıdır."},{"level":"Klinik","q":"14 yaşında kız korse kullanıyor; sıktığı için kendi kararıyla daha az süre takıyor. Fizyoterapist ne yapmalıdır?","options":["Korseyi bırakıp yalnız egzersiz","Kullanımı desteklemek, hekimle görüşmek","Takma süresini daha da azaltmak","Sorun olmadığını söyleyip rahatlatmak"],"answer":1,"exp":"Takma süresinde hekim talimatı esastır. Sorunlarını dinleyin, kullanımı destekleyin, uyum konusunu hekim veya ortez teknisyeniyle görüşün."},{"level":"Klinik","q":"12 yaşında skolyozlu erkek çocuk, geceleri şiddetli sırt ağrısıyla uyanıyor. Doğru yaklaşım nedir?","options":["Germe öğretmek","İzlemek","Yükü artırmak","Hekim değerlendirmesine yönlendirmek"],"answer":3,"exp":"Şiddetli veya gece ağrısıyla seyreden skolyozun altında tümör gibi başka bir neden olabilir; bu yüzden hekim değerlendirmesine yönlendirilmelidir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Omurga","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"İnme","lead":"Beyin damarlarının tıkanması veya yırtılması sonucu ani gelişen nörolojik bulgular. Erken mobilizasyon ve göreve yönelik, tekrarlı pratik fonksiyonel iyileşmenin temelidir.","sheet":{"kind":"condition","items":[{"h":"Tablo","t":"İskemik inme (aterotrombotik, kardiyoembolik, laküner), beyin içi kanama ve subaraknoid kanama. Bulgular lezyonun yerine ve büyüklüğüne bağlıdır."},{"h":"Ana bulgular","t":"Hemiparezi, duyu bozukluğu, spastisite, afazi, tek taraflı ihmal (neglect), dizartri, disfaji; dikkat bozukluğu ve diğer yüksek kortikal işlev bozuklukları."},{"h":"Değerlendirme","t":"Parezi: Brunnstrom evresi, SIAS, FMA; spastisite: MAS; denge: BBS; ADL: FIM."},{"h":"Faza göre rehabilitasyon","t":"Akut faz: risk yönetimiyle erken mobilizasyon. Subakut faz: göreve yönelik pratik ve yürüme eğitimi. Kronik faz: aktivite ve katılımın sürdürülmesi."},{"h":"Dikkat, kontrendikasyon","t":"Akut fazda kan basıncı, bilinç düzeyi ve nörolojik bulgulardaki dalgalanmalara dikkat edin. Paretik kolu çekmek veya yanlış destek omuz ağrısına yol açar."},{"h":"Hekime yönlendirme","t":"Bilinç düzeyi düşerse, parezi veya dizartri aniden kötüleşirse, şiddetli baş ağrısı, kusma ya da ani kan basıncı değişikliği olursa hemen bildirin."}]},"keypoints":["Mobilizasyonu hekim talimatı ve sonlandırma kriterlerine göre başlatın ve durdurun","Paretik omzu çekmeyin, pozisyonlamayla koruyun","Neglect'te: ihmal edilen tarafa yönlendiren görevler ve çevre düzenlemesi","Fonksiyonel iyileşmenin temeli göreve yönelik, tekrarlı pratiktir","Ortezi yürüme kapasitesine ve hedeflere göre, kademeli olarak değerlendirin"],"case":{"text":"68 yaşında erkek, sağ a. cerebri media alanında iskemik inmeden 3 hafta sonra. Sol hemiparezi (alt ekstremite: Brunnstrom evre III). Tekerlekli sandalyeyle sık sık sol taraftaki nesnelere çarpıyor ve tabağın sol yarısındaki yemeği bırakıyor.","answer":"Sol neglect şüphesi; düşme ve çarpma riski yüksek. Sol tarafa dikkati geliştiren görevler, çevre düzenlemesi ve gözetim altında pratik. Neglect sürdükçe bağımsız hareket etmesine izin vermeyin."},"questions":[{"level":"Temel","q":"A. cerebri media alanındaki iskemik inmede hangi dağılımda hemiparezi tipiktir?","options":["Alt ekstremite ağırlıklı","Üst ekstremite ve yüz ağırlıklı","İki alt ekstremitede paraparezi","Simetrik tetraparezi"],"answer":1,"exp":"A. cerebri media, üst ekstremite ve yüzün motor korteksi dahil hemisferin lateral yüzünü besler; bu yüzden bunlar ağırlıklıdır. Alt ekstremite ağırlığı: a. cerebri anterior."},{"level":"Temel","q":"Sol neglect'e en sık hangi lezyon yol açar?","options":["Sol frontal lob","Serebellum","Sağ parietal lob","Beyin sapı"],"answer":2,"exp":"Sol neglect tipik olarak sağ hemisferin, özellikle sağ parietal lobun hasarında gelişir."},{"level":"Orta","q":"Hangi Brunnstrom evresinde sinerjiler istemli ve tam olarak ortaya çıkar?","options":["Evre II","Evre IV","Evre VI","Evre III"],"answer":3,"exp":"III: sinerjiler istemli ve tam olarak ortaya çıkar. II: birlikte reaksiyonlar, başlayan sinerjiler. IV: kısmen izole hareket mümkündür."},{"level":"Orta","q":"İnme sonrası spastisiteyi hangi ölçekle değerlendirirsiniz?","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"MAS, kas tonusunu pasif harekete karşı dirence göre derecelendirir. FIM ADL'yi, BBS dengeyi, MMSE bilişsel işlevi ölçer."},{"level":"Klinik","q":"İnme sonrası paretik omuzda subluksasyon var ve hasta transfer sırasında omuz ağrısı bildiriyor. Ne yaparsınız?","options":["Paretik kolundan tutarak yardım edersiniz","Omzu destekler, kolu çekmezsiniz","Ağrı geçene kadar tamamen sabitlersiniz","Her gün kuvvetli pasif germe yaparsınız"],"answer":1,"exp":"Subluksasyonlu omzu çekmek ağrı ve yaralanmaya yol açar. Destek aparatı ve pozisyonlamayla koruyun, EHA'yı ağrısız sınırlar içinde sürdürün."},{"level":"Klinik","q":"Akut iskemik inme: mobilizasyon sırasında dizartri ve parezi aniden kötüleşiyor. Ne yaparsınız?","options":["Yürüme çalışmasına devam edersiniz","Dinlendikten sonra devam edersiniz","Durur ve hemen hekime bildirirsiniz","Ertesi gün yeniden değerlendirirsiniz"],"answer":2,"exp":"Nörolojik bulguların ani kötüleşmesi lezyonun genişlemesine veya nüksüne işaret edebilir. Egzersizi durdurun, hastayı güvene alın ve hemen hekime haber verin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Nöroloji","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"Parkinson Hastalığı","lead":"Orta beyindeki substantia nigra'nın dopaminerjik nöronlarının dejenerasyonuyla motor bulgulara yol açan ilerleyici nörodejeneratif hastalık. Anahtar: dış uyaranlarla (cue) hareket ve düşme önleme.","sheet":{"kind":"condition","items":[{"h":"Tablo","t":"Substantia nigra'nın dopaminerjik nöronları dejenere olur, striatumda dopamin eksikliği gelişir ve hareket kontrolü bozulur. Bulgular yavaş ilerler."},{"h":"Ana bulgular","t":"İstirahat tremoru, rijidite, akinezi/bradikinezi, postüral instabilite. Ayrıca donma (freezing), küçük adımlı yürüme, öne eğik postür ve motor dışı bulgular (ör. kabızlık)."},{"h":"Değerlendirme","t":"Hoehn-Yahr evresi, MDS-UPDRS, BBS, TUG, yürüme hızı, donma varlığı, düşme öyküsü ve ilaç etkisinin gün içi dalgalanması."},{"h":"Tedavi akışı","t":"Erken dönemde genel hareket ve dayanıklılığın korunması; ilerledikçe görsel/işitsel cue destekli yürüme eğitimi, denge egzersizleri, düşme önleme ve çevre düzenlemesi."},{"h":"Dikkat, kontrendikasyon","t":"Egzersiz zamanını ilaç etkisindeki dalgalanmaya (wearing-off, diskinezi) göre ayarlayın. Ortostatik hipotansiyona da dikkat edin."},{"h":"Hekime yönlendirme","t":"Bulgularda ani kötüleşme, ilaç etki süresinin kısalması, halüsinasyon, tekrarlayan düşmeler, disfajinin artması veya şiddetli rijiditeyle yüksek ateş olursa bildirin."}]},"keypoints":["Egzersizi ilacın etkili olduğu \"on\" dönemine denk getirin","Dış uyaranlar (yer şeritleri, ritmik ses) donmayı azaltır","Büyük amplitüdlü, yavaş hareketleri tekrar tekrar çalıştırın","Dönerken ve çift görevde düşme riski yüksektir","Öne eğik postüre karşı gövde ekstansiyonu ve rotasyonu egzersizleri"],"case":{"text":"72 yaşında kadın, Parkinson hastalığı (Hoehn-Yahr III). Dar kapılarda ve dönerken ayakları donuyor, evde birkaç kez düşmüş. Bulgular ilacın etkisi azaldığında artıyor.","answer":"Donma ve postüral instabilite nedeniyle düşme riski yüksek. \"On\" döneminde görsel/işitsel cue ile yürüme ve dönme çalıştırın, ev ortamını düzenleyin. İlaç konusunu hekimle görüşün; hasta dozu kendisi değiştirmemeli."},"questions":[{"level":"Temel","q":"Parkinson hastalığında öncelikle hangi yapı dejenere olur?","options":["Serebellum","Substantia nigra","Omuriliğin ön boynuzu","Motor korteks"],"answer":1,"exp":"Substantia nigra'nın dopaminerjik nöronları dejenere olur; striatumdaki dopamin düzeyinin düşmesi motor bulgulara yol açar."},{"level":"Temel","q":"Parkinson hastalığının tremoru için hangisi tipiktir?","options":["İntansiyon tremoru","Hareketle artar","İstirahat tremoru","Uykuda da sürer"],"answer":2,"exp":"İstirahatte ortaya çıkar ve istemli hareketle azalır. İntansiyon tremoru serebellar hasarda görülür."},{"level":"Orta","q":"Hoehn-Yahr evre III için hangisi tipiktir?","options":["Postüral instabilite ortaya çıkar","Yalnızca tek taraflı bulgular","Tekerlekli sandalye, yatağa bağımlılık","Bilateral bulgular, postüral refleksler sağlam"],"answer":0,"exp":"III: postüral instabiliteyle bilateral bulgular. I: tek taraflı; II: bilateral, postüral refleksler sağlam; V: tekerlekli sandalye veya yatağa bağımlılık."},{"level":"Orta","q":"Donma (freezing) neyle azaltılabilir?","options":["Gözler kapalı yürüme","Yürüme hızını aniden artırma","Dar koridorda tekrarlı yürüme","Görsel cue, ör. yer şeritleri"],"answer":3,"exp":"Dış uyaranlar (yer şeritleri, metronom sesi) donmayı azaltır ve adım uzunluğunu artırır."},{"level":"Klinik","q":"Parkinson hastası ilacını sabah ve öğlen alıyor; ikindi sonrası yavaşlıyor, egzersiz aksıyor. Ne yaparsınız?","options":["Öğleden sonra egzersiz miktarını artırırsınız","Egzersizi \"on\" dönemine alırsınız","Hasta dozu kendisi ayarlar","Fizyoterapiyi bırakırsınız"],"answer":1,"exp":"Wearing-off şüphesi. Egzersizi ilacın etkili olduğu döneme planlayın, dalgalanmayı hekime bildirin. İlaç ayarını hekim yapar."},{"level":"Klinik","q":"Parkinson hastası ilacı aniden bırakmış; yüksek ateş, belirgin rijidite ve bilinç bulanıklığı var. Ne yaparsınız?","options":["Hafif hareketle beklersiniz","Germeyi artırırsınız","Durur, hemen hekime haber verirsiniz","Ertesi gün yeniden değerlendirirsiniz"],"answer":2,"exp":"İlacın ani kesilmesinden sonra ateş, rijidite ve bilinç bulanıklığı malign sendrom (NMS benzeri tablo) şüphesidir, acil bakım gerekir. Hemen hekime haber verin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Nöroloji","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"Multipl Skleroz","lead":"Merkezi sinir sisteminin miyelin kılıfı inflamasyonla hasar görür; sıklıkla ataklar ve remisyonlar birbirini izler. Anahtar: yorgunluğu ve vücut ısısı artışını gözeterek yükü dozlamak.","sheet":{"kind":"condition","items":[{"h":"Tablo","t":"Otoimmün hastalık: beyin, omurilik ve optik sinirde zaman ve alan olarak dağılmış demiyelinizan odaklar gelişir. Genç erişkinlerde, özellikle kadınlarda daha sıktır."},{"h":"Ana bulgular","t":"Görme bozukluğu (optik nörit), kas güçsüzlüğü, duyu bozukluğu, spastisite, ataksi, yorgunluk, mesane ve bağırsak işlev bozukluğu, Lhermitte belirtisi vb."},{"h":"Değerlendirme","t":"EDSS, manuel kas testi, MAS, denge, yürüme kapasitesi ve yorgunluk düzeyi. Bulguların gün içi ve sıcaklığa bağlı değişimini de kontrol edin."},{"h":"Tedavi akışı","t":"Atakta dinlenme ve nazik EHA egzersizleri; remisyonda yorgunluğa göre ayarlanmış, kademeli aerobik, kuvvetlendirme ve denge egzersizleri."},{"h":"Dikkat, kontrendikasyon","t":"Vücut ısısının artması bulguları geçici olarak kötüleştirir (Uhthoff fenomeni): sıcak ortamdan ve aşırı yüklenmeden kaçının, dinlenme araları verin."},{"h":"Hekime yönlendirme","t":"Yeni görme kaybı, uyuşma veya felç ya da 24 saatten uzun süren ani kötüleşme atağa işaret edebilir: hekime bildirin."}]},"keypoints":["Serin ortamda çalışın, vücut ısısının artmasından kaçının","Belirgin yorgunlukta yükü azaltın, dinlenme araları verin","Atakta ve remisyonda farklı egzersiz içerikleri uygulayın","ADL eğitimine enerji koruma tekniklerini ekleyin","Spastisiteyi germe ve pozisyonlamayla yönetin"],"case":{"text":"32 yaşında kadın, multipl skleroz (remisyon). Sıcak spor salonunda egzersiz sırasında alt ekstremitede güçsüzlük ve uyuşma arttı, ancak dinlenme ve serinleme sonrası yaklaşık 30 dakikada düzeldi.","answer":"Vücut ısısı artışına bağlı geçici kötüleşme (Uhthoff fenomeni) olası. Serin ortamda, dinlenme aralarıyla, azaltılmış yoğunlukta devam edin. Dinlenmeyle düzelmez ve bulgular sürerse atak düşünün ve hekime bildirin."},"questions":[{"level":"Temel","q":"Multipl sklerozda öncelikle hangi yapı hasar görür?","options":["Periferik sinirlerin miyelini","Merkezi sinir sisteminin miyelini","Nöromüsküler kavşak","İskelet kası lifleri"],"answer":1,"exp":"Beyin, omurilik ve optik sinirin, yani merkezi sinir sisteminin miyelin kılıfı hasar görür. Periferik demiyelinizasyon ör. Guillain-Barre sendromunda görülür."},{"level":"Temel","q":"Vücut ısısı artışında bulguların geçici kötüleşmesi hangi fenomendir?","options":["Lhermitte belirtisi","Romberg belirtisi","Babinski refleksi","Uhthoff fenomeni"],"answer":3,"exp":"Uhthoff fenomeni: vücut ısısı artınca bulgular geçici kötüleşir. Lhermitte belirtisi: boyun fleksiyonunda sırttan ekstremitelere elektrik çarpması gibi ağrı yayılır."},{"level":"Orta","q":"Multipl skleroz atağında uygun fizyoterapi hangisidir?","options":["Yüksek yoğunluklu kuvvetlendirme","Uzun süreli aerobik egzersiz","Nazik EHA egzersizleri","Sıcak ortamda egzersiz"],"answer":2,"exp":"Atakta inflamasyon aktiftir, bu yüzden aşırı yüklenmeden kaçının; nazik eklem hareket açıklığı egzersizleri ve pozisyonlama ön plandadır."},{"level":"Orta","q":"Boyun fleksiyonunda sırttan ekstremitelere elektrik çarpması gibi ağrı yayılması hangi belirtidir?","options":["Lhermitte belirtisi","Uhthoff fenomeni","Hoffmann refleksi","Trendelenburg belirtisi"],"answer":0,"exp":"Lhermitte belirtisi servikal omurilik lezyonlarında sıktır ve multipl sklerozun karakteristik belirtilerinden biridir."},{"level":"Klinik","q":"MS hastası akşama doğru çok yoruluyor, yürüyüşü dengesizleşiyor. Ne önerirsiniz?","options":["Akşama doğru hareketi artırsın","Aktiviteyi daha iyi olduğu saatlere dağıtsın","Dinlenmeden devam etsin","Sıcak odada egzersiz yapsın"],"answer":1,"exp":"Yorgunluğu enerji koruma yaklaşımıyla yönetin: aktiviteyi günün daha iyi saatlerine dağıtın ve planlı dinlenme araları verin."},{"level":"Klinik","q":"Remisyondaki MS hastası: günlerdir bir gözde görme kaybı ve yeni alt ekstremite uyuşması var. Ne yaparsınız?","options":["Egzersiz yoğunluğunu artırırsınız","Sıcak uygulama eklersiniz","Atak şüphesiyle hekime bildirirsiniz","Bir ay sonra yeniden değerlendirirsiniz"],"answer":2,"exp":"Süregelen yeni nörolojik bulgu atağa işaret edebilir. Yükü artırmayın ve en kısa sürede hekime bildirin."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Nöroloji","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"Omurilik Yaralanması","lead":"Omurilik yaralanması, yaralanma seviyesinin altında motor, duyusal ve otonom işlevleri bozar. Odakta kalan işlevlere göre hedef belirleme ve komplikasyonların önlenmesi vardır.","sheet":{"kind":"condition","items":[{"h":"Tablo","t":"Düşme, trafik kazası veya hastalık sonucu gelişir; tam ve inkomplet yaralanma ayrılır. Servikal yaralanma tetraplejiye, torakolomber yaralanma parapleji yol açar."},{"h":"Ana bulgular","t":"Yaralanma seviyesinin altında motor felç ve duyu bozukluğu, mesane ve bağırsak işlev bozukluğu, otonom bozukluk (ortostatik hipotansiyon, ısı düzenleme bozukluğu), spastisite."},{"h":"Değerlendirme","t":"ASIA kriterlerine göre nörolojik seviyeyi ve AIS'i belirleyin; anahtar kas gücünü ve duyuyu segment segment değerlendirin. ADL'yi FIM veya SCIM ile ölçün."},{"h":"Tedavi akışı","t":"Akut fazda solunum yönetimi, pozisyonlama, EHA'nın korunması; subakut fazda kalan kasların kuvvetlendirilmesi ve ADL eğitimi: oturma, transfer, tekerlekli sandalye kullanımı."},{"h":"Dikkat, kontrendikasyon","t":"T6 üstü yaralanmalarda otonom disrefleksiye dikkat edin. Bası yarasını önleyen basınç boşaltmayı öğretin; ortostatik hipotansiyonda kademeli dikleştirme."},{"h":"Hekime yönlendirme","t":"Baş ağrısı, terleme, yüzde kızarmayla ani kan basıncı artışı; nörolojik kötüleşme, ateş, bası yarasının kötüleşmesi ve alt ekstremite şişliği (DVT şüphesi) olursa bildirin."}]},"keypoints":["Nörolojik seviye: işlevi hâlâ sağlam olan en kaudal segment","C6 yaralanmada kavrama için tenodez etkisini kullanın","Otonom disreflekside hastayı oturtun, tetikleyiciyi (ör. dolu mesane) giderin","Düzenli basınç boşaltma hareketleriyle bası yarasını önleyin","Servikal yaralanmada solunum işlevini değerlendirin, balgam atılmasına yardım edin"],"case":{"text":"25 yaşında erkek, C6 tam yaralanma (AIS A), kazadan 2 ay sonra. Egzersiz sırasında aniden şiddetli baş ağrısı, yüzde kızarma ve terleme başlıyor, kan basıncı belirgin yükseliyor. Planlanan kateterizasyon saati geçmiş.","answer":"Dolu mesanenin tetiklediği otonom disrefleksi şüphesi. Egzersizi durdurun, hastayı oturtun (baş yukarıda), giysileri gevşetin, tetikleyiciyi bulup giderin ve hemen hekime ve hemşireye haber verin. Yatar pozisyonda bekletmeyin."},"questions":[{"level":"Temel","q":"İtme (push-up) transferini mümkün kılan C7 anahtar kası hangisidir?","options":["m. biceps brachii","m. triceps brachii","m. iliopsoas","m. quadriceps femoris"],"answer":1,"exp":"C7'nin anahtar kası m. triceps brachii'dir (dirsek ekstansiyonu). M. biceps brachii C5, m. iliopsoas L2, m. quadriceps femoris L3 anahtar kasıdır."},{"level":"Temel","q":"Tenodez etkisinin kavrama için kullanılması hangi yaralanma seviyesine özgüdür?","options":["C4","T6","C6","L3"],"answer":2,"exp":"C6 yaralanmada el bileği ekstansiyonu mümkündür; ekstansiyonda parmaklar pasif olarak fleksiyona gelir (tenodez etkisi), bu kavrama için kullanılır."},{"level":"Orta","q":"ASIA bozukluk ölçeğinde (AIS) A derecesi ne anlama gelir?","options":["İnkomplet, yalnızca duyu korunmuş","Motor işlev kısmen korunmuş","Nörolojik olarak normal","S4–5'te bile motor ve duyu işlevi yok"],"answer":3,"exp":"AIS A: tam yaralanma, en alt sakral segmentlerde (S4–5) bile motor ve duyu işlevi yoktur. AIS B: inkomplet, yalnızca duyu korunmuştur."},{"level":"Orta","q":"Otonom disrefleksi hangi yaralanma seviyesinde sıktır?","options":["T6 ve üstü","T12 ve altı","L3 ve altı","Kauda ekuina"],"answer":0,"exp":"T6 üstü yaralanmada lezyonun altındaki uyaranlara (ör. dolu mesane) aşırı sempatik yanıt ve ani kan basıncı artışı gelişir."},{"level":"Klinik","q":"C6 yaralanmalı hasta: tilt masasında açı artırılırken baş dönmesi, solukluk ve kan basıncı düşüşü oluyor. Ne yaparsınız?","options":["Alışsın diye açıyı artırmaya devam edersiniz","Masayı hemen yatay konuma getirirsiniz","Egzersize devam edersiniz","Otururken boynunu öne eğdirirsiniz"],"answer":1,"exp":"Ortostatik hipotansiyon şüphesi. Açıyı geri alın, bulguları ve kan basıncını kontrol edin. Önleme: karın bağı, kompresyon çorabı, kademeli dikleştirme."},{"level":"Klinik","q":"Torakal tam yaralanmalı, tekerlekli sandalyedeki hasta: sakral kızarıklık basınca solmuyor, kalıcı. Ne yaparsınız?","options":["Kızarıklığa kuvvetli masaj yaparsınız","Daha uzun oturtarak alıştırırsınız","Basınç boşaltma yöntemini gözden geçirirsiniz","Bir şey yapmaya gerek yoktur"],"answer":2,"exp":"Kalıcı kızarıklık bası yarasının erken belirtisidir. Basınç boşaltmayı ve oturma minderini gözden geçirin, bakım ekibine bildirin. Kızarıklığa masaj doku hasarını artırır."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Nöroloji","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"Periferik Sinir Yaralanmaları","lead":"Travma veya bası sonucu periferik sinir hasar görür ve innervasyon alanının motor, duyusal ve otonom işlevi azalır. Yaralanmanın ağırlığını ve rejenerasyonun seyrini izlemek önemlidir.","sheet":{"kind":"condition","items":[{"h":"Tablo","t":"Seddon sınıflaması: geçici iletim bozukluğu (nöropraksi), akson kopması (aksonotmezis), sinirin tamamen kopması (nörotmezis)."},{"h":"Ana bulgular","t":"İnnerve edilen kaslarda flask felç ve atrofi, innervasyon alanında duyu ve terleme bozukluğu. Tendon refleksleri azalmış veya kaybolmuştur."},{"h":"Değerlendirme","t":"Manuel kas testi, duyu muayenesi (dokunma, ağrı, iki nokta ayrımı), Tinel belirtisinin yerindeki değişim, EMG ve sinir iletim çalışması sonuçları."},{"h":"Tedavi akışı","t":"Ortezle felçli kasların aşırı gerilmesini önleyin, EHA'yı koruyun. Reinnervasyon hızına göre aktif yardımlı egzersizden kademeli olarak kuvvetlendirmeye geçin."},{"h":"Dikkat, kontrendikasyon","t":"Duyu kaybı olan alanda yanık ve bası yaralanmalarına dikkat edin. Felçli kasların aşırı yüklenmesinden ve sinir onarımı sonrası aşırı germeden kaçının."},{"h":"Hekime yönlendirme","t":"Felcin ani ilerlemesi, şiddetli ağrı veya şişlik, cilt rengi değişikliği ya da beklenen sürede iyileşme olmaması durumunda bildirin."}]},"keypoints":["Tinel belirtisinin distale ilerlemesi sinir rejenerasyonunun işaretidir","Düşük el ve düşük ayakta ortezle kontraktürü ve aşırı gerilmeyi önleyin","Duyusu azalmış alanı gözle kontrol edip korumayı öğretin","İyileşme yaralanmaya yakın kaslardan uzak kaslara doğru ilerler","Sinir onarımı sonrası hekimin belirttiği immobilizasyon süresine uyun"],"case":{"text":"45 yaşında erkek: humerus diafiz kırığından beri el bileğini ve parmaklarını ekstansiyona getiremiyor. El sırtında, başparmak ile işaret parmağı arasında duyu azalmış. Dirsek ekstansiyonu yapılabiliyor.","answer":"Humerus diafizi düzeyinde gelişen n. radialis felci (düşük el) şüphesi. El bileğini dorsifleksiyonda tutan ortezle aşırı gerilmeyi ve kontraktürü önleyin, EHA'yı koruyun. İyileşmeyi Tinel belirtisi ve kas testiyle izleyin; gecikirse hekime bildirin."},"questions":[{"level":"Temel","q":"Hangi sinirin felci düşük ele yol açar?","options":["n. medianus","n. ulnaris","n. radialis","n. musculocutaneus"],"answer":2,"exp":"N. radialis el bileği ve parmak ekstansörlerini innerve eder; felcinde el bileği ekstansiyona gelmez, düşük el gelişir."},{"level":"Temel","q":"Hangi sinirin felci 4.–5. parmakta pençeleşmeye yol açar?","options":["n. ulnaris","n. radialis","n. axillaris","n. femoralis"],"answer":0,"exp":"N. ulnaris felcinde interosseöz kaslar ve 4.–5. parmağın lumbrikalleri felç olur; yüzük ve serçe parmak pençe pozisyonuna gelir."},{"level":"Orta","q":"Seddon'a göre hangi durumda akson sağlamdır ve yalnızca iletim geçici olarak bozulmuştur?","options":["Nörotmezis","Nöropraksi","Aksonotmezis","Waller dejenerasyonu"],"answer":1,"exp":"Nöropraksi, akson devamlılığının korunduğu geçici iletim bozukluğudur; Waller dejenerasyonu olmaz, görece hızlı iyileşir."},{"level":"Orta","q":"Periferik sinir rejenerasyonunu izlemek için hangi bulgu uygundur?","options":["Artmış tendon refleksleri","Babinski refleksi","Rijidite","Tinel belirtisinin yerinin ilerlemesi"],"answer":3,"exp":"Rejenere olan akson ucuna perküsyon yayılan karıncalanma oluşturur; bu noktanın distale ilerlemesi rejenerasyonun işaretidir."},{"level":"Klinik","q":"Bacak alçısından sonra fibula başına bası nedeniyle ayak bileği dorsifleksiyona gelmiyor. Ne yaparsınız?","options":["Ayak bileğini plantar fleksiyonda tutarsınız","Düşük ayağı ayak-ayak bileği ortezi ile yönetirsiniz","Felçli kası yüksek dirençle kuvvetlendirirsiniz","Duyusu azalmış alana yoğun sıcak uygularsınız"],"answer":1,"exp":"N. peroneus communis felcine bağlı düşük ayakta ayak-ayak bileği ortezi takılmayı ve plantar fleksiyon kontraktürünü önler. Duyusu azalmış alanda sıcak yanık riski taşır."},{"level":"Klinik","q":"El bileğinin volar yüzündeki kesiden sonra başparmak opozisyonu yapılamıyor, tenar atrofi var. Hangi sinirin yaralanması olasıdır?","options":["n. ulnaris","n. radialis ramus superficialis","n. medianus","n. musculocutaneus"],"answer":2,"exp":"N. medianus tenar kasları (ör. m. opponens pollicis) innerve eder; felcinde opozisyon zorlaşır, maymun eli gelişir."}],"seccion":"Yaralanmalar ve rehabilitasyon","grupo":"Nöroloji","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"Manuel Terapi (Maitland)","lead":"Eklem aksesuar hareketlerinin değerlendirilmesine ve derecelendirilmiş, osilasyonlu pasif hareketlere dayanan, ağrı ve EHA üzerine etki eden sistem. Değerlendirme ve yeniden değerlendirmenin tekrarı esastır.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Eklem aksesuar hareketlerini kullanarak ağrıyı azaltır ve eklem mobilitesini artırır. Tekniği ve şiddeti hastanın yanıtına göre seçersiniz."},{"h":"Ana teknikler ve türler","t":"Derece I–IV osilasyonlu pasif hareketler. Derece V yüksek hızlı, küçük amplitüdlü thrust'tır (manipülasyon)."},{"h":"Endikasyonlar","t":"Eklem kaynaklı ağrı ile kapsül veya bağ kısalığına bağlı hareket kısıtlılığı (bel ağrısı, boyun ağrısı, donuk omuz vb.)."},{"h":"Kontrendikasyon, dikkat","t":"Kırık, malign tümör, enfeksiyon, inflamatuvar hastalığın akut dönemi, ağır osteoporoz, ilerleyen nörolojik bulgu veya servikal damar hasarı şüphesinde uygulanmaz."},{"h":"Uygulama ipuçları","t":"Ağrı baskınsa derece I–II, sertlik baskınsa derece III–IV seçin. Tedavi öncesi ve sonrası karşılaştırma işaretlerini kontrol ederek etkiyi değerlendirin."},{"h":"Kanıt","t":"Terapötik egzersizle birlikte kısa vadede ağrıyı azaltabilir. Tek başına uygulandığında uzun vadeli etkisi sınırlıdır."}]},"keypoints":["Ağrıda derece I–II, sertlikte derece III–IV","Etkiyi tedavi öncesi ve sonrası karşılaştırma işaretleriyle değerlendirin","Aksesuar hareketi taraflar arası farka ve son hissine göre değerlendirin","Teknikten önce kırmızı bayrakları dışlayın","Kazanılan EHA'yı ev egzersizleriyle sürdürün"],"case":{"text":"50 yaşında erkek, kronik sağ boyun sertliği. İstirahat ağrısı neredeyse yok; sağa rotasyonun sonunda direnç ve hafif ağrı hissediyor. Kırmızı bayrak yok.","answer":"Sertlik ağrıdan baskın, bu yüzden dirence giren derece III–IV düşünülebilir. Tedavi öncesi ve sonrası rotasyon EHA'sını ve ağrıyı yeniden değerlendirin, ev egzersizlerine aktarın. Değerlendirme yapmadan güçlü thrust uygulamayın."},"questions":[{"level":"Temel","q":"Maitland derece IV'ü hangisi doğru tanımlar?","options":["Dirençten önce büyük amplitüd","Açıklığın başında küçük amplitüd","Açıklığın sonunda küçük amplitüd","Direnç içinde büyük amplitüd"],"answer":2,"exp":"Derece IV, hareket açıklığının sonunda direnç içinde küçük amplitüdlü harekettir. Açıklığın başında küçük amplitüd: I; direnç içinde büyük amplitüd: III."},{"level":"Temel","q":"Öncelikle ağrı giderme için hangi dereceyi seçersiniz?","options":["Derece I–II","Derece III–IV","Yalnızca derece V","Yalnızca derece IV"],"answer":0,"exp":"Derece I–II dirençten önceki aralıkta uygulanır, esas olarak ağrı giderme içindir. III–IV sertlik ve hareket kısıtlılığı içindir."},{"level":"Orta","q":"Maitland derece V hangi tekniği ifade eder?","options":["Dirençten önce büyük amplitüd","Yüksek hızlı, küçük amplitüdlü thrust","Sürekli traksiyon","Yumuşak doku yoğurma"],"answer":1,"exp":"Derece V, hareket açıklığının sonunda uygulanan yüksek hızlı, küçük amplitüdlü thrust, yani manipülasyondur."},{"level":"Orta","q":"Etkiyi değerlendirmek için tedavi öncesi ve sonrası neyi karşılaştırırsınız?","options":["Laboratuvar değerlerini","Görüntüleme bulgularını","Vücut ağırlığı değişimini","Karşılaştırma işaretlerini (asterisk)"],"answer":3,"exp":"Tedavi öncesi tekrarlanabilir bulguları ve hareket açıklığını karşılaştırma işareti olarak kaydedin, sonra değişimi kontrol edin."},{"level":"Klinik","q":"Akut bel ağrılı hasta: harekette şiddetli ağrı ve koruyucu kas spazmı var. Hangi dereceyle başlarsınız?","options":["Derece IV","Derece V","Derece I–II","Derece III"],"answer":2,"exp":"Şiddetli ağrı ve yüksek irritabilitede dirence girmeyen derece I–II ile ağrıyı azaltın."},{"level":"Klinik","q":"Boyun ağrılı hasta: boyun rotasyonunda baş dönmesi, çift görme ve dizartri oluyor. Ne yaparsınız?","options":["Durur ve hekime bildirirsiniz","Derece IV'ü güçlendirirsiniz","Thrust ile düzeltmeyi denersiniz","Tekrar sayısını artırırsınız"],"answer":0,"exp":"Baş dönmesi, çift görme ve dizartri servikal damar hasarına işaret eder. Manuel terapiyi bırakın ve hekime bildirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"Proprioseptif Nöromüsküler Fasilitasyon (PNF)","lead":"Proprioseptörleri uyararak nöromüsküler yanıtları kolaylaştırır. Spiral-diyagonal hareket paternleri tipiktir; kas kuvveti, koordinasyon ve EHA'yı geliştirmek için kullanılır.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Proprioseptörleri uyararak motor yanıtı kolaylaştırır; kas kuvvetini, koordinasyonu, stabiliteyi ve EHA'yı geliştirir."},{"h":"Ana teknikler ve türler","t":"Omuz kuşağı, pelvis ve ekstremitelerin diyagonal paternleri; ritmik başlatma, tut-gevşe, ritmik stabilizasyon ve diğer tekniklerle birlikte."},{"h":"Endikasyonlar","t":"Kas güçsüzlüğü, koordinasyon bozukluğu, hareket kısıtlılığı veya eklem instabilitesi olan merkezi sinir sistemi ve ortopedik tablolar, spor yaralanmaları."},{"h":"Kontrendikasyon, dikkat","t":"İyileşmemiş kırıkta, direncin henüz izin verilmediği postoperatif bölgede ve şiddetli ağrıda uygulanmaz. Kardiyovasküler riskte nefes tutmaya dikkat edin."},{"h":"Uygulama ipuçları","t":"Manuel temas, sözel komut, görsel geri bildirim, traksiyon/approksimasyon, germe, optimal direnç ve zamanlamayı birleştirin. Direnç akıcı hareketi engellememeli."},{"h":"Kanıt","t":"EHA'yı ve kas işlevini geliştirdiği bildirilmektedir. Etki tabloya ve hedefe bağlıdır; diğer terapötik egzersizlerle birlikte uygulanır."}]},"keypoints":["Ağrıya bağlı hareket kısıtlılığında: tut-gevşe","Hareketi başlatmak zorsa: ritmik başlatma","Direnç \"optimal\" olmalı: akıcı hareketi engellememeli","Normal zamanlamada hareket distalden başlar","Nefes tutmaktan kaçının, hasta sürekli nefes almalı"],"case":{"text":"60 yaşında kadın, periartrit humeroskapularis sonrası kısıtlı abdüksiyon. Harekette ağrı şiddetli, pasif germede koruyucu kas spazmı artıyor.","answer":"Ağrılı hareket kısıtlılığında izometrik kontraksiyon kullanan tut-gevşe uygundur. Ağrıyı artırmadan uygulayın, öncesinde ve sonrasında EHA'yı ölçün. Tekrarlı kuvvetli pasif germeden kaçının."},"questions":[{"level":"Temel","q":"PNF hareket paternleri için hangisi tipiktir?","options":["Tek düzlemli, düz hareket","Spiral-diyagonal hareket","Yalnızca izokinetik hareket","Yalnızca pasif hareket"],"answer":1,"exp":"PNF paternleri fleksiyon-ekstansiyon, addüksiyon-abdüksiyon ve rotasyon bileşenlerini birleştiren spiral-diyagonal hareketlerdir."},{"level":"Temel","q":"Hareketin yönünü fizyoterapistin eli aracılığıyla ileten PNF temel öğesi hangisidir?","options":["Soğuk uyaran","Elektrik stimülasyonu","Manuel temas","Ultrason"],"answer":2,"exp":"Manuel temas, hareket yönünde uygulanan basınçla hastanın kas kontraksiyonunu ve hareket yönünü yönlendirir."},{"level":"Orta","q":"Hasta hareketi başlatmakta zorlanıyorsa hangi PNF tekniğini uygularsınız?","options":["Tut-gevşe","Kas-gevşe","Ritmik stabilizasyon","Ritmik başlatma"],"answer":3,"exp":"Ritmik başlatma pasif → aktif yardımlı → aktif → dirençli sırasıyla ilerler, hareketin başlatılmasına ve öğrenilmesine yardım eder."},{"level":"Orta","q":"Hangi teknik alternatif izometrik kontraksiyonlarla eklem stabilitesini artırır?","options":["Ritmik stabilizasyon","Ritmik başlatma","Kas-gevşe","Tekrarlı germe"],"answer":0,"exp":"Ritmik stabilizasyonda antagonist kas grupları hareket olmadan, sırayla izometrik kasılır; bu stabiliteyi artırır."},{"level":"Klinik","q":"Diz fleksiyonu ağrı nedeniyle kısıtlı. EHA'yı artırmak için hangi PNF tekniği uygundur?","options":["Kas-gevşe","Tut-gevşe","Tekrarlı germe","Ritmik başlatma"],"answer":1,"exp":"Tut-gevşede kısıtlayan kasın izometrik kontraksiyonunu gevşeme izler; ağrılı hareket kısıtlılığında kullanılır."},{"level":"Klinik","q":"Dirençli PNF egzersizi sırasında hasta nefesini tutuyor ve yüzü kızarıyor. Ne yaparsınız?","options":["Direnci artırmaya devam edersiniz","Tekrar sayısını artırırsınız","Nefesini tutmamasını söylersiniz","Daha hızlı tempo istersiniz"],"answer":2,"exp":"Nefes tutma kan basıncını yükseltir. Direnci ayarlayın ve egzersizi sürekli nefes alarak yapmasını isteyin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"Elektroterapi","lead":"Elektriksel uyarıyla ağrıyı azaltır veya kas kontraksiyonu oluşturur. Akım türü ve parametreleri amaca göre seçilir; kontrendikasyonlar her zaman kontrol edilmelidir.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Ağrı giderme, kas kontraksiyonu oluşturarak kas kuvvetini koruma ve artırma, hareketi yeniden öğrenme, ödemi azaltma."},{"h":"Ana teknikler ve türler","t":"TENS (transkutanöz elektriksel sinir stimülasyonu), NMES (nöromüsküler elektriksel stimülasyon), FES (fonksiyonel elektriksel stimülasyon), interferansiyel akım, yüksek voltajlı pulsatil akım vb."},{"h":"Endikasyonlar","t":"Akut ve kronik ağrı, ameliyat veya immobilizasyon sonrası kas güçsüzlüğü, inme sonrası paretik kasların fasilitasyonu, yürürken düşük ayağın uyarılması."},{"h":"Kontrendikasyon, dikkat","t":"Kalp pili ve diğer implante elektronik cihazlarda, gebelerde karın ve bel bölgesinde, karotis sinüsü üzerinde, tümörlü, cildi hasarlı ve duyu bozukluğu olan alanda kaçının."},{"h":"Uygulama ipuçları","t":"Cilt durumunu ve duyuyu kontrol edin; elektrot yeri ve boyutu, frekans, puls genişliği, şiddet ve tedavi süresini amaca göre ayarlayın."},{"h":"Kanıt","t":"Ameliyat sonrası kuadriseps güçsüzlüğünde ve inme sonrası fonksiyonel iyileşmede yararlı olduğu bildirilmektedir. Ağrı üzerine etkisine dair sonuçlar çelişkilidir."}]},"keypoints":["Tedaviden önce cilt durumunu ve olası duyu bozukluğunu kontrol edin","Anamnezde implante elektronik cihazları mutlaka sorun","Ağrı için TENS, kas kontraksiyonu oluşturmak için NMES seçin","Tedavi sonrası elektrot altında kızarıklık veya ısı artışı olup olmadığına bakın","Elektriksel uyarıyı aktif egzersizle birleştirin"],"case":{"text":"65 yaşında erkek, diz protezi ameliyatı sonrası. M. quadriceps'in istemli kontraksiyonu zayıf, SLR'de diz tam ekstansiyona gelmiyor (ekstansiyon kaybı). Kalp pili yok, cilt lezyonu yok.","answer":"Kuadriseps güçsüzlüğü ve yetersiz kontraksiyon için aktif egzersizle birlikte NMES düşünülebilir. Elektrotları ameliyat yarasından uzak yerleştirin, cilt ve ağrı yanıtını izleyin. Yaraya ve duyusu azalmış alana akım vermeyin."},"questions":[{"level":"Temel","q":"Hangi elektroterapi duyusal düzeyde uyarıyla esas olarak ağrı giderme amacı taşır?","options":["FES","TENS","NMES","Ultrason"],"answer":1,"exp":"TENS ağrı giderme amacıyla duyusal sinirleri cilt üzerinden uyarır. NMES kas kontraksiyonu oluşturur, FES hareketi destekler."},{"level":"Temel","q":"Hangi elektroterapi kası harekete (ör. yürüme) zamanlanmış olarak uyarıp işlevi ikame eder?","options":["TENS","Ultrason","FES","Sıcak paket"],"answer":2,"exp":"FES (fonksiyonel elektriksel stimülasyon) kasları hareketin ritmine göre uyarır ve işlevi ikame eder, ör. düşük ayakta yürüme sırasında."},{"level":"Orta","q":"Elektroterapinin kontrendikasyonu hangisidir?","options":["Kronik bel ağrısı","Ameliyat sonrası kas güçsüzlüğü","Düşük ayak","İmplante kalp pili"],"answer":3,"exp":"İmplante elektronik cihazlar uyarı akımı nedeniyle hatalı çalışabilir, bu yüzden kontrendikasyondur. Diğer seçenekler endikasyondur."},{"level":"Orta","q":"Derinde düşük frekanslı uyarı oluşturmak için iki orta frekanslı akımı çaprazlayan yöntem hangisidir?","options":["İnterferansiyel akım","TENS","FES","İyontoforez"],"answer":0,"exp":"İnterferansiyel akım farklı frekanslı iki orta frekanslı akımı çaprazlar; farklarına karşılık gelen düşük frekanslı uyarı derinde oluşur."},{"level":"Klinik","q":"Diz protezi sonrası kuadrisepsin istemli kontraksiyonu zayıf. Uygun seçim hangisidir?","options":["Yalnızca sıcak uygulama","Aktif egzersizle birlikte NMES","Ameliyat yarasına elektrot","Kontraksiyon dönene kadar istirahat"],"answer":1,"exp":"NMES, ameliyat sonrası kuadriseps kontraksiyon yetersizliğinde aktif egzersizle birlikte kullanılır. Elektrodu yaradan uzak yerleştirin."},{"level":"Klinik","q":"Elektriksel uyarı sonrası elektrot bölgesinde kızarıklık ve kabarcık görülüyor. Ne yaparsınız?","options":["Daha yüksek şiddetle devam edersiniz","Aynı yere yeniden yapıştırırsınız","Durur, cildi inceler ve bildirirsiniz","Isıtarak beklersiniz"],"answer":2,"exp":"Elektrot altındaki kızarıklık ve kabarcık cilt hasarına işaret edebilir. Tedaviyi durdurun, cilt durumunu kaydedin ve bildirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"Ultrason, Lazer, Sıcak ve Soğuk Uygulama","lead":"Isı, ses dalgası, ışık veya soğutmayla ağrı ve doku durumu üzerine etki eder. Faza ve amaca göre ısıtma ya da soğutmaya karar verir, kontrendikasyonları kontrol edersiniz.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Ağrı giderme, kas tonusunu azaltma, doku uzayabilirliğini artırma, akut inflamatuvar şişliği azaltma; terapötik egzersizden önce veya sonra."},{"h":"Ana teknikler ve türler","t":"Ultrason (sürekli, pulsatil), düşük güçlü lazer, yüzeyel sıcak (sıcak paket, parafin), mikrodalga diatermi, soğuk uygulama (buz paketi vb.)."},{"h":"Endikasyonlar","t":"Sıcak: kronik ağrı, sertlik, kontraktür; soğuk: akut yaralanma sonrası ağrı ve şişlik; ultrason: diğerlerinin yanında yumuşak doku uzayabilirliğini artırma."},{"h":"Kontrendikasyon, dikkat","t":"Sıcaktan akut inflamasyonda, kanama eğiliminde, tümörlü alanda; ultrasondan gözde, gebe karnında, büyüme kıkırdağında; soğuktan Raynaud fenomeni olan alanda kaçının."},{"h":"Uygulama ipuçları","t":"Tedaviden önce cildi ve sıcak-soğuk duyusunu kontrol edin, uygulama sırasında da cildi izleyin. Ultrason başlığını sürekli hareket ettirin, bir noktada durmayın."},{"h":"Kanıt","t":"Terapötik egzersize ek olarak kısa süreli ağrı giderme için kullanılır. Çoğu çalışmaya göre tek başına etkisi sınırlıdır; ana unsur egzersiz tedavisidir."}]},"keypoints":["Akut şişlik ve ısı artışında soğuk, kronik sertlikte sıcak","Önce sıcak-soğuk duyusunu kontrol edin, duyu bozukluğu olan alandan kaçının","Ultrason başlığını durmadan hareket ettirin","Sıcak uygulamadan sonra germe ve egzersiz iyi bir eşleşmedir","Fiziksel ajanlar egzersiz tedavisinin tamamlayıcısıdır"],"case":{"text":"22 yaşında erkek, futbol oynarken inversiyon tipi ayak bileği burkulması; yaralanmanın ertesi günü. Lateral malleol çevresinde şişlik, ısı artışı ve hassasiyet, yük vermede şiddetli ağrı. Hekim kırığı dışlamış.","answer":"Akut inflamasyon bulguları var; soğuk uygulama, kompresyon ve elevasyonla ağrıyı ve şişliği azaltın. Bu fazda sıcak şişliği artırabilir, kaçının. Soğuk yanığını önlemek için uygulama sırasında cildi izleyin."},"questions":[{"level":"Temel","q":"Akut şişlik ve ağrıyı azaltmak için hangi fiziksel ajanı kullanırsınız?","options":["Sıcak paket","Parafin","Soğuk uygulama","Mikrodalga diatermi"],"answer":2,"exp":"Soğuk vazokonstriksiyon yapar, akut ağrıyı ve şişliği azaltır. Diğer seçenekler sıcak uygulamadır, akut inflamasyonda kaçınılmalıdır."},{"level":"Temel","q":"Hangisi yüzeyel sıcak uygulamalardandır?","options":["Mikrodalga diatermi","Sıcak paket","Sürekli ultrason","Düşük güçlü lazer"],"answer":1,"exp":"Sıcak paket ve parafin ciltten itibaren yüzeyel dokuları ısıtır. Mikrodalga diatermi ve sürekli ultrason derin ısıtıcılardır."},{"level":"Orta","q":"Hangi bölge ultrason uygulaması için kontrendikedir?","options":["m. quadriceps femoris","Omuz çevresi","m. triceps surae","Göz küresi"],"answer":3,"exp":"Göz küresi ultrason için kontrendike bölgedir. Ayrıca gebe karnı, büyüme kıkırdağı ve tümörlü alandan da kaçınılmalıdır."},{"level":"Orta","q":"Ultrason uygulamasının doğru yöntemi hangisidir?","options":["Başlığı sürekli hareket ettirirsiniz","Başlığı bir noktada tutarsınız","Jelsiz uygularsınız","Ağrı olsa da devam edersiniz"],"answer":0,"exp":"Başlık bir yerde durursa ısı yoğunlaşır ve doku hasarı yapabilir; bu yüzden jelle, sürekli hareket ettirerek uygulanır."},{"level":"Klinik","q":"Ayak bileği burkulması, yaralanmanın ertesi günü: belirgin şişlik ve ısı artışı. Uygun fiziksel ajan hangisidir?","options":["Sıcak paket","Soğuk, kompresyon, elevasyon","Parafin","Mikrodalga diatermi"],"answer":1,"exp":"Akut inflamasyon bulgularında soğuk, kompresyon ve elevasyonla ağrıyı ve şişliği azaltın. Sıcak şişliği artırabilir."},{"level":"Klinik","q":"Diyabetik nöropati nedeniyle ayakta duyu azalmış; ayağa sıcak paket planlanıyor. Ne yaparsınız?","options":["Daha yüksek ısıda, kısa süre uygularsınız","Her zamanki gibi uygularsınız","Duyusu azalmış alana sıcak uygulamazsınız","Uyku sırasında uzun süre uygularsınız"],"answer":2,"exp":"Duyu bozukluğu olan alan sıcağı iyi algılamaz, yanık riski yüksektir. Sıcak uygulamadan kaçının ve başka bir yöntem seçin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"Hidroterapi, Masaj ve Manuel Lenf Drenajı","lead":"Hidroterapi suyun kaldırma kuvvetini, basıncını ve sıcaklığını kullanır; masaj ve manuel lenf drenajı yumuşak dokulara elle etki eder. Anahtar, endikasyon ve kontrendikasyonların doğru tartılmasıdır.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Hidroterapi kaldırma kuvveti, su basıncı ve ısıyla hareketi ve ağrı gidermeyi destekler. Masaj kas tonusunu azaltır, manuel lenf drenajı lenfödemi azaltır."},{"h":"Ana teknikler ve türler","t":"Girdap banyosu, Hubbard tankı, havuz egzersizleri. Masaj: sıvazlama, yoğurma, bası vb. Lenfödemde kompleks dekonjestif terapi (cilt bakımı, manuel drenaj, kompresyon, egzersiz)."},{"h":"Endikasyonlar","t":"Yük kısıtlaması gerektiren eklem hastalıkları ve ameliyatlar sonrası, ağrı ve artmış kas tonusu, sekonder lenfödem (ör. kanser ameliyatı sonrası), primer lenfödem."},{"h":"Kontrendikasyon, dikkat","t":"Ateş, akut enfeksiyon (ör. selülit), akut derin ven trombozu, açık yara, dekompanse kalp yetmezliği. Suda hidrostatik basınç kalbin yükünü artırır."},{"h":"Uygulama ipuçları","t":"Lenf drenajına ödemli alanın proksimalinden, yalnızca cildi kaydıran hafif basınçla başlayın. Su egzersizinde su ısısını, süreyi, genel durumu ve vital bulguları kontrol edin."},{"h":"Kanıt","t":"Lenfödemde kompresyonu da içeren kompleks terapi önerilir. Masajın tek başına etkisi sınırlıdır, bu yüzden terapötik egzersizle birlikte uygulanır."}]},"keypoints":["Kaldırma kuvveti yüklenmeyi kolaylaştırır; yük su derinliğiyle değişir","Hidrostatik basınç venöz dönüşü destekler ama kalbi yükler","Lenf drenajına proksimalden, hafif basınçla başlayın","Kızarıklık, ısı artışı, ateş: enfeksiyondan şüphelenin, durun","Lenfödemde kompresyonu da içeren kompleks terapi"],"case":{"text":"65 yaşında kadın. Meme kanseri ameliyatı sonrası sekonder lenfödem; etkilenen üst ekstremitenin çevresi sağlam taraftan büyük. Kızarıklık, ısı artışı veya ateş yok, derin ven trombozu tanısı konmamış.","answer":"Enfeksiyon ve tromboz belirtisi olmadan kompleks terapi endikedir. Cilt bakımı, proksimalden başlanan hafif basınçlı manuel drenaj, kompresyon ve kompresyon altında egzersizi birleştirin. Kızarıklık veya ateşte durun ve hekime yönlendirin."},"questions":[{"level":"Temel","q":"Suyun hangi özelliği eklemlere binen vücut ağırlığı yükünü azaltır?","options":["Kaldırma kuvveti","Viskozite","Özgül ısı","Yüzey gerilimi"],"answer":0,"exp":"Kaldırma kuvveti vücut ağırlığına zıt yönde etki eder ve yükü azaltır. Viskozite harekete karşı dirençtir, özgül ısı ısı etkisiyle ilgilidir."},{"level":"Temel","q":"Manuel lenf drenajında önce hangi bölgeyi tedavi edersiniz?","options":["Ödemin en belirgin distal kısmını","Ödemli alanın daha proksimalini","El ve ayak parmak uçlarını","Yalnızca en ağrılı kısmı"],"answer":1,"exp":"Önce proksimal kısmı (lenf düğümleri, gövde tarafı) drene ederek yol açarsınız, sonra distale ilerlersiniz."},{"level":"Orta","q":"Manuel lenf drenajının en tipik kontrendikasyonu hangisidir?","options":["Kronik sekonder lenfödem","İdame fazında üst ekstremite lenfödemi","Akut derin ven trombozu","Hafif cilt kuruluğu"],"answer":2,"exp":"Akut derin ven trombozunda trombüs yerinden kopabilir, bu yüzden kontrendikedir. Kronik lenfödem endikasyondur, cilt kuruluğu cilt bakımıyla yönetilir."},{"level":"Orta","q":"Hangisi lenfödemin kompleks terapisinin parçası DEĞİLDİR?","options":["Cilt bakımı","Manuel lenf drenajı","Kompresyon tedavisi","Etkilenen ekstremitenin uzun süre istirahati"],"answer":3,"exp":"Kompleks terapinin öğeleri: cilt bakımı, manuel drenaj, kompresyon ve kompresyon altında egzersiz. Uzun süreli immobilizasyon bunun parçası değildir."},{"level":"Klinik","q":"60'lı yaşlarda kadın, meme kanseri cerrahisi sonrası kol ödemi. Drenajda ekstremitede ani kızarıklık, ısı artışı ve ateş başlıyor. Ne yaparsınız?","options":["Drenaj basıncını artırırsınız","Tedaviyi bırakır, hekime bildirirsiniz","Sıcak uygulama eklersiniz","Daha güçlü kompresyonla devam edersiniz"],"answer":1,"exp":"Akut enfeksiyona (ör. selülit) işaret eden bulgular. Drenajı, kompresyonu ve sıcak uygulamayı durdurun, gecikmeden hekime yönlendirin."},{"level":"Klinik","q":"70'li yaşlarda erkek, kalp yetmezliği, istirahatte de nefes darlığı var. Havuz egzersizi düşünüyorsunuz. Doğru karar hangisidir?","options":["Kalp yükü artar, hekimle görüşün","Kaldırma kuvveti sayesinde kısıtlamasız yapılabilir","Derin suda, uzun süre yapın","Daha sıcak suda yapın"],"answer":0,"exp":"Suda hidrostatik basınç venöz dönüşü ve kalbin yükünü artırır. Stabil olmayan kalp yetmezliğinde endikasyonu hekimle görüşün."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"Kinezyo Bantlama","lead":"Duyusal uyarı vermek ve eklem hareketini desteklemek için cilde elastik bant yapıştırılır. Uygulama temellerini ve cilt sorunlarının önlenmesini bilin; terapötik egzersizin tamamlayıcısı olarak kullanın.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Cilt aracılığıyla duyusal uyarıyla kas aktivitesini destekler, eklem hareketini yönlendirir, postür farkındalığını artırır; ödem ve morluğun azalmasına yardımcı olabilir. Güçlü sabitleme amaç değildir."},{"h":"Ana teknikler ve türler","t":"Şekiller: I, Y, X ve yelpaze (lenf). Kasa, eklem desteğine ve ödeme yönelik uygulamalar vardır. Sabitleme için elastik olmayan (rijit) bant kullanılır."},{"h":"Endikasyonlar","t":"Terapötik egzersizle birlikte: spor yaralanması sonrası ağrı ve şişliğin azalmasına destek, kas kullanımının yeniden öğrenilmesi, postür ve aks farkındalığı."},{"h":"Kontrendikasyon, dikkat","t":"Cilt hasarı, enfeksiyon, egzama, önceki bant alerjisi, derin ven trombozu şüphesi, hassas ciltli yaşlı. Duyu bozukluğu olan alanda cilt sorunu zor fark edilir."},{"h":"Uygulama ipuçları","t":"Cilt temiz ve kuru olmalı, köşeleri yuvarlak kesin. İki ucu gerilmeden yapıştırın. Önce küçük parçayla deneyin; kaşıntı veya kızarıklıkta hemen çıkarmasını isteyin."},{"h":"Kanıt","t":"Çoğu çalışmaya göre ağrı üzerine etkisi kısa süreli ve sınırlıdır; bu yüzden tek başına tedavi değil, terapötik egzersizin tamamlayıcısıdır."}]},"keypoints":["Elastik bantın amacı destektir, sabitleme değil","İki ucu gerilmeden cilde yatırın","Temiz, kuru cilt; köşeleri yuvarlak kesin","Kaşıntı veya kızarıklıkta hemen çıkarılmalı","Etkisi sınırlıdır, terapötik egzersizle birleştirin"],"case":{"text":"22 yaşında erkek, inversiyon tipi ayak bileği burkulmasından 3 gün sonra. Lateral malleol çevresinde şişlik ve morluk var, yük vermede hafif ağrı. Daha önce hiç bantlanmamış, cilt hastalığı yok.","answer":"Önce cilt durumuna bakın ve küçük bir deneme parçası yapıştırın. Şişliğe az gerilimle yelpaze bant uygulayın, terapötik egzersizle birlikte. Bantın iyileştireceğini söylemeyin; kaşıntı veya kızarıklıkta çıkarmasını isteyin."},"questions":[{"level":"Temel","q":"Elastik bantın iki ucunu hangi gerilimle yapıştırırsınız?","options":["Maksimum gererek","Yalnızca uçları kuvvetle gererek","Gerilimsiz","Cildi sıkıştırarak"],"answer":2,"exp":"İki ucu (çapayı) gerilmeden cilde yatırırsınız. Uçlardaki gerilim cildi çeker; bantın kalkmasına ve cilt tahrişine yol açar."},{"level":"Temel","q":"Bantın iki kola kesilip kas karnını çevrelediği şekil hangisidir?","options":["I bant","X bant","Yelpaze bant","Y bant"],"answer":3,"exp":"Y bantın tabanı bir noktaya sabitlenir, iki kolla kas karnı çevrelenir. Yelpaze bant ince şeritlere kesilerek ödem üzerine yayılır."},{"level":"Orta","q":"Bantlamadan sonra hangi bulguda bant hemen çıkarılmalıdır?","options":["Uygulama yerinde kaşıntı veya kızarıklık","Egzersiz sonrası hafif kas gerginliği","Postürüne daha kolay dikkat etmesi","Hareketi daha hafif hissetmesi"],"answer":0,"exp":"Kaşıntı ve kızarıklık cilt tahrişinin (ör. bant alerjisi) belirtisidir. Kötüleşmeyi önlemek için hemen çıkarmasını isteyin."},{"level":"Orta","q":"Eklem hareketini güçlü biçimde kısıtlamak, sabitlemek istiyorsanız ne seçersiniz?","options":["Elastik bant, I şekli","Elastik olmayan (rijit) bant","Elastik bant, yelpaze şekli","Gerilimsiz Y şekli"],"answer":1,"exp":"Güçlü sabitleme için elastik olmayan bant gerekir. Elastik bant hareketi çok az kısıtlar; amacı destek ve duyusal uyarıdır."},{"level":"Klinik","q":"20'li yaşlarda erkek, ayak bileği burkulması sonrası şişliğe bantlama planlıyorsunuz. Uygulamadan önce en önemli kontrol nedir?","options":["Yürüme hızı","İstirahat nabzı","Cilt durumu ve önceki bant alerjisi","Baskın ayak"],"answer":2,"exp":"Uygulamadan önce cilt hasarını, egzamayı ve önceki bant alerjisini kontrol edin. Cilt sorunu varsa bantlamayın."},{"level":"Klinik","q":"30'lu yaşlarda kadın omuz bantlamasından sonra \"daha az ağrıyor\" diyor. Ona ne söylersiniz?","options":["Doku yenilendi, iyileştiniz","Etki çoğu kez geçicidir, egzersizle birlikte gerekir","Sürekli takmanız gerekir","Kas kuvvetiniz hemen arttı"],"answer":1,"exp":"Bantlamanın etkisi kısa süreli ve sınırlıdır. Aşırı beklenti yaratmayın; terapötik egzersizin tamamlayıcısı olduğunu açıklayın."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Teknikler ve fizik tedavi ajanları","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"Terapötik Egzersizler","lead":"Fizyoterapinin özü: reçete edilen egzersizlerle kas kuvveti, esneklik, dayanıklılık ve denge geliştirilerek ADL iyileştirilir. Güvenli ilerleme için yükleme ilkelerini ve sonlandırma kriterlerini bilin.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Temel hareketleri, ADL'yi ve katılımı iyileştirmek için EHA, kas kuvveti, kas ve genel dayanıklılık, esneklik, denge ve koordinasyonu geliştirmek."},{"h":"Ana teknikler ve türler","t":"EHA egzersizi (pasif, aktif yardımlı, aktif), kuvvetlendirme (izometrik, izotonik – konsantrik, eksantrik –, izokinetik), germe, aerobik egzersiz, denge ve koordinasyon egzersizi."},{"h":"Endikasyonlar","t":"Geniş kapsamlı: kas-iskelet sistemi hastalıkları, ameliyat sonrası, nörolojik ve dahili hastalıklar, hareketsizlik sendromu, yaşa bağlı işlev kaybı."},{"h":"Kontrendikasyon, dikkat","t":"Stabil olmayan kalp hastalığı, kontrolsüz hipertansiyon, akut inflamasyon, tespit edilmemiş kırık: dikkat veya kontrendikasyon. Egzersiz sonlandırma kriterlerini kontrol edin."},{"h":"Uygulama ipuçları","t":"Yükü aşırı yüklenme, özgüllük ve geri dönüşümlülük ilkelerine göre ayarlayın; algılanan zorluğu ve vital bulguları izleyin. Kompansasyonu fark edin; nefes tutmasın."},{"h":"Kanıt","t":"Birçok kas-iskelet ve kronik hastalıkta terapötik egzersiz tedavinin önerilen temelidir. Etki, programın uzun süre sürdürülebilmesine bağlıdır."}]},"keypoints":["Yükü aşırı yüklenme, özgüllük ve geri dönüşümlülük ilkelerine göre kurun","Erken postoperatif dönemde eklemi hareket ettirmeyen izometrik egzersizle başlayın","Nefes tutmaktan (ıkınmadan) kaçının, sürekli nefes alsın","Kompansasyonu fark edin, doğru hareketle çalışsın","Göğüs ağrısı, soğuk terleme, şiddetli nefes darlığı: hemen durun, bildirin"],"case":{"text":"72 yaşında kadın, diz protezinden 3 hafta sonra. M. quadriceps kas gücü 3: tam hareket açıklığında aktif hareket ettiriyor ama dirence dayanamıyor. Vital bulguları stabil.","answer":"Yer çekimine karşı aktif hareketle başlayın, sonra kademeli olarak hafif direnç ekleyin. Kompansasyonu ve ağrıyı izleyin, nefes tutmaktan kaçının. İlk gün maksimum yük vermeyin."},"questions":[{"level":"Temel","q":"Kasın uzarken gerim ürettiği kontraksiyon türü hangisidir?","options":["Konsantrik kontraksiyon","Eksantrik kontraksiyon","İzometrik kontraksiyon","İzokinetik kontraksiyon"],"answer":1,"exp":"Eksantrik kontraksiyonda kas uzarken kuvvet üretir. Konsantrikte kısalırken, izometrikte boy değişimi olmadan."},{"level":"Temel","q":"Kas kuvvetini artırmak için günlük olandan daha büyük yük verilmesi hangi ilkedir?","options":["Özgüllük ilkesi","Geri dönüşümlülük ilkesi","Aşırı yüklenme ilkesi","Bireyselleştirme ilkesi"],"answer":2,"exp":"Aşırı yüklenme ilkesine göre adaptasyon, alışılmış yükü aşan uyaranla gerçekleşir."},{"level":"Orta","q":"Hangi egzersiz eklem hareketi olmadan kuvvetlendirir ve bu yüzden ameliyattan sonra erken dönemde kullanışlıdır?","options":["İzometrik egzersiz","İzokinetik egzersiz","Sıçrama egzersizi","Yüksek yüklü eksantrik egzersiz"],"answer":0,"exp":"İzometrik egzersizde kas eklemi hareket ettirmeden kasılır; eklemi ve yarayı korur, bu yüzden erken dönemde yapılabilir."},{"level":"Orta","q":"Kuvvetlendirme egzersizi sırasında neden kaçınılmalıdır?","options":["Sürekli nefes almaktan","Kompansasyonu kontrol etmekten","Isınmadan","Nefes tutmaktan"],"answer":3,"exp":"Nefes tutma (ıkınma) kan basıncını aniden yükseltir. Özellikle yaşlılarda ve kalp hastalarında sürekli nefes alınmalıdır."},{"level":"Klinik","q":"70'li yaşlarda erkek, m. quadriceps kas gücü 3. Kuvvetlendirmeye nasıl başlarsınız?","options":["Maksimum dirençli izokinetik egzersizle","Yer çekimine karşı aktif hareket, kademeli yük","Yalnızca pasif hareketle","Yüksek yoğunluklu sıçrama egzersiziyle"],"answer":1,"exp":"Kas gücü 3, yer çekimine karşı tam açıklıkta hareket ettirebildiği anlamına gelir. Aktif hareketle başlayın ve kademeli olarak hafif direnç ekleyin."},{"level":"Klinik","q":"60'lı yaşlarda erkek, sabit bisiklette göğüs ağrısı ve soğuk terleme başlıyor. Ne yaparsınız?","options":["Durdurur, vitalleri ölçer, hekime bildirirsiniz","Yükü azaltıp devam edersiniz","Dinlendikten sonra aynı yükle devam edersiniz","Germeye geçersiniz"],"answer":0,"exp":"Göğüs ağrısı ve soğuk terleme sonlandırma kriteridir, kalp hastalığına işaret edebilir. Hemen durdurun, vitalleri ölçün ve hekime bildirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"Köprü","rotulo":"Güçlendirdiği kaslar","texto":"gluteal kaslar ve hamstringler","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"Düz bacak kaldırma","rotulo":"Güçlendirdiği kas","texto":"kuadriseps","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"Squat","rotulo":"Güçlendirdiği kaslar","texto":"kuadriseps ve gluteal kaslar","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"Solunum Fizyoterapisi","lead":"Solunum tekniklerinin öğretimi, sekresyon atılımının desteklenmesi ve terapötik egzersizle ventilasyonu iyileştirir, nefes darlığını azaltır. KOAH'ta ve postoperatif akciğer komplikasyonlarının önlenmesinde merkezi rol oynar.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Ventilasyonu iyileştirmek, hava yolu temizliğini desteklemek, nefes darlığını azaltmak, egzersiz kapasitesini ve ADL'yi artırmak, postoperatif akciğer komplikasyonlarını önlemek."},{"h":"Ana teknikler ve türler","t":"Büzük dudak solunumu, diyafram solunumu, postüral drenaj, huffing ve öksürük eğitimi, solunum desteği, solunum kası eğitimi, genel dayanıklılık ve kuvvetlendirme egzersizleri."},{"h":"Endikasyonlar","t":"Kronik solunum hastalıkları (ör. KOAH), pnömoni, toraks ve karın ameliyatı öncesi ve sonrası, nöromüsküler hastalığa bağlı ventilasyon bozukluğu, bol sekresyonlu bronşektazi."},{"h":"Kontrendikasyon, dikkat","t":"Artmış kafa içi basınç, stabil olmayan dolaşım, hemoptizide baş aşağı drenajdan kaçının. Tedavi edilmemiş pnömotoraks ve ağır aritmiye dikkat; SpO2'yi ve bulguları izleyin."},{"h":"Uygulama ipuçları","t":"Sekresyonun yerini oskültasyon ve görüntülemeyle belirleyip pozisyonu buna göre seçin. SpO2, solunum sayısı, nabız ve modifiye Borg ölçeğini izleyin; hareketi solunum ritmine uydurun."},{"h":"Kanıt","t":"KOAH'ta nefes darlığını azaltmak ve egzersiz kapasitesini artırmak için terapötik egzersize dayalı pulmoner rehabilitasyon önerilir."}]},"keypoints":["Büzük dudak solunumu ekspirasyonda hava yolu kollapsını önler","Postüral drenajda sekresyonlu akciğer segmenti üstte olmalı","Huffing: glottis açık, güçlü ve hızlı ekspirasyon","Artmış kafa içi basınç ve hemoptizide baş aşağı pozisyondan kaçının","KOAH'ta pulmoner rehabilitasyonun temeli terapötik egzersizdir"],"case":{"text":"74 yaşında erkek, KOAH, ev oksijen tedavisi yok. Yürürken ve giyinirken şiddetli nefes darlığı; aceleyle yapılan hareketten sonra SpO2 düşüyor. Sekresyonu az, istirahat durumu stabil.","answer":"Büzük dudak solunumunu ve hareket temposunu ayarlamayı öğretin; sonra SpO2 ve nefes darlığını izleyerek dayanıklılık ve alt ekstremite kuvvetlendirme egzersizleri yaptırın. Nefesini tutarak acele etmemesini isteyin."},"questions":[{"level":"Temel","q":"KOAH'ta ekspirasyonda hava yolu kollapsını önlemek için hangi solunum tekniğini öğretirsiniz?","options":["Hızlı, yüzeyel göğüs solunumu","Nefes tutma","Büzük dudak solunumu","Hiperventilasyon"],"answer":2,"exp":"Büzük dudak solunumu ekspirasyona direnç verir, hava yolu basıncını korur, kollapsı önler ve ekspirasyonu kolaylaştırır."},{"level":"Temel","q":"Yer çekimi sekresyonu hareket ettirsin diye sekresyonlu segmenti üste aldığınız yöntem hangisidir?","options":["Huffing","Postüral drenaj","Solunum kası eğitimi","Büzük dudak solunumu"],"answer":1,"exp":"Postüral drenajda sekresyonlu segment üstte olur ve yer çekimi sekresyonu santral hava yollarına doğru hareket ettirir."},{"level":"Orta","q":"Glottis açıkken güçlü ve hızlı ekspirasyonla sekresyonu hareket ettiren teknik hangisidir?","options":["Öksürüğü bastırma","Diyafram solunumu","Valsalva manevrası","Huffing"],"answer":3,"exp":"Huffing glottis açık yapılan zorlu ekspirasyondur; öksürüğe göre daha az göğüs içi basınç artışıyla sekresyonu hareket ettirir."},{"level":"Orta","q":"Hangi durumda baş aşağı postüral drenajdan kaçınılmalıdır?","options":["Artmış kafa içi basınç","Kronik bronşektazi","Bol sekresyonlu pnömoni","Alt lob atelektazisi"],"answer":0,"exp":"Baş aşağı pozisyon kafa içi basıncı artırır, bu yüzden artmış kafa içi basınçta kaçınılır. Diğer durumlar drenaj endikasyonu olabilir."},{"level":"Klinik","q":"70'li yaşlarda erkek, KOAH. Yürürken nefes darlığı artıyor ve SpO2 düşüyor. Ne öğretirsiniz?","options":["Çabuk bitirmek için hızlı yürüsün","Büzük dudak solunumu ve hareket temposunu ayarlama","Nefesini tutarak hareket etsin","Yürümeyi tamamen bıraksın"],"answer":1,"exp":"Hareket temposunu solunuma uydursun ve büzük dudak solunumu kullansın. Tam hareketsizlik dekondisyonu hızlandırır."},{"level":"Klinik","q":"Karın ameliyatı sonrası 1. gündeki hasta. Postoperatif akciğer komplikasyonlarını önlemede ne yardımcı olur?","options":["Birkaç gün yatak istirahati","Ağrı nedeniyle solunum egzersizini atlamak","Erken mobilizasyon, derin solunum ve öksürük eğitimi","Uzun süre baş aşağı pozisyon"],"answer":2,"exp":"Erken mobilizasyon ve derin solunum ile öksürük (yarayı destekleyerek) eğitimi atelektazi ve pnömoniyi önlemede önemlidir."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"Kardiyak Rehabilitasyon","lead":"Terapötik egzersiz, hasta eğitimi ve yaşam tarzı danışmanlığını birleştiren kapsamlı program. Amaç egzersiz kapasitesini ve yaşam kalitesini artırmak, nüksü önlemektir. Güvenlik önce gelir.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Egzersiz kapasitesini ve yaşam kalitesini artırmak, koroner risk faktörlerini düzeltmek, nüksü ve yeniden yatışı önlemek, kaygıyı azaltmak, işe ve topluma dönüşü desteklemek."},{"h":"Ana teknikler ve türler","t":"Aerobik egzersiz (yürüme, sabit bisiklet), direnç egzersizi, hasta eğitimi, yaşam tarzı danışmanlığı (ilaç kullanımı, beslenme, sigarayı bırakma). Üç fazda ilerler: akut, rehabilitasyon, idame."},{"h":"Endikasyonlar","t":"Akut miyokard enfarktüsü sonrası, angina pektoris, kalp ameliyatı sonrası, kronik kalp yetmezliği, büyük damar hastalıkları, periferik arter hastalığı. Koşul stabil durumdur."},{"h":"Kontrendikasyon, dikkat","t":"Stabil olmayan angina, kontrolsüz aritmi, dekompanse kalp yetmezliği, semptomatik ağır aort stenozu, akut miyokardit: terapötik egzersiz kontrendikedir."},{"h":"Uygulama ipuçları","t":"Yoğunluğu kardiyopulmoner egzersiz testindeki anaerobik eşiğe (AT) veya algılanan zorluğa göre ayarlayın. Beta bloker altında nabız az artar: bulguları, kan basıncını ve EKG'yi de izleyin."},{"h":"Kanıt","t":"Koroner arter hastalığında ve kronik kalp yetmezliğinde kılavuzlar terapötik egzersizi de içeren kapsamlı kardiyak rehabilitasyonu önermektedir."}]},"keypoints":["Egzersiz, eğitim ve yaşam tarzı danışmanlığı birlikte","Yoğunluğu AT'ye veya algılanan zorluğa göre ayarlayın","Beta bloker altında yalnızca nabza göre karar vermeyin","Göğüs ağrısı, ST değişikliği, aritmi: durun","Ani kilo artışı, ödem: kalp yetmezliğinin kötüleşmesinden şüphelenin"],"case":{"text":"63 yaşında erkek, akut miyokard enfarktüsü tedavisinden sonra rehabilitasyon fazında ayaktan egzersiz yapıyor. Beta bloker kullanıyor. Sabit bisiklette göğüs yakınması yok ama nabzı neredeyse hiç artmıyor.","answer":"Beta bloker nabız yanıtını baskılar; yükü yalnızca nabza göre artırmayın, algılanan zorluk, kan basıncı ve EKG'ye göre karar verin. Göğüs ağrısı veya ST değişikliğinde durun ve hekime bildirin."},"questions":[{"level":"Temel","q":"Hangisi kardiyak rehabilitasyonun parçası DEĞİLDİR?","options":["Terapötik egzersiz","Hasta eğitimi","Koroner risk faktörlerinin düzeltilmesi","Uzun süreli yatak istirahati"],"answer":3,"exp":"Kardiyak rehabilitasyon egzersiz, hasta eğitimi, yaşam tarzı danışmanlığı ve psikolojik destek içeren kapsamlı bir programdır. Uzun yatak istirahati dekondisyona yol açar."},{"level":"Temel","q":"Yoğunluğu ayarlamak için kardiyopulmoner egzersiz testinden elde edilen hangi göstergeyi kullanırsınız?","options":["Manuel kas testi","Anaerobik eşik (AT)","Eklem hareket açıklığı","Kavrama kuvveti"],"answer":1,"exp":"Anaerobik eşik (AT), aerobik egzersiz yoğunluğunun yaygın bir göstergesidir; kardiyopulmoner egzersiz testiyle belirlenir."},{"level":"Orta","q":"Terapötik egzersizin kontrendikasyonu hangisidir?","options":["Stabil kronik kalp yetmezliği","Bypass sonrası rehabilitasyon fazı","Stabil olmayan angina","Enfarktüs sonrası stabil dönem"],"answer":2,"exp":"Stabil olmayan angina terapötik egzersizin kontrendikasyonudur. Stabil kronik kalp yetmezliği ve ameliyat ya da enfarktüs sonrası rehabilitasyon fazı endikasyondur."},{"level":"Orta","q":"Beta bloker kullanan hastada yoğunluğu değerlendirmek için ne yararlıdır?","options":["Algılanan zorluk (Borg ölçeği)","Yalnızca nabız","Vücut ağırlığı","Vücut sıcaklığı"],"answer":0,"exp":"Beta bloker nabız artışını baskılar; yalnızca nabza göre çok yüksek yük belirleyebilirsiniz. Algılanan zorluğu da kullanın."},{"level":"Klinik","q":"60'lı yaşlarda erkek, enfarktüs sonrası rehabilitasyon fazı. Yürüme egzersizinde göğüs ağrısı ve ST depresyonu oluyor. Ne yaparsınız?","options":["Yürüme hızını artırırsınız","Devam eder ve izlersiniz","Sıvı verip aynı yükle sürdürürsünüz","Egzersizi durdurur, hekime bildirirsiniz"],"answer":3,"exp":"Göğüs ağrısı ve ST depresyonu miyokard iskemisine işaret eden durdurma belirtisidir. Egzersizi hemen durdurun ve hekime bildirin."},{"level":"Klinik","q":"70'li yaşlarda kadın, kronik kalp yetmezliği. Birkaç günde kilosu aniden arttı, bacak ödemi ve nefes darlığı kötüleşti. Ne yaparsınız?","options":["Yoğunluğu artırırsınız","Kötüleşme şüphesiyle hekime bildirirsiniz","Her zamanki gibi egzersiz yaptırırsınız","Yalnızca kuvvetlendirme eklersiniz"],"answer":1,"exp":"Kısa sürede kilo artışı, ödem ve artan nefes darlığı kalp yetmezliğinin kötüleşme belirtisidir. Egzersizi erteleyin ve hekime bildirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"Pelvik Taban ve Kadın Sağlığı","lead":"Pelvik taban kas disfonksiyonundan kaynaklanan üriner inkontinans, pelvik organ prolapsusu, gebelik ve doğum sonrası bedensel değişikliklerle ilgilenir. Temel: doğru kontraksiyonu öğretmek ve kırmızı bayrakları taramak.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Pelvik taban kaslarının kuvvet, dayanıklılık ve koordinasyonunu geliştirmek, inkontinans ve prolapsusu hafifletmek; gebelik ve doğum sonrası lumbopelvik ağrıyı ve gövde işlevini düzenlemek."},{"h":"Ana teknikler ve türler","t":"Pelvik taban egzersizleri, biofeedback, karın içi basınç ve solunum kontrolü eğitimi, postür ve hareket eğitimi, yaşam tarzı danışmanlığı (idrar alışkanlıkları, kilo kontrolü vb.)."},{"h":"Endikasyonlar","t":"Stres ve mikst inkontinans, hafif pelvik organ prolapsusu, doğum sonrası pelvik taban zayıflığı, diastasis recti, erkekte radikal prostatektomi sonrası inkontinans."},{"h":"Kontrendikasyon, dikkat","t":"İç (vajinal) muayene için uzmanlık eğitimi, ayrıntılı bilgilendirme ve onam gerekir. İleri gebelikte uzun sırtüstü yatış vena kava sendromu yapabilir. Hematüri, ateş, perine uyuşması: hekime."},{"h":"Uygulama ipuçları","t":"Sıkma ve yukarı çekme kontraksiyonunu kontrol edin; karın, kalça ve addüktör kaslarını kasmaktan ve ıkınmaktan kaçınsın. Hızlı ve sürekli kontraksiyonu, günlük hayatta sürdürülebilir şekilde çalışsın."},{"h":"Kanıt","t":"Stres inkontinansında pelvik taban egzersizleri konservatif tedavinin ilk seçeneğidir. Etki, hastanın egzersizi düzenli sürdürmesine bağlıdır."}]},"keypoints":["Pelvik taban kaslarını \"sıkın ve yukarı çekin\" komutuyla öğretin","Ikınma ve kalça kaslarını kasma kompansasyondur, kaçınılmalı","Öksürük ve hapşırıkta kaçırma: stres inkontinansı","İleri gebelikte uzun sırtüstü yatış kan basıncını düşürebilir","Ani idrar bozukluğu, perine uyuşması: hemen hekime"],"case":{"text":"38 yaşında kadın, doğumdan bir yıl sonra. Öksürürken ve hapşırırken idrar kaçırıyor. Mekik çekerken karın orta hattı kabarıyor. Hematüri, ateş veya perine bölgesinde duyu bozukluğu yok.","answer":"Stres inkontinansı ve diastasis recti düşünülür. Doğru pelvik taban kontraksiyonunu ve ıkınmadan karın içi basınç kontrolünü öğretin. Kuvvetli mekiklerin ani, çok sayıda tekrarından kaçının."},"questions":[{"level":"Temel","q":"Pelvik tabanın ana kası hangisidir?","options":["M. iliopsoas","M. gluteus maximus","M. levator ani","M. rectus femoris"],"answer":2,"exp":"M. levator ani, m. coccygeus ile birlikte diaphragma pelvis'i oluşturur ve pelvik tabanın ana kasıdır. Diğerleri kalça çevresi kaslarıdır."},{"level":"Temel","q":"Öksürük veya hapşırıkta karın içi basınç artınca idrar kaçırılan inkontinans türü hangisidir?","options":["Sıkışma (urge) inkontinansı","Stres inkontinansı","Taşma inkontinansı","Fonksiyonel inkontinans"],"answer":1,"exp":"Stres inkontinansında karın içi basınç artınca üretranın kapanması yetersiz kalır. Sıkışma inkontinansına güçlü idrar hissi eşlik eder."},{"level":"Orta","q":"Pelvik taban egzersizinde kontraksiyonu doğru nasıl öğretirsiniz?","options":["Nefes tutarak ıkınma","Kalça kaslarını kuvvetle sıkma","Karnı öne itme","Üretra, vajina, anüsü sıkıp yukarı çekme"],"answer":3,"exp":"Pelvik taban kaslarını sıkma ve yukarı çekme hareketiyle kassın. Ikınma, kalçayı kasma ve karnı öne itme kompansasyondur."},{"level":"Orta","q":"İleri gebelikte uzun süre sırtüstü yatışta neye dikkat edilmelidir?","options":["Vena kava sendromu (supin hipotansiyon)","Diastasis recti'nin düzelmesi","Pelvik taban kaslarının hipertrofisi","İnkontinansın geçmesi"],"answer":0,"exp":"İleri gebelikte sırtüstü yatışta uterus v. cava inferior'a bası yapar ve kan basıncı düşebilir. Örneğin yan yatış pozisyonuna çevirin."},{"level":"Klinik","q":"38 yaşında kadın, doğumdan bir yıl sonra öksürükle idrar kaçırıyor, mekikte karın orta hattı kabarıyor. Uygun girişim hangisidir?","options":["Her gün çok sayıda kuvvetli mekik","Pelvik taban egzersizi ve karın içi basınç kontrolü","Sıvı alımını aşırı kısıtlama","Yalnızca dinlenme önerisi"],"answer":1,"exp":"Stres inkontinansı ve diastasis recti olası. Doğru pelvik taban kontraksiyonu ve karın içi basınç kontrolüyle başlayın."},{"level":"Klinik","q":"50'li yaşlarda kadın bel ağrısı için tedaviye geliyor. Ani idrar yapma güçlüğü ve perine uyuşmasından söz ediyor. Ne yaparsınız?","options":["Pelvik taban egzersizini artırırsınız","Bir sonraki seansa kadar beklersiniz","Hemen hekime haber verirsiniz","Lomber germe yaparsınız"],"answer":2,"exp":"Ani idrar bozukluğu ve perine bölgesinde duyu bozukluğu kauda ekuina sendromuna işaret eden kırmızı bayraktır. Hemen hekime yönlendirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"Pediatrik Fizyoterapi","lead":"Gelişmekte olan çocuğun motor gelişimini, aktivitesini ve katılımını destekleyen alan. Normal gelişim bilgisine dayanır; oyunla ve aileyle iş birliği içinde ilerler.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"Motor gelişimi desteklemek, temel hareketleri ve mobiliteyi kazandırmak, ikincil bozuklukları (kontraktür, deformite) önlemek, evde, okul öncesinde ve okulda katılımı artırmak, aileyi desteklemek."},{"h":"Ana teknikler ve türler","t":"Nörogelişimsel yaklaşım, göreve yönelik pratik, oyun temelli hareket, pozisyonlama, ortezler, oturma destek araçları ve yürüteç kullanımı, aile eğitimi."},{"h":"Endikasyonlar","t":"Serebral palsi, gelişimsel gerilik, Down sendromu, spina bifida, Duchenne musküler distrofisi, düşük doğum ağırlıklı prematüreler, ortopedik hastalıklar."},{"h":"Kontrendikasyon, dikkat","t":"Spastik serebral palside kalça subluksasyonu ve çıkığının takibi önemlidir. Musküler distrofide yorgunluk bırakan yüksek yükten kaçının. Epileptik nöbetlere ve yorgunluğa dikkat edin."},{"h":"Uygulama ipuçları","t":"Değerlendirmede GMFM, GMFCS, primitif refleksler ve postüral reaksiyonları kullanın. Keyifli oyunla çalışın; evde de sürdürülebilmesi için günlük hedefleri aileyle paylaşın."},{"h":"Kanıt","t":"Net hedeflere dayalı göreve yönelik pratik ve aileyle iş birliği içindeki girişimler kanıtla desteklenir. Tek tek tekniklerden daha önemlisi günlük pratiktir."}]},"keypoints":["Baş kontrolünün beklenen zamanı 3–4 aylıktır","GMFCS serebral palside kaba motor becerileri 5 seviyede sınıflar","Spastik SP'de kalça çıkığını düzenli kontrol edin","Musküler distrofide yorgunluk bırakan yüksek yükten kaçının","Hedefi aileyle paylaşın, oyunla çalışın"],"case":{"text":"5 yaşında erkek, spastik dipleji. Evde yürüteçle hareket ediyor ama parmak ucuna basması dikkat çekiyor. Aile, \"anaokulunda arkadaşlarıyla birlikte dolaşabilmesini\" istiyor.","answer":"Ailenin isteği günlük hedef olsun: yürüteçle hareket pratiğini oyuna ve anaokulu etkinliklerine bağlayın. M. triceps surae kısalığını önleyin, ortezi değerlendirin ve kalçayı kontrol edin. Yalnızca normal gelişim sırasında ısrar etmeyin."},"questions":[{"level":"Temel","q":"Baş kontrolünün gelişmesi ne zaman beklenir?","options":["1 aylıkken","3–4 aylıkken","7–8 aylıkken","12 aylıkken"],"answer":1,"exp":"Baş kontrolü 3–4 aylık civarında beklenir. Bunu dönme, oturma, tutunarak ayakta durma ve bağımsız yürüme izler."},{"level":"Temel","q":"Serebral palsili çocuğun kaba motor becerisini 5 seviyede sınıflayan ölçek hangisidir?","options":["GMFM","MRC","FIM","GMFCS"],"answer":3,"exp":"GMFCS kaba motor beceriyi 5 seviyede sınıflar. GMFM kaba motor işlevi puanla ölçer."},{"level":"Orta","q":"Duchenne musküler distrofisinde hangi hareketten kaçınırsınız?","options":["Yorgunluk bırakan yüksek yüklü hareketten","EHA egzersizinden","Solunum egzersizinden","Oyun temelli hareketten"],"answer":0,"exp":"Kas lifleri kolay hasar görür, bu yüzden belirgin yorgunluk bırakan yüksek yükten kaçının. Kontraktür önleme ve solunum egzersizleri önemlidir."},{"level":"Orta","q":"Spastik serebral palside hangi komplikasyonun düzenli kontrolü önemlidir?","options":["Ön çapraz bağ yırtığı","Rotator manşet yırtığı","Kalça subluksasyonu, çıkığı","Ayak bileği burkulması"],"answer":2,"exp":"Kalça çevresi kaslarındaki spastisite ve dengesizlik nedeniyle kalça subluksasyonu ve çıkığı sıktır, bu yüzden düzenli kontrol gerekir."},{"level":"Klinik","q":"4 yaşında çocuk, spastik dipleji. Yürüme hedefini doğru nasıl belirlersiniz?","options":["Fizyoterapist tek başına karar verir","Aileyle birlikte günlük bir hedef koyarsınız","Kesinlikle yalnızca normal gelişim sırasına göre","Oyunsuz, yalnızca tekrarla çalıştırırsınız"],"answer":1,"exp":"Hedefi aileyle paylaşın ve somut ev, anaokulu etkinliklerine bağlayın. Oyun, pratiğin sürdürülebilir kalmasına yardım eder."},{"level":"Klinik","q":"7 yaşında erkek, Duchenne musküler distrofisi, merdivende giderek zorlanıyor. Doğru hareket yaklaşımı hangisidir?","options":["Yorgunluksuz aktivite, kontraktür önleme","Yüksek yüklü eksantrik kuvvetlendirme","Tüm hareketlerin yasaklanması","Her gün tam tükenene kadar yürütmek"],"answer":0,"exp":"Aşırı yük kas hasarını hızlandırabilir. Aktiviteyi yorgunluk bırakmayan düzeyde sürdürün ve kontraktür önlemeye devam edin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"Geriatrik Fizyoterapi","lead":"Odağında yaşlanmaya bağlı işlev kaybı, kırılganlık (frailty), sarkopeni ve düşmelerin yönetimi vardır. Değerlendirmeye dayanarak bağımsızlığını ve katılımını koruyup hareketi güvenle sürdürmesine yardım ederiz.","sheet":{"kind":"method","items":[{"h":"Amaç","t":"ADL, yaşam işlevleri ve katılımı korumak ve geliştirmek; düşmeleri önlemek; kırılganlık ve sarkopeniyi önlemek, iyileştirmek; hareketsizlik sendromunu önlemek; bakım verenlerin yükünü azaltmak."},{"h":"Ana teknikler ve türler","t":"Alt ekstremite ve gövde kuvvetlendirme, denge egzersizi, yürüme eğitimi, çift görevli pratik, oturma, ayağa kalkma ve transfer eğitimi, yardımcı cihaz seçimi, ev ortamı düzenlemesi."},{"h":"Endikasyonlar","t":"Kırılganlık, sarkopeni, önceki düşme, kırık veya ameliyat sonrası, kronik hastalığa bağlı hareketsizlik, hastanede yatışa bağlı dekondisyon, demansla yaşayanların aktivitesinin desteklenmesi."},{"h":"Kontrendikasyon, dikkat","t":"Ortostatik hipotansiyona, osteoporotik vertebra kırığına, polifarmasi yan etkilerine, dehidratasyona, hassas cilde ve bilişsel gerilemeye dikkat edin. Ani ağrı, bulgu değişikliği: hekim."},{"h":"Uygulama ipuçları","t":"TUG, tek ayak üstünde durma, sandalyeden kalkma, yürüme hızı, kavrama kuvvetiyle değerlendirin ve bireysel hedefler koyun. Yükü kademeli artırın, beslenmeyle birlikte sürekliliği teşvik edin."},{"h":"Kanıt","t":"Denge ve kuvvetlendirme öğeleri içeren egzersiz programları evde yaşayan yaşlılarda düşmeleri önlemede etkilidir. Uzun süre sürdürülebilir olması önemlidir."}]},"keypoints":["Fried kırılganlık kriterleri arasında yavaşlayan yürüme vardır","Sarkopeni: azalmış kas kütlesi ve kas kuvveti veya fiziksel işlev","Düşme önleme: denge ve kas kuvveti birlikte","Uzun yatıştan sonra mobilizasyonda ortostatik hipotansiyona dikkat edin","Osteoporozda ani sırt ağrısı vertebra kırığı açısından şüphelidir"],"case":{"text":"82 yaşında kadın, son bir yılda iki kez düşmüş. TUG süresi uzamış, sandalyeden ancak elleriyle destek alarak kalkıyor. Osteoporoz tedavisi görüyor, sırt ağrısı yok. Yalnız yaşıyor, evden nadiren çıkıyor.","answer":"Düşme riski yüksek. Denge egzersizini ve alt ekstremite kuvvetlendirmeyi kademeli olarak birleştirin, ev ortamını düzenleyin ve dışarı çıkma fırsatları yaratın. Dinlenme önermeyin ve ilk gün yüksek yük vermeyin."},"questions":[{"level":"Temel","q":"Hangisi Fried kırılganlık kriterleri arasındadır?","options":["Görme kaybı","Kan basıncı artışı","Yürüme hızında yavaşlama","Boy uzaması"],"answer":2,"exp":"Fried kriterlerinin 5 öğesi: kilo kaybı, tükenmişlik, azalmış aktivite, yavaşlayan yürüme ve azalmış kas kuvveti (kavrama kuvveti)."},{"level":"Temel","q":"Yaşlanmaya bağlı kas kütlesinin azaldığı ve kas kuvveti veya fiziksel işlevin bozulduğu durum hangisidir?","options":["Sarkopeni","Osteoporoz","Artroz","Ortostatik hipotansiyon"],"answer":0,"exp":"Sarkopenide kas kütlesi azalmasına kas kuvveti veya fiziksel işlevde bozulma eşlik eder. Osteoporoz kemik kütlesinin azalmasıdır."},{"level":"Orta","q":"TUG (Timed Up and Go testi) neyi ölçer?","options":["Kavrama kuvvetini","Kalkma, yürüme ve dönmeyi içeren hareketi","Yalnızca bilişsel işlevi","Solunum işlevini"],"answer":1,"exp":"TUG, hastanın sandalyeden kalkıp yürüyüp dönerek geri gelip oturma süresini ölçer; mobiliteyi ve düşme riskini değerlendirir."},{"level":"Orta","q":"Uzun yatıştan sonra yaşlı hastanın ilk oturma ve ayağa kalkışında özellikle neye dikkat edilmelidir?","options":["Rotator manşet yırtığı","Üşüme","Parmak kontraktürü","Ortostatik hipotansiyon"],"answer":3,"exp":"Uzun yatıştan sonra kan basıncı düzenlemesi bozulur; oturur ve ayağa kalkarken kan basıncı kolayca düşer. Bulguları ve kan basıncını izleyin."},{"level":"Klinik","q":"80'li yaşlarda kadın, önceden düşmüş, TUG süresi uzamış, alt ekstremite kuvveti azalmış. Uygun girişim hangisidir?","options":["Denge egzersizi ve alt ekstremite kuvvetlendirme","Yalnızca germe","Dinlenme önerisi","İlk günden maksimum yüklü kuvvetlendirme"],"answer":0,"exp":"Düşme önlemede denge ve kuvvetlendirme öğelerini birleştiren egzersiz etkilidir. Yükü kademeli artırın."},{"level":"Klinik","q":"85 yaşında kadın, osteoporoz. Hafif bir oturur pozisyonda düşmeden sonra ani şiddetli sırt ağrısı başlıyor. Ne yaparsınız?","options":["Gövde fleksiyon egzersizlerini artırırsınız","Sıcak uygulayıp beklersiniz","Görüntüleme için hekime yönlendirirsiniz","Sırt kası germesi yaparsınız"],"answer":2,"exp":"Osteoporozlu yaşlıda küçük travma sonrası ani sırt ağrısı vertebra kompresyon kırığı açısından şüphelidir. Egzersize devam etmeyin, hekime yönlendirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Egzersiz tedavisi ve uzmanlık alanları","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"Klinik Vakalar","lead":"Klinik akıl yürütme süreci: anamnezden hipotez kurar, muayeneyle doğrular, bulguları özetleyip yorumladıktan sonra hedefi ve tedaviyi belirlersiniz. Yeniden değerlendirmeyle sürekli gözden geçirirsiniz.","sheet":{"kind":"basics","items":[{"h":"Anamnez","t":"Ana yakınmayı, başlangıç ve seyri, ağrının yerini ve niteliğini, artıran ve azaltan etkenleri, özgeçmişi, ilaçları, yaşam koşullarını ve beklentileri sorun. Kırmızı bayrakları da tarayın."},{"h":"Hipotez oluşturma","t":"Anamneze dayanarak birden çok olası neden ve tabloyu toplayın, muayeneyle neyin doğrulanması gerektiğine karar verin. Hemen tek bir açıklamaya bağlanmayın."},{"h":"Muayene","t":"İnspeksiyon, palpasyon, EHA ölçümü, kas kuvveti testi, özel testler, nörolojik muayene ve hareket analiziyle hipotezi doğrulayın. Taraflar arası farka ve tekrarlanabilirliğe dikkat edin."},{"h":"Özet ve yorum","t":"Bulguları ICF çerçevesinde (vücut işlevleri, aktivite, katılım, çevre) düzenleyin; sorunlar arasındaki ilişkiyi ve öncelik sırasını düşünün."},{"h":"Hedef belirleme","t":"Hasta ve aileyle birlikte somut, ölçülebilir, süreli kısa ve uzun vadeli hedefler koyun. Günlük yaşam durumlarına bağlı hedefler önemlidir."},{"h":"Tedavi ve yeniden değ.","t":"Girişimi hedeflere göre seçin ve değişimi aynı göstergelerle yeniden değerlendirin. İyileşme yoksa hipoteze ve muayeneye geri dönün."}]},"keypoints":["Anamnez sırasında kırmızı bayrakları mutlaka tarayın","Birden çok hipotez kurun ve her birini muayeneyle doğrulayın","Sorunları ICF çerçevesinde düzenleyin","Hedef hastayla ortak, ölçülebilir ve süreli olmalı","İyileşme yoksa hipotez ve muayeneden başlayarak yeniden düşünün"],"case":{"text":"68 yaşında erkek, bilateral diz osteoartriti. Yürürken sağ dizi ağrıyor; sağ m. quadriceps zayıflamış, diz ekstansiyonu kısıtlı. İsteği: \"Torunumla yakındaki parka kadar yürümek istiyorum.\"","answer":"Ağrıyı, kas güçsüzlüğünü, hareket kısıtlılığını ve yürüme kısıtlılığını düzenleyin; parka kadar yürümeyi süreli bir hedef olarak koyun. Kuvvetlendirme ve EHA egzersizleri yapın, ağrı ve yürünen mesafeye göre yeniden değerlendirin. Yalnızca görüntüleme bulgusuna göre karar vermeyin."},"questions":[{"level":"Temel","q":"Klinik akıl yürütme sürecinde anamnezden sonra ne gelir?","options":["Tedaviye başlama","Hipotez kurma","Hedefin kesin olarak belirlenmesi","Taburculuk danışmanlığı"],"answer":1,"exp":"Anamnezden elde edilen bilgilere göre neden ve tablo hakkında hipotez kurar, bunu doğrulayacak muayeneleri seçersiniz."},{"level":"Temel","q":"Doğru hedef belirleme yolu hangisidir?","options":["Fizyoterapist tek başına karar verir","Soyut ifade","Süresiz","Ölçülebilir, süreli hedef"],"answer":3,"exp":"Hedef hasta ve aileyle ortak, somut, ölçülebilir ve süreli olmalıdır. Böylece yeniden değerlendirmede değişim yargılanabilir."},{"level":"Orta","q":"ICF'ye göre \"merdiven çıkamıyor\" ifadesini nereye yerleştirirsiniz?","options":["Aktivite","Katılım","Vücut işlevleri ve yapıları","Çevresel faktörler"],"answer":0,"exp":"Bireyin yaptığı eylem, örneğin merdiven çıkma, \"aktivite\" kapsamına girer. Toplumsal rollere katılım \"katılım\"dır."},{"level":"Orta","q":"Girişim sonrası yeniden değerlendirmede iyileşme yoksa ne yaparsınız?","options":["Aynı tedaviye devam edersiniz","Muayeneyi atlarsınız","Hipotezi ve muayeneyi gözden geçirirsiniz","Hastanın az çabasına bağlarsınız"],"answer":2,"exp":"İyileşme yoksa hipotezin ve muayenenin doğru olup olmadığını gözden geçirin, tablonun yorumunu ve girişimi yeniden düşünün."},{"level":"Klinik","q":"50'li yaşlarda erkek: elevasyonun orta açıklığında lateral omuz ağrısı, Hawkins-Kennedy testi pozitif, pasif EHA normal. Ne düşünürsünüz?","options":["Donuk omuz","Subakromiyal sıkışma","Servikal radikülopati","Torasik çıkış sendromu"],"answer":1,"exp":"Elevasyonun orta açıklığındaki ağrılı ark ve pozitif Hawkins-Kennedy testi subakromiyal sıkışmaya işaret eder. Donuk omuzda pasif EHA da kısıtlıdır."},{"level":"Klinik","q":"60'lı yaşlarda kadın, bel ağrısı; geçmişte kanser öyküsü, gece ağrısı ve açıklanamayan kilo kaybı var. Ne yaparsınız?","options":["Lomber egzersizlere başlarsınız","Manipülasyon yaparsınız","Sıcak uygulayıp beklersiniz","Hekimi bilgilendirir, tetkik istersiniz"],"answer":3,"exp":"Kanser öyküsü, gece ağrısı ve kilo kaybı ciddi hastalığa işaret eden kırmızı bayraklardır. Tedaviden önce hekime yönlendirin."}],"seccion":"Tedaviler ve uygulamalar","grupo":"Klinik vakalar","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
